"""One-click installer: recreates the whole youtube-automation-agents project.

Run from inside the youtube-automation-agents folder:
    python setup_project.py

Existing files are overwritten with the versions embedded below.
"""
import os

FILES = {
    '.gitignore': '# Never upload secrets or tokens to GitHub\n.env\nclient_secret*.json\ntoken_*.json\n\n# Ignore media files & virtual environments\n*.mp4\n*.mp3\n*.wav\nGDrive_Mount/\n__pycache__/\nvenv/\n.DS_Store\n',
    '.env.example': 'YOUTUBE_API_KEY="AIzaSyYourYouTubeAPIKeyHere"\nGEMINI_API_KEY="AIzaSyYourGeminiAPIKeyHere"\nPIXABAY_API_KEY="YourPixabayAPIKeyHere"\n# Optional alternative stock footage source\nPEXELS_API_KEY="YourPexelsAPIKeyHere"\nTELEGRAM_BOT_TOKEN="7123456789:AAHYourBotTokenHere"\nTELEGRAM_CHANNEL_ID="-100YourChannelIDHere"\n# Optional, kept for possible future use (not used by the pipeline today)\nHF_TOKEN="hf_YourHuggingFaceTokenHere"\n',
    'requirements.txt': 'pyyaml>=6.0.2\npython-dotenv==1.0.1\nrequests>=2.31.0\nyt-dlp>=2025.1.1\nmoviepy==1.0.3\nedge-tts>=7.3.1\ntzdata>=2024.1\ngoogle-genai>=1.0.0\ngoogle-api-python-client>=2.150.0\ngoogle-auth-oauthlib>=1.2.1\ngoogle-auth-httplib2>=0.2.0\n',
    'BRAIN.md': '# MASTER BRAIN & MULTI-AGENT CONFIGURATION\r\nGlobal rules shared by every channel. Modify the YAML block or the Agent Instructions below to change how all agents behave.\r\nChannels are listed on the channel page: `execution/channels.yaml`. How to run everything: `execution/execution.md`.\r\n\r\n```yaml\r\n# Gemini models for scripts and titles, tried in order (a busy or retired model falls through to the next)\r\nai_models: ["gemini-3.8-flash", "gemini-3.7-flash", "gemini-3.5-flash", "gemini-flash-latest"]\r\n\r\n# GitHub starts scheduled runs late (4 to 5 hours in October 2026). The GitHub schedule fires this many minutes\r\n# BEFORE each fetch_time, so runs actually start near fetch_time. 0 = no shift. The Telegram start message says how\r\n# early or late each run started; adjust this if they drift.\r\ngithub_schedule_lead_minutes: 265\r\n# true when the GitHub repository is public (unlimited Actions minutes, so --check skips the minutes warning)\r\ngithub_repo_public: true\r\n\r\nstorage_paths:\r\n  base_dir: "./GDrive_Mount/YouTube_Automation"\r\n  tokens_dir: "./GDrive_Mount/YouTube_Automation/00_tokens"\r\n  branding_dir: "./GDrive_Mount/YouTube_Automation/00_branding"   # cached channel logos for the end card\r\n  manifest_file: "./GDrive_Mount/YouTube_Automation/01_manifests/trends.json"\r\n  raw_downloads: "./GDrive_Mount/YouTube_Automation/02_raw_videos"\r\n  audio_renders: "./GDrive_Mount/YouTube_Automation/02_audio_voiceovers"\r\n  processed_videos: "./GDrive_Mount/YouTube_Automation/03_edited_videos"\r\n  archive_dir: "./GDrive_Mount/YouTube_Automation/04_published_archive"\r\n\r\n# Runs on your laptop or IDE put video files here instead, one folder per day:\r\n#   YouTube_Auto/<YYYY-MM-DD>/download  (source videos)  and  /upload  (narration + final videos)\r\n# Day folders older than keep_days are deleted automatically. GitHub runs keep using storage_paths above.\r\nlocal_media:\r\n  enabled: true\r\n  root: "H:/My Drive/YouTube_Auto"   # your Google Drive (Drive for Desktop); "~/YouTube_Auto" = your user folder instead\r\n  keep_days: 2\r\n\r\n# Where each video\'s pictures come from:\r\n#   "stock"   = free stock clips matching the topic (works everywhere, including GitHub)\r\n#   "youtube" = re-use the trending video itself (laptop only: YouTube blocks downloads from cloud servers)\r\nfootage:\r\n  source: "stock"\r\n  provider: "auto"        # "pixabay" | "pexels" | "auto" (whichever key is set: PIXABAY_API_KEY, then PEXELS_API_KEY)\r\n  clips_per_video: 3\r\n\r\nediting_rules:\r\n  zoom_factor: 1.06\r\n  original_audio_volume: 0      # 0 = only the AI voice is heard; 0.05 = original sound faintly underneath\r\n  watermark_fontsize: 36\r\n  watermark_color: "white"\r\n  watermark_opacity: 0.75\r\n  end_card:                     # closing card on every video: channel name, LIKE first, then SUBSCRIBE\r\n    enabled: true\r\n    seconds: 3\r\n    show_logo: false            # true = also show the channel\'s logo above the name\r\n    like_text: "LIKE"\r\n    subscribe_text: "SUBSCRIBE"\r\n\r\nupload_rules:\r\n  privacy_status: "public" # Default when a channel has no privacy_status of its own\r\n  synthetic_media_disclosure: true\r\n\r\ncleanup_rules:                  # GitHub runs; laptop runs keep files in YouTube_Auto day folders instead\r\n  delete_raw_after_publish: true\r\n  delete_voiceover_after_publish: true\r\n  delete_edited_after_publish: true\r\n  delete_edited_from_previous_dates: true\r\n```\r\n\r\n## PIPELINE ARCHITECTURE\r\n(Reference for people. This section is NOT sent to the AI; only the AGENT INSTRUCTIONS below are.)\r\n\r\n### Where everything is decided\r\n| File | Decides |\r\n|---|---|\r\n| `execution/channels.yaml` | Who each channel is: name, link, made for kids, watermark, category |\r\n| `execution/questions.yaml` | What and when each channel posts: genre, searches, language, voice, Shorts schedule, long videos, footage style |\r\n| `BRAIN.md` (this file) | Rules shared by all channels: AI models, storage, footage source, editing and end card, upload and cleanup, AI writing instructions |\r\n| `.github/workflows/daily_youtube_agents.yml` | When GitHub runs (generated from each channel\'s `fetch_time` by `execution.py --check`, firing `github_schedule_lead_minutes` early because GitHub starts scheduled runs hours late) |\r\n| `execution/execution.py` | The only entry point; reads the three files above and runs the agents |\r\n\r\n### What one run does, in order\r\n1. **Choose channels**: a scheduled run picks the channels whose `fetch_time` (one time or a list) matches; a manual run uses the channel typed in. With several fetch times a day, each run makes only the videos whose go-live times fall before the channel\'s next run.\r\n2. **Clear lost work**: unfinished videos whose files are gone (an interrupted earlier run) are marked `expired`.\r\n3. **Long videos first, then Shorts.** For each format:\r\n   1. **Agent 1, Scout**: searches YouTube for trending videos on the channel\'s search phrases (Shorts topics from Shorts, long topics from 4 to 20 minute videos), in the channel\'s language, rotating phrases and source channels.\r\n   2. **Agent 3, Script & Voice**: Gemini writes an original script for the topic, and in the same request the upload title, description, hashtags and footage terms (hook first; long videos get 3 to 5 parts and a recap). The voice narrates it, sentence timings are recorded, and if the narration runs longer than allowed the script is shortened and narrated again. The narration is split into scenes (3 per Short, ~15 s each in long videos).\r\n   3. **Agent 2, Footage**: a specific and a backup search term for each scene (for Shorts, written in the script request; for long videos, Gemini reads each scene\'s words in a second request); one stock clip per scene is downloaded from Pixabay (or Pexels).\r\n   4. **Agent 4, Editor**: FFmpeg cuts each clip to its scene\'s narration time, fits it to 1080x1920 (Short) or 1920x1080 (long), joins them, adds the watermark and narration (no original audio), and appends the LIKE then SUBSCRIBE end card.\r\n   5. **Agent 5, Publisher**: confirms the YouTube login is the right channel, uses the title and description written with the script (the source video\'s title if Gemini was unavailable), adds up to 8 hashtags (`#shorts` for Shorts, Gemini\'s topic hashtags and the trending source video\'s own, also used as search tags) and the stock footage credit, and uploads in resumable chunks with its go-live time (Shorts: `short_post_times`, or `first_post_time` then every `post_frequency`; long: `long_post_times`; a time already passed goes live soon after upload). It uploads only as many videos as the run has go-live times; extra finished videos wait for the next run.\r\n4. **Agent 6, Cleanup**: deletes files no longer needed (GitHub) or day folders older than `keep_days` (laptop).\r\n5. **Agent 7, Telegram**: a "run started" message (with how early or late GitHub started it), then one message per channel with each uploaded video\'s title, link, go-live time and hashtags, and how many failed.\r\n\r\n### Video status flow (in the manifest, `01_manifests/trends.json`)\r\n`discovered` → `voiced` → `ready_to_edit` → `edited` → `published`\r\n(`download_failed` or `expired` when a step can\'t be completed; re-used trending videos use `discovered` → `downloaded` → `voiced` → `edited` → `published`.)\r\n\r\n## AGENT INSTRUCTIONS\r\n* **Agent 1 (Scout):** Prioritize high-velocity Short videos. Store clean metadata in human-readable JSON.\r\n* **Agent 3 (Script & Voice):** Write a transformative commentary script on the trending topic, sized to the channel\'s `target_duration_seconds`, in the channel\'s language and tone. Short, clear sentences that read naturally aloud. **Open with a hook in the first sentence (first 3 seconds)**: a surprising fact, a bold question, or a "you won\'t believe" moment that makes the viewer keep watching, then pay it off before the end. For news and war channels, strictly avoid graphic or violent terms so the video remains advertiser-friendly; use strategic terminology ("escalating tensions", "frontline shifts", "defense posture"). Name the countries, places and public figures involved (heads of state, ministers and other government representatives), describing their public actions and statements factually, without insults or unproven claims. For kids channels, write as an excited child talking to friends: very simple words, playful wonder, a "Guess what?" or "Whoa!" style hook, and end with a fun question that invites them to watch the next video. Keep it entertaining, not only educational: when the topic is a cartoon, story or silly animal, tell a short ORIGINAL funny story with a clear beginning, a surprise and a happy ending (never retell copyrighted characters such as Peppa Pig or Disney characters); when it is a fact, explain it with wonder and a joke.\r\n* **Agent 4 (Editor):** Apply a 1.06x crop zoom, remove the original audio completely (original_audio_volume 0), use only the AI voiceover, place the channel watermark in the bottom-right corner, and end every video with the end card (channel name, LIKE first, then SUBSCRIBE).\r\n* **Agent 5 (Publisher):** Generate a high-CTR title under 65 characters for Shorts (70 for long videos) that matches what the script actually says, with no clickbait the video doesn\'t pay off. Keep the description to the requested sentences with no credits, links or source names: the pipeline adds the footage credit itself. Hashtags have no spaces, never use the `@` symbol, and never name other YouTube channels.\r\n',
    'orchestrator.py': '"""Runs agents 1 to 7 in order for one channel. Started by execution/execution.py, not run directly."""\r\nimport copy\r\nimport json\r\nimport os\r\n\r\nfrom agents.agent_1_scout import TrendScoutAgent\r\nfrom agents.agent_2_downloader import DownloaderAgent\r\nfrom agents.agent_3_voiceover import VoiceoverAgent, stock_mode\r\nfrom agents.agent_4_editor import VideoEditorAgent\r\nfrom agents.agent_5_publisher import PublisherAgent\r\nfrom agents.agent_6_cleanup import CleanupAgent, expire_missing_files\r\nfrom agents.agent_7_notifier import TelegramNotifierAgent\r\nfrom brain import item_matches\r\n\r\n# Footage can\'t always be found (no matching stock clips, or a restricted video), so look again a few times\r\nFIND_ATTEMPTS = 3\r\n# Long videos are prepared first, so they are certainly ready well before their go-live times\r\nFORMATS = ("long", "short")\r\n\r\n\r\ndef format_profile(profile, fmt):\r\n    """The channel\'s settings for one format: Shorts as answered, or the long-video answers (Q22 to Q24)."""\r\n    settings = copy.deepcopy(profile)\r\n    settings["format"] = fmt\r\n    if fmt == "long":\r\n        settings["max_videos_per_run"] = profile["long"]["count"]\r\n        settings["publish_plan"] = profile.get("long_publish_plan")\r\n    return settings\r\n\r\n\r\nclass OrchestratorAgent:\r\n    def __init__(self, config, instructions):\r\n        self.config = config\r\n        self.instructions = instructions\r\n        self.setup_directories()\r\n\r\n    def setup_directories(self):\r\n        paths = self.config["storage_paths"]\r\n        os.makedirs(os.path.dirname(paths["manifest_file"]), exist_ok=True)\r\n        os.makedirs(paths["raw_downloads"], exist_ok=True)\r\n        os.makedirs(paths["audio_renders"], exist_ok=True)\r\n        os.makedirs(paths["processed_videos"], exist_ok=True)\r\n        os.makedirs(paths["archive_dir"], exist_ok=True)\r\n        os.makedirs(paths["tokens_dir"], exist_ok=True)\r\n\r\n    def manifest_items(self, channel_key, profile=None):\r\n        path = self.config["storage_paths"]["manifest_file"]\r\n        if not os.path.exists(path):\r\n            return []\r\n        with open(path, "r", encoding="utf-8") as f:\r\n            items = json.load(f)\r\n        if profile is None:\r\n            return [item for item in items if item.get("profile") == channel_key]\r\n        return [item for item in items if item_matches(item, channel_key, profile)]\r\n\r\n    def expire_unfinishable(self, channel_key):\r\n        """Before counting today\'s videos, drop half-finished ones whose files were lost (e.g. a fresh GitHub run)."""\r\n        path = self.config["storage_paths"]["manifest_file"]\r\n        if not os.path.exists(path):\r\n            return\r\n        with open(path, "r", encoding="utf-8") as f:\r\n            items = json.load(f)\r\n        expired = expire_missing_files([i for i in items if i.get("profile") == channel_key])\r\n        if expired:\r\n            print(f"[Orchestrator] {expired} unfinished video(s) from an earlier run lost their files; "\r\n                  "marked expired so new ones are made instead.")\r\n            with open(path, "w", encoding="utf-8") as f:\r\n                json.dump(items, f, indent=4, ensure_ascii=False)\r\n\r\n    def run_format(self, config, channel_key, dry_run):\r\n        """Find footage, narrate, edit and (unless a test run) upload one format\'s videos."""\r\n        profile = config["profiles"][channel_key]\r\n        paths = config["storage_paths"]\r\n        wanted = profile["max_videos_per_run"]\r\n        print(f"\\n---------- {channel_key}: {wanted} {profile[\'format\']} video(s) ----------")\r\n\r\n        self.expire_unfinishable(channel_key)\r\n        scout = TrendScoutAgent(config, self.instructions)\r\n        downloader = DownloaderAgent(paths["manifest_file"], paths["raw_downloads"], config)\r\n        voiceover = VoiceoverAgent(config, self.instructions)\r\n        if stock_mode(config, profile):\r\n            # Stock footage: write and narrate the script first, then fetch a clip that matches each scene\r\n            ready_statuses, in_progress = ("ready_to_edit", "edited"), ("discovered", "voiced")\r\n            steps = [voiceover.run, lambda: downloader.run(channel_key)]\r\n        else:\r\n            # Re-used trending video: download it first, then narrate\r\n            ready_statuses, in_progress = ("downloaded", "voiced", "edited"), ("discovered",)\r\n            steps = [lambda: downloader.run(channel_key), voiceover.run]\r\n\r\n        for attempt in range(FIND_ATTEMPTS):\r\n            items = self.manifest_items(channel_key, profile)\r\n            ready = sum(1 for i in items if i["status"] in ready_statuses)\r\n            pending = sum(1 for i in items if i["status"] in in_progress)\r\n            if ready >= wanted:\r\n                break\r\n            if attempt:\r\n                print(f"\\n[Orchestrator] {ready} of {wanted} video(s) ready; looking for more (attempt {attempt + 1}).")\r\n            if ready + pending < wanted:\r\n                scout.run(limit=wanted - ready - pending)\r\n            for step in steps:\r\n                step()\r\n\r\n        VideoEditorAgent(config).run()\r\n        if not dry_run:\r\n            PublisherAgent(config, self.instructions).run()\r\n\r\n    def execute_pipeline(self, channel_key, dry_run=False, formats=FORMATS, planned=None):\r\n        """Run every agent for one channel (long videos, then Shorts) and return the number of videos uploaded."""\r\n        base = self.config["profiles"][channel_key]\r\n        published_before = {i["video_id"] for i in self.manifest_items(channel_key) if i["status"] == "published"}\r\n        print("====================================================")\r\n        print(f" ORCHESTRATOR STARTED | CHANNEL: {channel_key}" + (" | TEST RUN" if dry_run else ""))\r\n        print("====================================================")\r\n\r\n        for fmt in formats:\r\n            if (fmt == "long" and not base["long"]["count"]) or (fmt == "short" and not base["max_videos_per_run"]):\r\n                continue\r\n            config = copy.deepcopy(self.config)\r\n            config["active_profile"] = channel_key\r\n            config["profiles"][channel_key] = format_profile(base, fmt)\r\n            self.run_format(config, channel_key, dry_run)\r\n\r\n        if dry_run:\r\n            print("\\n[Test run] Skipping upload, cleanup and Telegram alert.")\r\n            print(f"[Test run] Finished videos are in: {self.config[\'storage_paths\'][\'processed_videos\']}")\r\n            return 0\r\n\r\n        config = copy.deepcopy(self.config)\r\n        config["active_profile"] = channel_key\r\n        CleanupAgent(config).run()\r\n        uploaded = [i for i in self.manifest_items(channel_key)\r\n                    if i["status"] == "published" and i["video_id"] not in published_before]\r\n        TelegramNotifierAgent(config).run(uploaded, planned)\r\n\r\n        print("\\n====================================================")\r\n        print(f" {channel_key}: {len(uploaded)} video(s) uploaded")\r\n        for item in uploaded:\r\n            link = "shorts/" if item.get("format", "short") == "short" else "watch?v="\r\n            print(f"   https://youtube.com/{link}{item.get(\'uploaded_youtube_id\')}  ({item.get(\'format\', \'short\')})")\r\n        print("====================================================")\r\n        return len(uploaded)\r\n',
    'brain.py': '"""Loads BRAIN.md (global rules), execution/channels.yaml (who each channel is) and\r\nexecution/questions.yaml (what and when each channel posts), and works out GitHub schedules."""\r\nimport os\r\nimport re\r\nfrom datetime import datetime, time, timedelta, timezone\r\nfrom zoneinfo import ZoneInfo, ZoneInfoNotFoundError\r\n\r\nimport yaml\r\n\r\nPROJECT_DIR = os.path.dirname(os.path.abspath(__file__))\r\nBRAIN_FILE = os.path.join(PROJECT_DIR, "BRAIN.md")\r\nCHANNELS_FILE = os.path.join(PROJECT_DIR, "execution", "channels.yaml")\r\nQUESTIONS_FILE = os.path.join(PROJECT_DIR, "execution", "questions.yaml")\r\n\r\nDAY_NAMES = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]\r\nDEFAULT_TIMEZONE = "Asia/Kolkata"\r\n\r\nFREQUENCIES = {"15 mins": 15, "30 mins": 30, "1 hour": 60, "3 hours": 180}\r\nLANGUAGES = {"English": "en-", "Hindi": "hi-", "Telugu": "te-"}\r\nDEFAULT_VOICES = {\r\n    # (language, made_for_kids) -> voice\r\n    ("English", False): "en-US-AndrewNeural",\r\n    ("English", True): "en-US-AnaNeural",\r\n    ("Hindi", False): "hi-IN-MadhurNeural",\r\n    ("Hindi", True): "hi-IN-SwaraNeural",\r\n    ("Telugu", False): "te-IN-MohanNeural",\r\n    ("Telugu", True): "te-IN-ShrutiNeural",\r\n}\r\nSPEEDS = ["-15%", "-5%", "+0%", "+10%"]\r\nVIDEO_LENGTHS = [15, 30, 45, 60]\r\nVISIBILITIES = ["public", "unlisted", "private"]\r\nFOOTAGE_STYLES = ["any", "animation", "film", "mixed"]\r\nLONG_MINUTES = [4, 5, 6, 7, "4-5", "4-6", "5-6", "5-7", "6-7"]\r\nMAX_LONG_VIDEOS_PER_DAY = 4\r\nMAX_VIDEOS_PER_DAY = 50\r\n# Upload videos, and read which channel a login belongs to (checked before every upload)\r\nYOUTUBE_SCOPES = [\r\n    "https://www.googleapis.com/auth/youtube.upload",\r\n    "https://www.googleapis.com/auth/youtube.readonly",\r\n]\r\n\r\n\r\n# ---------- loading ----------\r\n\r\ndef load_brain(brain_file=BRAIN_FILE, channels_file=CHANNELS_FILE, questions_file=QUESTIONS_FILE):\r\n    with open(brain_file, "r", encoding="utf-8") as f:\r\n        raw_md = f.read()\r\n\r\n    fence = "`" * 3\r\n    yaml_match = re.search(fence + r"yaml\\n(.*?)\\n" + fence, raw_md, re.DOTALL)\r\n    if not yaml_match:\r\n        raise ValueError("Invalid BRAIN.md: Missing yaml configuration block.")\r\n\r\n    config = yaml.safe_load(yaml_match.group(1))\r\n    instructions = raw_md.split("## AGENT INSTRUCTIONS")[-1].strip()\r\n    config["profiles"] = load_profiles(channels_file, questions_file)\r\n    lead = int(config.get("github_schedule_lead_minutes") or 0)\r\n    for profile in config["profiles"].values():\r\n        profile["schedule"]["lead_minutes"] = lead\r\n    apply_media_folders(config)\r\n    return config, instructions\r\n\r\n\r\ndef apply_media_folders(config):\r\n    """Local runs keep video files in <root>/<YYYY-MM-DD>/download and /upload, so whole days are easy to delete.\r\n\r\n    GitHub runs store nothing between runs, so they keep the storage_paths folders from BRAIN.md.\r\n    """\r\n    media = config.get("local_media") or {}\r\n    if os.getenv("GITHUB_ACTIONS") == "true" or not media.get("enabled", True):\r\n        config["storage_mode"] = "cloud"\r\n        return\r\n    root = os.path.normpath(os.path.expanduser(media.get("root", "~/YouTube_Auto")))\r\n    if not os.path.isdir(os.path.splitdrive(root)[0] + os.sep):\r\n        # e.g. Google Drive for Desktop isn\'t running, so its drive letter is missing\r\n        fallback = os.path.normpath(os.path.expanduser("~/YouTube_Auto"))\r\n        print(f"[Storage] {root} isn\'t available; using {fallback} for video files this run.")\r\n        root = fallback\r\n    day = os.path.join(root, datetime.now().strftime("%Y-%m-%d"))\r\n    paths = config["storage_paths"]\r\n    paths["raw_downloads"] = os.path.join(day, "download")\r\n    paths["audio_renders"] = os.path.join(day, "upload")\r\n    paths["processed_videos"] = os.path.join(day, "upload")\r\n    config["storage_mode"] = "local"\r\n    config["media_root"] = root\r\n\r\n\r\ndef read_section(path, section):\r\n    with open(path, "r", encoding="utf-8") as f:\r\n        return (yaml.safe_load(f) or {}).get(section) or {}\r\n\r\n\r\ndef load_profiles(channels_file=CHANNELS_FILE, questions_file=QUESTIONS_FILE):\r\n    channels = read_section(channels_file, "channels")\r\n    answers = read_section(questions_file, "channels")\r\n\r\n    problems = validate_channels(channels) + validate_answers(answers, channels)\r\n    if problems:\r\n        raise ValueError("Please fix these problems:\\n  - " + "\\n  - ".join(problems))\r\n\r\n    return {key: build_profile(channels[key], answers.get(key)) for key in channels}\r\n\r\n\r\ndef fetch_times(answers):\r\n    """Q12 fetch_time as a list: one "HH:MM", or a list of them for several runs a day."""\r\n    value = answers.get("fetch_time")\r\n    if value in (None, "", []):\r\n        return []\r\n    return list(value) if isinstance(value, list) else [value]\r\n\r\n\r\ndef build_profile(channel, answers):\r\n    """Combine a channel\'s identity with its answers into the settings the agents use."""\r\n    kids = bool(channel["made_for_kids"])\r\n    a = answers or {}\r\n    language = a.get("language") or "English"\r\n    genre = a.get("genre") or channel["channel_name"]\r\n\r\n    return {\r\n        # From the channel page\r\n        "channel_name": channel["channel_name"],\r\n        "channel_url": channel["channel_url"],\r\n        "made_for_kids": kids,\r\n        "watermark_text": channel.get("watermark_text") or "@" + re.sub(r"[^A-Za-z0-9]", "", channel["channel_name"]),\r\n        "category_id": str(channel.get("category_id") or ("27" if kids else "24")),\r\n        "logo_file": channel.get("logo_file"),\r\n        # From the questions file\r\n        "has_answers": answers is not None,\r\n        "enabled": answers is not None and a.get("run", True) is not False,\r\n        "niche": genre,\r\n        "search_queries": a.get("search_phrases") or [f"{genre} #shorts"],\r\n        "language": language,\r\n        "voice": a.get("voice") or DEFAULT_VOICES[(language, kids)],\r\n        "voice_rate": a.get("voice_speed") or ("-15%" if kids else "-5%"),\r\n        "tone": a.get("tone") or ("Enthusiastic, warm, curious storyteller for young children." if kids\r\n                                  else "Clear, engaging and informative."),\r\n        "target_duration_seconds": int(a.get("video_length_seconds") or 30),\r\n        "avoid_terms": a.get("avoid_words") or [],\r\n        "lookback_days": int(a.get("lookback_days") or 5),\r\n        # Day total of Shorts: one per short_post_times entry when given, else videos_per_day\r\n        "max_videos_per_run": len(a.get("short_post_times") or []) or int(a.get("videos_per_day") or 1),\r\n        "privacy_status": a.get("visibility") or "public",\r\n        "test_run": bool(a.get("test_run", False)),\r\n        "exclude_sources": a.get("exclude_sources") or [],\r\n        "footage_style": a.get("footage_style") or "any",\r\n        "schedule": {\r\n            "timezone": a.get("timezone") or DEFAULT_TIMEZONE,\r\n            # One run per fetch time; the day\'s videos are shared between the runs (see run_window)\r\n            "post_times": fetch_times(a),\r\n            "days": a.get("days") or "daily",\r\n        },\r\n        "posting": {\r\n            # Exact go-live times (short_post_times), or first_post_time then every post_frequency\r\n            "post_times": list(a.get("short_post_times") or []),\r\n            "first_post_time": a.get("first_post_time"),\r\n            "frequency_minutes": FREQUENCIES.get(a.get("post_frequency") or "1 hour", 60),\r\n        },\r\n        # Long (landscape, 5 to 7 minute) videos, prepared in the same run as the Shorts\r\n        "long": {\r\n            "count": int(a.get("long_videos_per_day") or 0),\r\n            "minutes": a.get("long_video_minutes") or 6,\r\n            "post_times": [str(t) for t in (a.get("long_post_times") or [])],\r\n        },\r\n    }\r\n\r\n\r\n# ---------- validation ----------\r\n\r\ndef validate_channels(channels):\r\n    if not channels:\r\n        return ["channels.yaml: no channels listed under \'channels:\'."]\r\n    problems = []\r\n    for key, details in channels.items():\r\n        where = f"channels.yaml \'{key}\'"\r\n        if not re.fullmatch(r"[a-z][a-z0-9_]{1,40}", str(key)):\r\n            problems.append(f"{where}: key must be lowercase letters, numbers and underscores, starting with a letter")\r\n        if not isinstance(details, dict):\r\n            problems.append(f"{where}: details must be indented under the key")\r\n            continue\r\n        for field in ("channel_name", "channel_url", "made_for_kids"):\r\n            if details.get(field) in (None, ""):\r\n                problems.append(f"{where}: missing required field \'{field}\'")\r\n        if details.get("channel_url") and not parse_channel_url(details["channel_url"]):\r\n            problems.append(f"{where}: channel_url must look like https://www.youtube.com/@handle "\r\n                            "or https://www.youtube.com/channel/UC...")\r\n    return problems\r\n\r\n\r\ndef item_matches(item, channel_key, profile):\r\n    """True if a manifest item belongs to this channel and to the format (short or long) being processed."""\r\n    return item.get("profile") == channel_key and item.get("format", "short") == profile.get("format", "short")\r\n\r\n\r\ndef parse_channel_url(url):\r\n    """Return ("handle", "@name") or ("id", "UC...") from a YouTube channel link, or None if unrecognised."""\r\n    match = re.search(r"youtube\\.com/(@[\\w.\\-]+)", str(url))\r\n    if match:\r\n        return "handle", match.group(1).lower()\r\n    match = re.search(r"youtube\\.com/channel/(UC[\\w\\-]{22})", str(url))\r\n    if match:\r\n        return "id", match.group(1)\r\n    return None\r\n\r\n\r\ndef channel_matches(url, channel_id, custom_url):\r\n    """True if the signed-in channel (its ID and @handle from the YouTube API) is the one the link points to."""\r\n    kind, value = parse_channel_url(url)\r\n    if kind == "id":\r\n        return channel_id == value\r\n    return (custom_url or "").lower() == value\r\n\r\n\r\ndef validate_answers(answers, channels):\r\n    problems = []\r\n    for key, a in answers.items():\r\n        where = f"questions.yaml \'{key}\'"\r\n        if key not in channels:\r\n            problems.append(f"{where}: no channel with this key in channels.yaml")\r\n            continue\r\n        if not isinstance(a, dict):\r\n            problems.append(f"{where}: answers must be indented under the channel key")\r\n            continue\r\n\r\n        language = a.get("language", "English")\r\n        if language not in LANGUAGES:\r\n            problems.append(f"{where}: language must be one of {\', \'.join(LANGUAGES)}")\r\n        voice = a.get("voice")\r\n        if voice:\r\n            if not re.fullmatch(r"[a-z]{2,3}-[A-Z]{2,4}-\\w+Neural", str(voice)):\r\n                problems.append(f"{where}: voice \'{voice}\' should look like en-US-AndrewNeural")\r\n            elif language in LANGUAGES and not str(voice).startswith(LANGUAGES[language]):\r\n                problems.append(f"{where}: voice \'{voice}\' does not speak {language}; pick a {LANGUAGES[language]}... voice")\r\n        checks = [\r\n            ("voice_speed", SPEEDS), ("video_length_seconds", VIDEO_LENGTHS),\r\n            ("post_frequency", list(FREQUENCIES)), ("visibility", VISIBILITIES), ("footage_style", FOOTAGE_STYLES),\r\n        ]\r\n        for field, allowed in checks:\r\n            if a.get(field) is not None and a[field] not in allowed:\r\n                problems.append(f"{where}: {field} must be one of {\', \'.join(str(x) for x in allowed)}")\r\n        for field in ("search_phrases", "avoid_words", "exclude_sources"):\r\n            value = a.get(field)\r\n            if value is not None and not (isinstance(value, list) and all(isinstance(v, str) for v in value)):\r\n                problems.append(f\'{where}: {field} must be a list in quotes, e.g. ["one", "two"] or []\')\r\n        videos = a.get("videos_per_day")\r\n        if videos is not None and not (isinstance(videos, int) and 1 <= videos <= MAX_VIDEOS_PER_DAY):\r\n            problems.append(f"{where}: videos_per_day must be a whole number from 1 to {MAX_VIDEOS_PER_DAY}")\r\n        long_count = a.get("long_videos_per_day")\r\n        if long_count is not None and not (isinstance(long_count, int) and 0 <= long_count <= MAX_LONG_VIDEOS_PER_DAY):\r\n            problems.append(f"{where}: long_videos_per_day must be a whole number from 0 to {MAX_LONG_VIDEOS_PER_DAY}")\r\n        if a.get("long_video_minutes") is not None and a["long_video_minutes"] not in LONG_MINUTES:\r\n            problems.append(f\'{where}: long_video_minutes must be one of 4, 5, 6, 7, "4-5", "4-6", "5-6", "5-7" \'\r\n                            \'or "6-7"\')\r\n        long_times = a.get("long_post_times") or []\r\n        if not isinstance(long_times, list):\r\n            problems.append(f\'{where}: long_post_times must be a list, e.g. ["13:00", "19:00"]\')\r\n            long_times = []\r\n        short_times = a.get("short_post_times") or []\r\n        if not isinstance(short_times, list):\r\n            problems.append(f\'{where}: short_post_times must be a list, e.g. ["08:00", "10:00"]\')\r\n            short_times = []\r\n        if len(short_times) > MAX_VIDEOS_PER_DAY:\r\n            problems.append(f"{where}: short_post_times can list at most {MAX_VIDEOS_PER_DAY} times")\r\n        for label, times_list in (("long", long_times), ("short", short_times)):\r\n            for t in times_list:\r\n                try:\r\n                    parse_time(t)\r\n                except (ValueError, AttributeError):\r\n                    problems.append(f"{where}: {label} post time \'{t}\' must be HH:MM in 24-hour format, in quotes")\r\n        if isinstance(long_count, int) and long_count > len(long_times):\r\n            problems.append(f"{where}: give one long_post_times entry per long video "\r\n                            f"({long_count} needed, {len(long_times)} given)")\r\n        lookback = a.get("lookback_days")\r\n        if lookback is not None and not (isinstance(lookback, int) and 1 <= lookback <= 30):\r\n            problems.append(f"{where}: lookback_days must be a whole number from 1 to 30")\r\n        times = [("fetch_time", t) for t in fetch_times(a)]\r\n        if a.get("first_post_time") is not None:\r\n            times.append(("first_post_time", a["first_post_time"]))\r\n        for field, value in times:\r\n            try:\r\n                parse_time(value)\r\n            except (ValueError, AttributeError):\r\n                problems.append(f"{where}: {field} \'{value}\' must be HH:MM in 24-hour format, in quotes")\r\n        try:\r\n            if len({parse_time(t) for t in fetch_times(a)}) < len(fetch_times(a)):\r\n                problems.append(f"{where}: fetch_time lists the same time twice")\r\n        except (ValueError, AttributeError):\r\n            pass\r\n        try:\r\n            ZoneInfo(a.get("timezone") or DEFAULT_TIMEZONE)\r\n        except (ZoneInfoNotFoundError, ValueError):\r\n            problems.append(f"{where}: unknown timezone \'{a.get(\'timezone\')}\'")\r\n        try:\r\n            parse_days(a.get("days") or "daily")\r\n        except ValueError:\r\n            problems.append(f"{where}: days must be daily, weekdays, weekends or a list like [mon, wed, fri]")\r\n    return problems\r\n\r\n\r\n# ---------- time helpers ----------\r\n\r\ndef parse_time(value):\r\n    # YAML reads an unquoted 09:30 as the base-60 integer 570, so accept both forms\r\n    if isinstance(value, int):\r\n        return time(value // 60, value % 60)\r\n    hours, minutes = str(value).strip().split(":")\r\n    return time(int(hours), int(minutes))\r\n\r\n\r\ndef parse_days(value):\r\n    if value in (None, "daily", "everyday", "all"):\r\n        return list(range(7))\r\n    if value == "weekdays":\r\n        return list(range(5))\r\n    if value == "weekends":\r\n        return [5, 6]\r\n    if isinstance(value, str):\r\n        value = value.split(",")\r\n    return sorted({DAY_NAMES.index(str(day).strip().lower()[:3]) for day in value})\r\n\r\n\r\ndef cron_time(local_dt, schedule):\r\n    """When GitHub\'s schedule should fire (UTC) for a run meant to start at local_dt: lead_minutes earlier."""\r\n    return (local_dt - timedelta(minutes=schedule.get("lead_minutes") or 0)).astimezone(timezone.utc)\r\n\r\n\r\ndef utc_slots(profile, ref_date=None):\r\n    """Map each fetch time to its GitHub cron time as {(minute, hour): {cron weekdays}} (cron weekdays: 0 = Sunday)."""\r\n    schedule = profile.get("schedule") or {}\r\n    tz = ZoneInfo(schedule.get("timezone", DEFAULT_TIMEZONE))\r\n    ref = ref_date or datetime.now(tz).date()\r\n    slots = {}\r\n\r\n    for post_time in schedule.get("post_times") or []:\r\n        local_time = parse_time(post_time)\r\n        for weekday in parse_days(schedule.get("days", "daily")):\r\n            local_date = ref + timedelta(days=(weekday - ref.weekday()) % 7)\r\n            utc_dt = cron_time(datetime.combine(local_date, local_time, tzinfo=tz), schedule)\r\n            slots.setdefault((utc_dt.minute, utc_dt.hour), set()).add((utc_dt.weekday() + 1) % 7)\r\n\r\n    return slots\r\n\r\n\r\ndef format_cron_days(days):\r\n    return "*" if len(days) == 7 else ",".join(str(day) for day in sorted(days))\r\n\r\n\r\ndef cron_lines(config):\r\n    merged = {}\r\n    for profile in config["profiles"].values():\r\n        if not profile.get("enabled", True):\r\n            continue\r\n        for slot, days in utc_slots(profile).items():\r\n            merged.setdefault(slot, set()).update(days)\r\n\r\n    ordered = sorted(merged.items(), key=lambda item: (item[0][1], item[0][0]))\r\n    return [f"{minute} {hour} * * {format_cron_days(days)}" for (minute, hour), days in ordered]\r\n\r\n\r\ndef fetch_time_for_cron(profile, cron, ref_date=None):\r\n    """The channel\'s local fetch time that the GitHub cron ("minute hour ...", UTC) stands for, or None."""\r\n    minute, hour = (int(part) for part in cron.split()[:2])\r\n    schedule = profile.get("schedule") or {}\r\n    tz = ZoneInfo(schedule.get("timezone", DEFAULT_TIMEZONE))\r\n    ref = ref_date or datetime.now(tz).date()\r\n    for post_time in schedule.get("post_times") or []:\r\n        utc_dt = cron_time(datetime.combine(ref, parse_time(post_time), tzinfo=tz), schedule)\r\n        if (utc_dt.minute, utc_dt.hour) == (minute, hour):\r\n            return parse_time(post_time)\r\n    return None\r\n\r\n\r\ndef due_profiles(config, cron, now=None):\r\n    now = now or datetime.now(timezone.utc)\r\n    minute, hour = (int(part) for part in cron.split()[:2])\r\n\r\n    scheduled = now.replace(hour=hour, minute=minute, second=0, microsecond=0)\r\n    if scheduled > now:\r\n        # GitHub started the run late, after midnight UTC\r\n        scheduled -= timedelta(days=1)\r\n    cron_day = (scheduled.weekday() + 1) % 7\r\n\r\n    return [\r\n        key for key, profile in config["profiles"].items()\r\n        if profile.get("enabled", True) and cron_day in utc_slots(profile).get((minute, hour), set())\r\n    ]\r\n',
    'agents/__init__.py': '# Multi-Agent Package Initializer\n',
    'agents/ai.py': '"""Shared Gemini text generation with fallback across the models listed in BRAIN.md (ai_models)."""\nimport time\n\nDEFAULT_MODELS = ["gemini-3.8-flash", "gemini-3.7-flash", "gemini-3.5-flash", "gemini-flash-latest"]\n\n# Busy (503), rate-limited (429) or retired (404) models are skipped in favour of the next one;\n# dropped connections and timeouts are retried the same way\nRETRYABLE = ("503", "500", "429", "404", "UNAVAILABLE", "RESOURCE_EXHAUSTED", "NOT_FOUND", "INTERNAL",\n             "disconnected", "Connection", "timed out", "Timeout")\nQUOTA = ("429", "RESOURCE_EXHAUSTED")\n# Spacing between requests keeps a run under the per-minute request limit\nMIN_GAP_SECONDS = 4\n# Per-minute limits clear within a minute, so when every model is rate-limited wait once and try again\nQUOTA_WAIT_SECONDS = 65\n\n_state = {"last_call": 0.0, "out_of_quota": False}\n\n\ndef is_retryable(error):\n    name = type(error).__name__\n    return any(code in str(error) for code in RETRYABLE) or any(\n        word in name for word in ("Connect", "Protocol", "Timeout", "Network"))\n\n\ndef _pace():\n    wait = _state["last_call"] + MIN_GAP_SECONDS - time.monotonic()\n    if wait > 0:\n        time.sleep(wait)\n    _state["last_call"] = time.monotonic()\n\n\ndef _try_models(client, prompt, models, errors):\n    """One pass over the models. Returns the text, or None if every model failed with a retryable error."""\n    for model in models:\n        for attempt in range(2):\n            _pace()\n            try:\n                return client.models.generate_content(model=model, contents=prompt).text.strip()\n            except Exception as e:\n                message = str(e)\n                if not is_retryable(e):\n                    raise\n                errors.append(f"{model}: {message[:200]}")\n                # A retired model or an exhausted quota will not recover in 5 seconds, so go straight to\n                # the next model instead of spending a second request on the same one\n                if any(code in message for code in ("404", "NOT_FOUND") + QUOTA):\n                    break\n                time.sleep(5 * (attempt + 1))\n    return None\n\n\ndef generate_text(client, prompt, models=None):\n    if _state["out_of_quota"]:\n        # Earlier calls in this run already found the daily quota used up; don\'t spend more requests\n        raise RuntimeError("All Gemini models failed: daily quota used up earlier in this run (429)")\n    models = models or DEFAULT_MODELS\n    errors = []\n    text = _try_models(client, prompt, models, errors)\n    if text is None and errors and all(any(code in e for code in QUOTA) for e in errors):\n        print(f"[Gemini] Every model is rate-limited; waiting {QUOTA_WAIT_SECONDS}s for the limit to reset...")\n        time.sleep(QUOTA_WAIT_SECONDS)\n        retry_errors = []\n        text = _try_models(client, prompt, models, retry_errors)\n        errors += retry_errors\n        if text is None and retry_errors and all(any(code in e for code in QUOTA) for e in retry_errors):\n            _state["out_of_quota"] = True\n    if text is None:\n        raise RuntimeError("All Gemini models failed: " + " | ".join(errors))\n    return text\n',
    'agents/branding.py': '"""Fetches and caches each channel\'s YouTube profile picture, used as the logo on the end card."""\nimport os\nfrom io import BytesIO\n\nimport requests\nfrom PIL import Image\nfrom googleapiclient.discovery import build\n\nfrom brain import parse_channel_url\n\n\ndef channel_logo(profile, channel_key, branding_dir):\n    """Return a local PNG of the channel\'s logo, or None if it can\'t be found.\n\n    A logo_file set on the channel page wins; otherwise the channel\'s YouTube profile picture is\n    downloaded once and cached (delete the cached file to refresh it after changing the picture).\n    """\n    custom = profile.get("logo_file")\n    if custom and os.path.exists(custom):\n        return custom\n\n    cached = os.path.join(branding_dir, f"logo_{channel_key}.png")\n    if os.path.exists(cached):\n        return cached\n\n    api_key = os.getenv("YOUTUBE_API_KEY")\n    parsed = parse_channel_url(profile.get("channel_url", ""))\n    if not api_key or not parsed:\n        return None\n    kind, value = parsed\n    try:\n        lookup = {"forHandle": value} if kind == "handle" else {"id": value}\n        youtube = build("youtube", "v3", developerKey=api_key)\n        items = youtube.channels().list(part="snippet", **lookup).execute().get("items", [])\n        thumbnails = items[0]["snippet"]["thumbnails"] if items else {}\n        url = next((thumbnails[size]["url"] for size in ("high", "medium", "default") if size in thumbnails), None)\n        if not url:\n            return None\n        image = Image.open(BytesIO(requests.get(url, timeout=20).content)).convert("RGBA")\n        os.makedirs(branding_dir, exist_ok=True)\n        image.save(cached)\n        return cached\n    except Exception as e:\n        print(f"[Branding] Could not fetch the logo for {channel_key}: {e}")\n        return None\n',
    'agents/stock_footage.py': '"""Free stock footage from Pixabay or Pexels, used instead of re-using trending YouTube videos.\r\n\r\nYouTube blocks video downloads from cloud servers such as GitHub\'s, while these APIs work everywhere and their clips\r\nare free to use. Both ask that you show where the footage came from, so each description credits the site.\r\n\r\nfootage.provider in BRAIN.md: "pixabay", "pexels", or "auto" (whichever has a key: PIXABAY_API_KEY, then PEXELS_API_KEY).\r\n"""\r\nimport os\r\nimport time\r\n\r\nimport requests\r\n\r\nfrom agents.ai import generate_text\r\n\r\nPROVIDERS = {\r\n    "pixabay": {"name": "Pixabay", "site": "https://pixabay.com", "env": "PIXABAY_API_KEY"},\r\n    "pexels": {"name": "Pexels", "site": "https://www.pexels.com", "env": "PEXELS_API_KEY"},\r\n}\r\nPEXELS_URLS = ["https://api.pexels.com/videos/search", "https://api.pexels.com/v1/videos/search"]\r\nPIXABAY_URL = "https://pixabay.com/api/videos/"\r\nMAX_DOWNLOAD_BYTES = 80 * 1024 * 1024\r\n# The ideal clip height for each output shape: Shorts are 1080x1920, long videos 1920x1080\r\nTARGET_HEIGHT = {"portrait": 1920, "landscape": 1080}\r\n\r\n\r\ndef safe_error(error, api_key):\r\n    # Pixabay puts the key in the request URL, so error messages must never be printed with it\r\n    return str(error).replace(api_key, "***") if api_key else str(error)\r\n\r\n\r\ndef with_retries(action, attempts=4):\r\n    """Run action(), retrying dropped connections and rate limits with a growing pause."""\r\n    for attempt in range(attempts):\r\n        try:\r\n            return action()\r\n        except requests.RequestException as e:\r\n            status = getattr(getattr(e, "response", None), "status_code", None)\r\n            if attempt == attempts - 1 or (status is not None and status < 500 and status != 429):\r\n                raise\r\n            # Rate limits reset per minute, so wait long enough for the window to clear\r\n            time.sleep(30 * (attempt + 1) if status == 429 else 5 * (attempt + 1))\r\n\r\n\r\n_last_request = [0.0]\r\n\r\n\r\ndef pace(min_gap=0.7):\r\n    """Keep API searches under about 85 a minute (Pixabay allows 100)."""\r\n    wait = _last_request[0] + min_gap - time.monotonic()\r\n    if wait > 0:\r\n        time.sleep(wait)\r\n    _last_request[0] = time.monotonic()\r\n\r\n\r\ndef choose_provider(setting="auto"):\r\n    """Return (provider, api_key) for the configured provider, or (None, None) if no key is set."""\r\n    order = [setting] if setting in PROVIDERS else ["pixabay", "pexels"]\r\n    for provider in order:\r\n        key = os.getenv(PROVIDERS[provider]["env"])\r\n        if key:\r\n            return provider, key\r\n    return None, None\r\n\r\n\r\ndef search_terms(ai_client, item, profile, models, count):\r\n    """Ask Gemini for short visual search terms matching the trending topic."""\r\n    prompt = (\r\n        f"Trending video title: {item[\'original_title\']}\\n"\r\n        f"Context: {item[\'original_description\'][:300]}\\n"\r\n        f"Channel niche: {profile.get(\'niche\', \'\')}\\n"\r\n        + ("The audience is young children, so keep every term child-friendly.\\n" if profile.get("made_for_kids") else "")\r\n        + ("Some clips will be cartoon animation, so terms like \'cartoon cat\' or \'animated forest\' are good.\\n"\r\n           if profile.get("footage_style") in ("animation", "mixed") else "")\r\n        + f"Give {count} different stock-footage search terms in English (1 to 3 words each) for visuals that "\r\n        "match this topic. Avoid graphic violence. Output ONLY the terms, comma-separated."\r\n    )\r\n    try:\r\n        text = generate_text(ai_client, prompt, models)\r\n        terms = [t.strip().strip(\'"\').strip() for t in text.replace("\\n", ",").split(",") if t.strip()]\r\n    except Exception as e:\r\n        print(f"[Stock footage] Could not get search terms from Gemini ({e}); using the channel niche.")\r\n        terms = []\r\n    return with_generic_terms(terms, profile)[:count]\r\n\r\n\r\ndef with_generic_terms(terms, profile):\r\n    fallback = [w for w in profile.get("niche", "").replace(",", " ").split() if len(w) > 3]\r\n    return list(dict.fromkeys(terms + fallback + ["city", "nature", "people", "sky", "abstract"]))\r\n\r\n\r\ndef topic_fallback(item, profile):\r\n    """Footage terms Gemini wrote alongside the script, topped up with generic ones."""\r\n    return with_generic_terms(list(item.get("topic_terms") or []), profile)[:5]\r\n\r\n\r\nTERM_PAIR_RULE = (\r\n    "two English stock-footage search terms (1 to 4 words each) for visuals that show what THAT part is talking "\r\n    "about: first the most specific match, then a more generic backup that stock sites are sure to have (people, "\r\n    "places, objects, animals, maps, flags, actions). "\r\n)\r\n\r\n\r\ndef footage_rules(profile):\r\n    """Rules every footage term follows, shared by the script request and the per-scene request.\r\n\r\n    News channels may name public figures, countries and landmarks in the specific term (stock sites have little\r\n    footage of named people, so the generic backup is tried next). Kids channels never name real people.\r\n    """\r\n    kids = profile.get("made_for_kids")\r\n    return (\r\n        ("Never use names of real people. The audience is young children, so keep every term child-friendly. "\r\n         if kids else\r\n         "If it is about a public figure (a head of state, minister or other government representative), a country "\r\n         "or a famous place, the first term may name them, e.g. \'Narendra Modi speech\' or \'Kremlin Moscow\'. ")\r\n        + ("Some clips will be cartoon animation, so terms like \'cartoon cat\' work well. "\r\n           if profile.get("footage_style") in ("animation", "mixed") else "")\r\n        + "Avoid graphic violence."\r\n    )\r\n\r\n\r\ndef parse_scene_hints(text):\r\n    """\'a | b ; c | d ; e | f\' -> [[a, b], [c, d], [e, f]]."""\r\n    hints = []\r\n    for part in text.split(";"):\r\n        options = [t.strip().strip(\'"\') for t in part.split("|") if t.strip().strip(\'"\')]\r\n        if options:\r\n            hints.append(options[:2])\r\n    return hints\r\n\r\n\r\ndef hinted_terms(hints, scenes, item, profile):\r\n    """Spread the script\'s hints over the scenes in order, each with one topic term as a last resort."""\r\n    fallback = topic_fallback(item, profile)\r\n    return [hints[i * len(hints) // len(scenes)] + [fallback[i % len(fallback)]] for i in range(len(scenes))]\r\n\r\n\r\ndef scene_terms(ai_client, scenes, item, profile, models):\r\n    """For each scene, [specific term, generic backup term] describing what that scene\'s narration actually says."""\r\n    if item.get("scene_hints") and item.get("format") != "long":\r\n        # Shorts: the script request already chose terms for the opening, middle and end of the narration\r\n        return hinted_terms(item["scene_hints"], scenes, item, profile)\r\n    numbered = "\\n".join(f"{i + 1}. {scene[\'text\'][:400]}" for i, scene in enumerate(scenes))\r\n    prompt = (\r\n        f"A narrated video about: {item[\'original_title\']}\\n"\r\n        f"Channel niche: {profile.get(\'niche\', \'\')}\\n"\r\n        + "For EACH numbered scene below, give " + TERM_PAIR_RULE + footage_rules(profile)\r\n        + f"\\nReply with exactly {len(scenes)} lines in the form \'number. specific term | backup term\' and nothing "\r\n        f"else.\\n\\n{numbered}"\r\n    )\r\n    terms = {}\r\n    try:\r\n        for line in generate_text(ai_client, prompt, models).splitlines():\r\n            number, _, rest = line.partition(".")\r\n            options = [t.strip().strip(\'"\') for t in rest.split("|") if t.strip()]\r\n            if number.strip().isdigit() and options:\r\n                terms[int(number) - 1] = options[:2]\r\n    except Exception as e:\r\n        print(f"[Stock footage] Could not get scene terms from Gemini ({e}); using topic terms.")\r\n    fallback = []\r\n    if len(terms) < len(scenes):\r\n        # The script request already returned footage terms for the whole topic; only ask again if it didn\'t\r\n        fallback = topic_fallback(item, profile) if item.get("topic_terms") else \\\r\n            search_terms(ai_client, item, profile, models, 5)\r\n    return [terms.get(i) or [fallback[i % len(fallback)]] for i in range(len(scenes))]\r\n\r\n\r\ndef fetch_scene_clips(provider, api_key, terms, destination_dir, prefix, kids=False, style="any",\r\n                      orientation="portrait"):\r\n    """One clip per scene, in scene order, trying each scene\'s terms in turn (specific first, then backup).\r\n\r\n    terms: [[term, ...] per scene]. Returns ([path or None per scene], credits, [term actually used per scene]).\r\n    """\r\n    os.makedirs(destination_dir, exist_ok=True)\r\n    paths, credits, used_terms, used_ids, cache = [], [], [], set(), {}\r\n    for index, options in enumerate(terms):\r\n        wanted = clip_type(style, index)\r\n        path, chosen = None, None\r\n        try:\r\n            for term in options:\r\n                for video_type in ([wanted, None] if wanted else [None]):\r\n                    key = (term, video_type)\r\n                    if key not in cache:\r\n                        cache[key] = with_retries(\r\n                            lambda: CANDIDATES[provider](api_key, term, kids, video_type, orientation))\r\n                    pool = [c for c in cache[key] if c[0] not in used_ids]\r\n                    if pool:\r\n                        clip_id, url, credit = pool[0]\r\n                        used_ids.add(clip_id)\r\n                        path = os.path.join(destination_dir, f"{prefix}_scene{index + 1:03d}.mp4")\r\n                        with_retries(lambda: download_file(url, path))\r\n                        credits.append(credit)\r\n                        chosen = term\r\n                        print(f"[Stock footage] Scene {index + 1}: \'{term}\' -> {PROVIDERS[provider][\'name\']} "\r\n                              f"video {clip_id}")\r\n                        break\r\n                if path:\r\n                    break\r\n        except requests.RequestException as e:\r\n            print(f"[Stock footage] Scene {index + 1} ({\' / \'.join(options)}) failed: {safe_error(e, api_key)}")\r\n            path = None\r\n        if not path:\r\n            print(f"[Stock footage] Scene {index + 1}: no clip for {\' / \'.join(options)}; "\r\n                  "a neighbouring clip will be reused.")\r\n        paths.append(path)\r\n        used_terms.append(chosen)\r\n    return paths, credits, used_terms\r\n\r\n\r\ndef download_file(url, target):\r\n    with requests.get(url, stream=True, timeout=180) as response:\r\n        response.raise_for_status()\r\n        with open(target, "wb") as f:\r\n            for chunk in response.iter_content(chunk_size=1 << 20):\r\n                f.write(chunk)\r\n\r\n\r\n# ---------- Pexels ----------\r\n\r\ndef pick_file(video, orientation="portrait"):\r\n    """Pexels: choose the MP4 rendition closest to the target height without going below 720p."""\r\n    files = [f for f in video.get("video_files", [])\r\n             if f.get("file_type") == "video/mp4" and f.get("height") and f.get("link")]\r\n    usable = [f for f in files if min(f["height"], f.get("width") or f["height"]) >= 720] or files\r\n    target = TARGET_HEIGHT[orientation]\r\n    return min(usable, key=lambda f: abs(f["height"] - target)) if usable else None\r\n\r\n\r\ndef pexels_candidates(api_key, term, kids, video_type, orientation):\r\n    # Pexels has no animation filter, so video_type is ignored here\r\n    params = {"query": term, "orientation": orientation, "size": "medium", "per_page": 30}\r\n    for url in PEXELS_URLS:\r\n        pace()\r\n        response = requests.get(url, headers={"Authorization": api_key}, params=params, timeout=30)\r\n        if response.status_code == 404:\r\n            continue\r\n        response.raise_for_status()\r\n        return [(v["id"], pick_file(v, orientation)["link"], v.get("user", {}).get("name", "Pexels"))\r\n                for v in response.json().get("videos", []) if v.get("duration", 0) >= 3 and pick_file(v, orientation)]\r\n    return []\r\n\r\n\r\n# ---------- Pixabay ----------\r\n\r\ndef pick_rendition(renditions, orientation="portrait"):\r\n    """Pixabay: pick the version that best fills the output frame after cropping, within the size cap."""\r\n    usable = [r for r in renditions.values() if r.get("url") and r.get("height")]\r\n    if not usable:\r\n        return None\r\n    portrait_clip = any(r["height"] > r["width"] for r in usable)\r\n    if orientation == "landscape" or portrait_clip:\r\n        # Already the right shape (or portrait for a Short): closest to the target height\r\n        target = TARGET_HEIGHT[orientation]\r\n        return min(usable, key=lambda r: abs(r["height"] - target))\r\n    # Landscape clip for a vertical Short: the tallest version under the cap keeps the centre crop sharp\r\n    small_enough = [r for r in usable if 0 < r.get("size", 0) <= MAX_DOWNLOAD_BYTES] or usable\r\n    return max(small_enough, key=lambda r: r["height"])\r\n\r\n\r\ndef pixabay_candidates(api_key, term, kids, video_type, orientation):\r\n    params = {"key": api_key, "q": term[:100], "per_page": 30, "order": "popular",\r\n              "safesearch": "true" if kids else "false"}\r\n    if video_type in ("animation", "film"):\r\n        params["video_type"] = video_type\r\n    pace()\r\n    response = requests.get(PIXABAY_URL, params=params, timeout=30)\r\n    response.raise_for_status()\r\n    hits = [h for h in response.json().get("hits", []) if h.get("duration", 0) >= 3]\r\n\r\n    def is_portrait(hit):\r\n        medium = hit["videos"].get("medium", {})\r\n        return medium.get("height", 0) > medium.get("width", 1)\r\n\r\n    # Prefer clips that already match the output shape; others are centre-cropped by the editor\r\n    hits.sort(key=lambda h: 0 if is_portrait(h) == (orientation == "portrait") else 1)\r\n    found = []\r\n    for hit in hits:\r\n        rendition = pick_rendition(hit["videos"], orientation)\r\n        if rendition:\r\n            found.append((hit["id"], rendition["url"], hit.get("user", "Pixabay")))\r\n    return found\r\n\r\n\r\nCANDIDATES = {"pexels": pexels_candidates, "pixabay": pixabay_candidates}\r\n\r\n\r\ndef clip_type(style, index):\r\n    """footage_style -> Pixabay video_type for the index-th clip ("mixed" alternates cartoon and real)."""\r\n    if style == "mixed":\r\n        return "animation" if index % 2 == 0 else "film"\r\n    return style if style in ("animation", "film") else None\r\n\r\n\r\ndef fetch_clips(provider, api_key, terms, destination_dir, prefix, kids=False, style="any",\r\n                orientation="portrait", clips_per_term=1):\r\n    """Download clips_per_term clips for each search term. Returns (file paths, contributor credits).\r\n\r\n    Each term is searched once and several clips are taken from its results, to keep API requests low.\r\n    """\r\n    os.makedirs(destination_dir, exist_ok=True)\r\n    paths, credits, used_ids, cache = [], [], set(), {}\r\n\r\n    def candidates(term, video_type):\r\n        if (term, video_type) not in cache:\r\n            cache[(term, video_type)] = with_retries(\r\n                lambda: CANDIDATES[provider](api_key, term, kids, video_type, orientation))\r\n        return cache[(term, video_type)]\r\n\r\n    def download(url, target):\r\n        with requests.get(url, stream=True, timeout=180) as response:\r\n            response.raise_for_status()\r\n            with open(target, "wb") as f:\r\n                for chunk in response.iter_content(chunk_size=1 << 20):\r\n                    f.write(chunk)\r\n\r\n    index = 0\r\n    for term in terms:\r\n        for _ in range(clips_per_term):\r\n            wanted = clip_type(style, index)\r\n            try:\r\n                pool = [c for c in candidates(term, wanted) if c[0] not in used_ids]\r\n                if not pool and wanted:\r\n                    # e.g. no cartoon clip for this term: take any kind of clip instead\r\n                    pool = [c for c in candidates(term, None) if c[0] not in used_ids]\r\n            except requests.RequestException as e:\r\n                print(f"[Stock footage] {PROVIDERS[provider][\'name\']} search failed for \'{term}\': "\r\n                      f"{safe_error(e, api_key)}")\r\n                break\r\n            if not pool:\r\n                print(f"[Stock footage] No more clips for \'{term}\'.")\r\n                break\r\n            clip_id, url, credit = pool[0]\r\n            used_ids.add(clip_id)\r\n            index += 1\r\n            target = os.path.join(destination_dir, f"{prefix}_clip{index}.mp4")\r\n            try:\r\n                with_retries(lambda: download(url, target))\r\n            except requests.RequestException as e:\r\n                print(f"[Stock footage] Download failed for {PROVIDERS[provider][\'name\']} video {clip_id}: "\r\n                      f"{safe_error(e, api_key)}")\r\n                continue\r\n            paths.append(target)\r\n            credits.append(credit)\r\n            print(f"[Stock footage] \'{term}\' -> {PROVIDERS[provider][\'name\']} video {clip_id} by {credit}")\r\n    return paths, credits\r\n',
    'agents/agent_1_scout.py': 'import os\nimport html\nimport json\nimport random\nfrom datetime import datetime, timedelta, timezone\nfrom googleapiclient.discovery import build\n\n# YouTube\'s relevanceLanguage codes, so results favour videos in the channel\'s narration language\nLANGUAGE_CODES = {"English": "en", "Hindi": "hi", "Telugu": "te"}\n# Don\'t reuse a source channel that supplied any of this channel\'s last N videos (unless nothing else is left)\nRECENT_SOURCES_WINDOW = 5\n\nclass TrendScoutAgent:\n    def __init__(self, config, instructions):\n        self.config = config\n        self.instructions = instructions\n        self.active_key = config["active_profile"]\n        self.profile = config["profiles"][self.active_key]\n        self.manifest_path = config["storage_paths"]["manifest_file"]\n        self.search_cache = {}\n\n        api_key = os.getenv("YOUTUBE_API_KEY")\n        if not api_key:\n            raise ValueError("Missing YOUTUBE_API_KEY in .env file.")\n        self.youtube = build("youtube", "v3", developerKey=api_key)\n\n    def search(self, query, published_after):\n        # Cached per run: retries reuse the same results instead of spending more of the daily search quota\n        if query not in self.search_cache:\n            long_form = self.profile.get("format") == "long"\n            params = dict(\n                part="snippet",\n                # Long videos take their topics from longer trending videos (4 to 20 minutes)\n                q=query.replace("#shorts", "").strip() if long_form else query,\n                type="video",\n                videoDuration="medium" if long_form else "short",\n                order="viewCount",\n                publishedAfter=published_after,\n                maxResults=50,  # same quota cost as 1, and leaves room to skip used or repeated sources\n            )\n            language = LANGUAGE_CODES.get(self.profile.get("language", "English"))\n            if language:\n                params["relevanceLanguage"] = language\n            self.search_cache[query] = self.youtube.search().list(**params).execute().get("items", [])\n        return self.search_cache[query]\n\n    def run(self, limit=None):\n        """Add up to `limit` new videos (default: the channel\'s videos per day) to the manifest.\n\n        Picks rotate across the search phrases, take at most one video per source channel, skip sources\n        used for this channel recently, and never use channels listed in exclude_sources.\n        """\n        print(f"\\n[Agent 1: Scout] Searching trending videos for profile: {self.active_key}...")\n        published_after = (datetime.now(timezone.utc) - timedelta(days=self.profile.get("lookback_days", 5))).isoformat()\n\n        existing_trends = []\n        if os.path.exists(self.manifest_path):\n            with open(self.manifest_path, "r", encoding="utf-8") as f:\n                try:\n                    existing_trends = json.load(f)\n                except json.JSONDecodeError:\n                    existing_trends = []\n\n        existing_ids = {item["video_id"] for item in existing_trends}\n        mine = [item for item in existing_trends if item.get("profile") == self.active_key]\n        recent_sources = {item.get("original_creator", "").lower() for item in mine[-RECENT_SOURCES_WINDOW:]}\n        excluded = {name.lower() for name in self.profile.get("exclude_sources") or []}\n        max_per_run = limit or self.profile["max_videos_per_run"]\n\n        queries = self.profile["search_queries"]\n        # Start from a different phrase each run so single-video runs cover every topic over time\n        offset = len(mine) % len(queries)\n        queries = queries[offset:] + queries[:offset]\n        candidates = {query: self.search(query, published_after) for query in queries}\n\n        new_items, used_sources = [], set()\n        for allow_recent in (False, True):\n            # Round-robin: best unused video from phrase 1, then phrase 2, ... until enough are picked\n            progress = True\n            while len(new_items) < max_per_run and progress:\n                progress = False\n                for query in queries:\n                    if len(new_items) >= max_per_run:\n                        break\n                    pick = self.next_candidate(candidates[query], existing_ids, used_sources, excluded,\n                                               set() if allow_recent else recent_sources)\n                    if pick:\n                        new_items.append(self.entry(pick, query))\n                        existing_ids.add(pick["id"]["videoId"])\n                        used_sources.add(pick["snippet"]["channelTitle"].lower())\n                        progress = True\n            if len(new_items) >= max_per_run:\n                break\n\n        all_trends = existing_trends + new_items\n        with open(self.manifest_path, "w", encoding="utf-8") as f:\n            json.dump(all_trends, f, indent=4, ensure_ascii=False)\n\n        sources = ", ".join(f"{i[\'original_creator\']} ({i[\'genre\']})" for i in new_items) or "none"\n        print(f"[Agent 1: Scout] Added {len(new_items)} new trending videos. Sources: {sources}")\n\n    @staticmethod\n    def next_candidate(items, existing_ids, used_sources, excluded, recent_sources):\n        for item in items:\n            source = item["snippet"]["channelTitle"].lower()\n            if (item["id"]["videoId"] in existing_ids or source in used_sources\n                    or source in excluded or source in recent_sources):\n                continue\n            return item\n        return None\n\n    def entry(self, item, query):\n        vid_id = item["id"]["videoId"]\n        entry_format = self.profile.get("format", "short")\n        minutes = str(self.profile.get("long", {}).get("minutes", 6))\n        if entry_format == "long":\n            # A range such as "5-6" gives every long video its own length, never longer than the upper bound\n            low, _, high = minutes.partition("-")\n            low, high = int(low), int(high or low)\n            target_seconds = random.randint(low * 60, high * 60 - 20) if high > low else low * 60 - 10\n            max_seconds = high * 60 - 5  # leaves room for the end card within the upper limit\n        else:\n            target_seconds = self.profile.get("target_duration_seconds", 30)\n            max_seconds = int(target_seconds * 1.2)\n        return {\n            "video_id": vid_id,\n            "profile": self.active_key,\n            "format": entry_format,\n            "target_seconds": target_seconds,\n            "max_seconds": max_seconds,\n            "genre": query,\n            # The search API returns HTML-escaped text (e.g. &#39; and &amp;)\n            "original_title": html.unescape(item["snippet"]["title"]),\n            "original_description": html.unescape(item["snippet"]["description"]),\n            "original_creator": html.unescape(item["snippet"]["channelTitle"]),\n            "source_url": f"https://www.youtube.com/watch?v={vid_id}",\n            "discovered_at": datetime.now(timezone.utc).isoformat(),\n            "status": "discovered",\n            "raw_video_path": None,\n            "voiceover_path": None,\n            "generated_script": None,\n            "edited_video_path": None,\n            "uploaded_youtube_id": None,\n            "notified_telegram": False\n        }\n',
    'agents/agent_2_downloader.py': 'import os\nimport json\nimport shutil\nimport yt_dlp\n\nfrom brain import item_matches\n\ndef ffmpeg_location():\n    # yt-dlp needs FFmpeg to merge video and audio; fall back to the copy bundled with MoviePy when none is installed\n    if shutil.which("ffmpeg"):\n        return None\n    try:\n        import imageio_ffmpeg\n        return imageio_ffmpeg.get_ffmpeg_exe()\n    except Exception:\n        return None\n\nclass DownloaderAgent:\n    """Gets footage for each discovered topic.\n\n    footage.source in BRAIN.md: "stock" downloads free Pexels clips matching the topic (works everywhere);\n    "youtube" downloads the trending video itself (laptop only: YouTube blocks downloads from cloud servers).\n    """\n    def __init__(self, manifest_path, download_destination_dir, config=None):\n        self.manifest_path = manifest_path\n        self.download_dir = download_destination_dir\n        self.config = config or {}\n        self.footage = self.config.get("footage") or {}\n\n    def run(self, active_profile):\n        print(f"\\n[Agent 2: Downloader] Checking manifest at {self.manifest_path}...")\n        with open(self.manifest_path, "r", encoding="utf-8") as f:\n            trends = json.load(f)\n\n        profile = self.config["profiles"][active_profile]\n        stock = self.footage.get("source", "stock") == "stock" or profile.get("format") == "long"\n        if stock:\n            from google import genai\n            from agents import stock_footage\n            provider, api_key = stock_footage.choose_provider(self.footage.get("provider", "auto"))\n            ai_client = genai.Client(api_key=os.getenv("GEMINI_API_KEY"))\n\n        # Stock footage is chosen after the script is narrated ("voiced"), one clip per scene of the script;\n        # re-used trending videos are downloaded straight after discovery\n        wanted_status = "voiced" if stock else "discovered"\n        for item in trends:\n            if item["status"] == wanted_status and item_matches(item, active_profile, profile):\n                vid_id = item["video_id"]\n                if stock:\n                    self.fetch_stock(item, stock_footage, provider, api_key, ai_client, profile)\n                else:\n                    self.download_source(item, vid_id)\n\n        with open(self.manifest_path, "w", encoding="utf-8") as f:\n            json.dump(trends, f, indent=4, ensure_ascii=False)\n\n    def fetch_stock(self, item, stock_footage, provider, api_key, ai_client, profile):\n        vid_id = item["video_id"]\n        if not provider:\n            print("[Agent 2: Downloader] No stock footage key: add PIXABAY_API_KEY (or PEXELS_API_KEY) "\n                  "to .env / GitHub secrets.")\n            item["status"] = "download_failed"\n            return\n        scenes = item.get("scenes") or [{"start": 0, "end": item.get("voice_seconds", 30), "text": item["original_title"]}]\n        orientation = "landscape" if item.get("format") == "long" else "portrait"\n        terms = stock_footage.scene_terms(ai_client, scenes, item, profile, self.config.get("ai_models"))\n        print(f"[Agent 2: Downloader] {len(scenes)} scenes for \'{item[\'original_title\'][:60]}\'")\n        try:\n            paths, credits, used_terms = stock_footage.fetch_scene_clips(\n                provider, api_key, terms, self.download_dir, f"stock_{vid_id}",\n                kids=profile.get("made_for_kids", False), style=profile.get("footage_style", "any"),\n                orientation=orientation)\n        except Exception as e:\n            print(f"[Agent 2: Downloader] Stock footage failed for {vid_id}: {stock_footage.safe_error(e, api_key)}")\n            paths, credits, used_terms = [], [], []\n        # Sync report: what is said in each scene, and the footage shown with it\n        for scene, used in zip(scenes, used_terms):\n            words = " ".join(scene["text"].split()[:9])\n            print(f"   {int(scene[\'start\']) // 60}:{int(scene[\'start\']) % 60:02d}-{int(scene[\'end\']) // 60}:"\n                  f"{int(scene[\'end\']) % 60:02d}  shows \'{used or \'neighbouring clip\'}\'  while saying: {words}...")\n        if any(paths):\n            # A scene with no clip reuses the nearest earlier (or later) one, so every scene keeps its timing\n            filled, last = [], next(p for p in paths if p)\n            for path in paths:\n                last = path or last\n                filled.append(last)\n            item["footage_paths"] = filled\n            item["scene_terms"] = used_terms\n            item["footage_provider"] = provider\n            item["footage_credits"] = sorted(set(credits))\n            item["raw_video_path"] = filled[0]\n            item["status"] = "ready_to_edit"\n        else:\n            item["status"] = "download_failed"\n\n    def download_source(self, item, vid_id):\n        target_file = os.path.join(self.download_dir, f"raw_{vid_id}.mp4")\n        ydl_opts = {\n            "format": "bestvideo[ext=mp4][height<=1920]+bestaudio[ext=m4a]/best[ext=mp4]/best",\n            "outtmpl": target_file,\n            "merge_output_format": "mp4",\n            "quiet": True,\n            "no_warnings": True,\n            "noprogress": True\n        }\n        if ffmpeg_location():\n            ydl_opts["ffmpeg_location"] = ffmpeg_location()\n\n        try:\n            print(f"[Agent 2: Downloader] Downloading {item[\'source_url\']} -> {target_file}")\n            with yt_dlp.YoutubeDL(ydl_opts) as ydl:\n                ydl.download([item["source_url"]])\n\n            if os.path.exists(target_file):\n                item["raw_video_path"] = target_file\n                item["status"] = "downloaded"\n        except Exception as e:\n            print(f"[Agent 2: Downloader] Error downloading {vid_id}: {e}")\n            item["status"] = "download_failed"\n',
    'agents/agent_3_voiceover.py': 'import os\r\nimport json\r\nimport asyncio\r\nimport edge_tts\r\nfrom google import genai\r\n\r\nfrom agents.ai import generate_text\r\nfrom agents.stock_footage import TERM_PAIR_RULE, footage_rules, parse_scene_hints\r\nfrom brain import item_matches\r\n\r\n# Roughly 150 spoken words per minute, a pace most listeners follow comfortably\r\nWORDS_PER_SECOND = 2.5\r\n# Scripts more than 20% over their target word count are shortened\r\nLENGTH_TOLERANCE = 1.2\r\n# Narration longer than the video\'s maximum length (times this factor) is shortened and narrated again\r\nDURATION_TOLERANCE = 1.0\r\n# Stock footage changes scene about this often in long videos; Shorts use footage.clips_per_video scenes\r\nLONG_SCENE_SECONDS = 15\r\n\r\n\r\ndef stock_mode(config, profile):\r\n    """Stock-footage videos are scripted first, then footage is chosen to match each scene of the script."""\r\n    return (config.get("footage") or {}).get("source", "stock") == "stock" or profile.get("format") == "long"\r\n\r\n\r\ndef group_scenes(sentences, total_seconds, scene_seconds):\r\n    """Group timed sentences into scenes of about scene_seconds; each scene gets one stock clip.\r\n\r\n    sentences: [(start_seconds, text)]. Returns [{"start", "end", "text"}] covering 0..total_seconds.\r\n    """\r\n    if not sentences:\r\n        return [{"start": 0.0, "end": total_seconds, "text": ""}]\r\n    scenes, current = [], {"start": 0.0, "text": []}\r\n    for index, (start, text) in enumerate(sentences):\r\n        if current["text"] and start - current["start"] >= scene_seconds:\r\n            scenes.append({"start": current["start"], "end": start, "text": " ".join(current["text"])})\r\n            current = {"start": start, "text": []}\r\n        current["text"].append(text)\r\n    scenes.append({"start": current["start"], "end": total_seconds, "text": " ".join(current["text"])})\r\n    # Fold a very short final scene into the one before it\r\n    if len(scenes) > 1 and scenes[-1]["end"] - scenes[-1]["start"] < scene_seconds / 3:\r\n        last = scenes.pop()\r\n        scenes[-1]["end"], scenes[-1]["text"] = last["end"], scenes[-1]["text"] + " " + last["text"]\r\n    return scenes\r\n\r\n\r\nMETA_FIELDS = {"TITLE": "seo_title", "DESCRIPTION": "seo_description", "HASHTAGS": "seo_hashtags",\r\n               "FOOTAGE": "topic_terms", "SCENES": "scene_hints"}\r\n\r\n\r\ndef parse_script_reply(text):\r\n    """Split Gemini\'s reply into (narration, {seo_title, seo_description, seo_hashtags, topic_terms}).\r\n\r\n    If the reply ignores the layout, the whole reply is the narration and the publisher writes the title later.\r\n    """\r\n    head, marker, body = text.partition("SCRIPT:")\r\n    if not marker:\r\n        return text.strip(), {}\r\n    meta = {}\r\n    for line in head.splitlines():\r\n        label, _, value = line.strip().lstrip("*# ").partition(":")\r\n        field = META_FIELDS.get(label.strip("* ").upper())\r\n        if field and value.strip():\r\n            meta[field] = value.strip().strip("*").strip().strip(\'"\')\r\n    if "topic_terms" in meta:\r\n        meta["topic_terms"] = [t.strip().strip(\'"\') for t in meta["topic_terms"].split(",") if t.strip()]\r\n    if "scene_hints" in meta:\r\n        meta["scene_hints"] = parse_scene_hints(meta["scene_hints"]) or None\r\n        if not meta["scene_hints"]:\r\n            del meta["scene_hints"]\r\n    return body.strip().strip("*").strip(), meta\r\n\r\n\r\nclass VoiceoverAgent:\r\n    def __init__(self, config, instructions):\r\n        self.config = config\r\n        self.instructions = instructions\r\n        self.active_key = config["active_profile"]\r\n        self.profile = config["profiles"][self.active_key]\r\n        self.paths = config["storage_paths"]\r\n        self.voice = self.profile.get("voice", "en-US-AndrewNeural")\r\n        self.voice_rate = self.profile.get("voice_rate", "-5%")\r\n\r\n        gemini_key = os.getenv("GEMINI_API_KEY")\r\n        if not gemini_key:\r\n            raise ValueError("Missing GEMINI_API_KEY in .env file.")\r\n        self.ai_client = genai.Client(api_key=gemini_key)\r\n\r\n    def generate_script(self, item):\r\n        target_seconds = item.get("target_seconds") or self.profile.get("target_duration_seconds", 30)\r\n        target_words = int(target_seconds * WORDS_PER_SECOND)\r\n        avoid_terms = self.profile.get("avoid_terms") or []\r\n        if item.get("format") == "long":\r\n            task = (\r\n                f"Task: Write an original, engaging narration script of about {target_words} words (about "\r\n                f"{round(target_seconds / 60)} minutes spoken) for a regular YouTube video, not a Short. Open with a "\r\n                "strong hook, then 3 to 5 clearly separated parts (a story with a beginning, middle and end, or an "\r\n                "explanation that builds step by step), keep a lively pace throughout, and end with a short recap and "\r\n                "a question inviting viewers to comment. Describe concrete, visual things (places, objects, animals, "\r\n                "people, actions) so matching footage can be shown for every sentence.\\n"\r\n            )\r\n        else:\r\n            task = (\r\n                f"Task: Write an original, high-retention narration script of about {target_words} words about this "\r\n                "topic for a YouTube Short: commentary, explanation, or a short funny story, whichever fits the "\r\n                "channel\'s tone and the master instructions.\\n"\r\n            )\r\n\r\n        prompt = (\r\n            f"Follow these master BRAIN instructions strictly:\\n{self.instructions}\\n\\n"\r\n            f"Profile: {self.active_key}\\n"\r\n            f"Channel Niche: {self.profile.get(\'niche\', self.active_key)}\\n"\r\n            f"Required Tone: {self.profile[\'tone\']}\\n"\r\n            f"Script Language: {self.profile.get(\'language\', \'English\')} (write in its native script)\\n"\r\n            f"Source Video Title: {item[\'original_title\']}\\n"\r\n            f"Source Video Context: {item[\'original_description\'][:300]}\\n\\n"\r\n            + task\r\n        )\r\n        if avoid_terms:\r\n            prompt += f"Never use these words or topics: {\', \'.join(avoid_terms)}.\\n"\r\n        long = item.get("format") == "long"\r\n        prompt += (\r\n            f"Stay within {target_words} words; a little shorter is fine, longer is not. The narration must be "\r\n            "only spoken text: no stage directions, no brackets, no intro labels.\\n\\n"\r\n            # The upload title and footage ideas come from this same request, so each video costs one call\r\n            "Reply in exactly this layout:\\n"\r\n            f"TITLE: a {\'click-worthy YouTube video\' if long else \'viral YouTube Short\'} title, at most "\r\n            f"{70 if long else 60} characters, no quotes, in the script language\\n"\r\n            f"DESCRIPTION: a {3 if long else 2}-sentence SEO description in the script language, with no credits "\r\n            "or source names (credits are added automatically)\\n"\r\n            "HASHTAGS: 5 hashtags separated by spaces that people actively search on YouTube for this topic right "\r\n            "now: 2 broad, popular ones for the niche and 3 specific to this story (no spaces inside a hashtag"\r\n            f"{\', do not use #shorts\' if long else \'\'})\\n"\r\n            "FOOTAGE: 5 English stock-footage search terms (1 to 3 words each, comma-separated) for visuals "\r\n            "that match the whole topic"\r\n            + (", child-friendly" if self.profile.get("made_for_kids") else "") + "\\n"\r\n        )\r\n        if not long:\r\n            # A Short has a few equal scenes, so footage for each is chosen here instead of in a second request\r\n            clips = int((self.config.get("footage") or {}).get("clips_per_video", 3))\r\n            prompt += (\r\n                f"SCENES: split the narration into {clips} equal parts in order and, for each part, give "\r\n                + TERM_PAIR_RULE + footage_rules(self.profile)\r\n                + f" Write them on this one line as \'specific | backup\' pairs separated by \' ; \' ({clips} pairs)\\n"\r\n            )\r\n        prompt += "SCRIPT:\\n<the narration>"\r\n\r\n        script, meta = parse_script_reply(generate_text(self.ai_client, prompt, self.config.get("ai_models")))\r\n        item.update(meta)\r\n        return self.fit_length(script, target_words)\r\n\r\n    def fit_length(self, script, target_words):\r\n        """Keep the video near its target length: Gemini sometimes writes far more than asked."""\r\n        limit = int(target_words * LENGTH_TOLERANCE)\r\n        if len(script.split()) <= limit:\r\n            return script\r\n        print(f"[Agent 3: Voiceover] Script is {len(script.split())} words (target {target_words}); shortening...")\r\n        try:\r\n            script = generate_text(self.ai_client, (\r\n                f"Shorten this narration script to at most {target_words} words. Keep the opening hook, the main "\r\n                "story or explanation, and the ending (recap and question). Same language and tone. Output ONLY "\r\n                f"the shortened narration text.\\n\\n{script}"\r\n            ), self.config.get("ai_models"))\r\n        except Exception as e:\r\n            print(f"[Agent 3: Voiceover] Could not shorten with Gemini ({e}); trimming instead.")\r\n        words = script.split()\r\n        if len(words) <= limit:\r\n            return script\r\n        # Last resort: cut at the final sentence ending before the limit\r\n        trimmed = " ".join(words[:limit])\r\n        cut = max(trimmed.rfind(mark) for mark in (". ", "! ", "? ", "। "))\r\n        return trimmed[:cut + 1] if cut > len(trimmed) // 2 else trimmed\r\n\r\n    def synthesize_voice(self, script_text, video_id):\r\n        """Narrate the script; returns (mp3 path, spoken seconds, [(sentence start seconds, sentence text)])."""\r\n        out_mp3 = os.path.join(self.paths["audio_renders"], f"vo_{self.active_key}_{video_id}.mp3")\r\n        print(f"[Agent 3: Voiceover] Narrating video {video_id} with {self.voice} ({self.voice_rate})...")\r\n\r\n        async def narrate():\r\n            communicate = edge_tts.Communicate(script_text, self.voice, rate=self.voice_rate,\r\n                                               boundary="SentenceBoundary")\r\n            sentences, end = [], 0.0\r\n            with open(out_mp3, "wb") as f:\r\n                async for chunk in communicate.stream():\r\n                    if chunk["type"] == "audio":\r\n                        f.write(chunk["data"])\r\n                    elif chunk["type"] == "SentenceBoundary":\r\n                        start = chunk["offset"] / 1e7\r\n                        sentences.append((start, chunk["text"]))\r\n                        end = max(end, start + chunk["duration"] / 1e7)\r\n            return sentences, end\r\n\r\n        sentences, end = asyncio.run(narrate())\r\n        return out_mp3, end + 0.5, sentences\r\n\r\n    def narrate_within_limit(self, item, script):\r\n        """Narrate, and if the spoken length runs past the video\'s maximum, shorten the script and narrate again."""\r\n        max_seconds = item.get("max_seconds")\r\n        vo_path, seconds, sentences = self.synthesize_voice(script, item["video_id"])\r\n        if max_seconds and seconds > max_seconds * DURATION_TOLERANCE:\r\n            words = len(script.split())\r\n            # Aim for the video\'s target length (inside the allowed range), not just under the maximum\r\n            goal_seconds = min(item.get("target_seconds") or max_seconds, max_seconds)\r\n            target_words = int(words * goal_seconds / seconds)\r\n            print(f"[Agent 3: Voiceover] Narration is {seconds / 60:.1f} min, over the {max_seconds / 60:.1f} min "\r\n                  f"limit; shortening to about {target_words} words...")\r\n            script = self.fit_length(script, target_words) if words > target_words * LENGTH_TOLERANCE else script\r\n            if len(script.split()) > target_words:\r\n                script = " ".join(script.split()[:target_words])\r\n            vo_path, seconds, sentences = self.synthesize_voice(script, item["video_id"])\r\n        return script, vo_path, seconds, sentences\r\n\r\n    def run(self):\r\n        manifest_path = self.paths["manifest_file"]\r\n        with open(manifest_path, "r", encoding="utf-8") as f:\r\n            trends = json.load(f)\r\n\r\n        # Stock videos are scripted straight after discovery (footage is chosen afterwards to match the script);\r\n        # re-used trending videos are scripted after their download\r\n        stock = stock_mode(self.config, self.profile)\r\n        wanted_status = "discovered" if stock else "downloaded"\r\n        scene_seconds = LONG_SCENE_SECONDS\r\n\r\n        for item in trends:\r\n            if item["status"] == wanted_status and item_matches(item, self.active_key, self.profile):\r\n                vid_id = item["video_id"]\r\n                try:\r\n                    script = self.generate_script(item)\r\n                    script, vo_path, seconds, sentences = self.narrate_within_limit(item, script)\r\n                    item["generated_script"] = script\r\n                    item["voiceover_path"] = vo_path\r\n                    item["voice_seconds"] = round(seconds, 2)\r\n                    if stock:\r\n                        if item.get("format") != "long":\r\n                            scene_seconds = seconds / int((self.config.get("footage") or {}).get("clips_per_video", 3))\r\n                        item["scenes"] = group_scenes(sentences, seconds, scene_seconds)\r\n                        print(f"[Agent 3: Voiceover] {seconds / 60:.1f} min of narration in {len(item[\'scenes\'])} scenes")\r\n                    item["status"] = "voiced"\r\n                except Exception as e:\r\n                    print(f"[Agent 3: Voiceover] Failed on {vid_id}: {e}")\r\n\r\n        with open(manifest_path, "w", encoding="utf-8") as f:\r\n            json.dump(trends, f, indent=4, ensure_ascii=False)\r\n',
    'agents/agent_4_editor.py': 'import os\nimport json\nimport shutil\nimport subprocess\nimport tempfile\nimport textwrap\nimport imageio_ffmpeg\nimport numpy as np\nfrom PIL import Image, ImageColor, ImageDraw, ImageEnhance, ImageFilter, ImageFont, ImageOps\nfrom moviepy.editor import (VideoFileClip, AudioFileClip, ImageClip, CompositeVideoClip, CompositeAudioClip,\n                            concatenate_videoclips)\n\nfrom agents.branding import channel_logo\nfrom brain import item_matches\n\nSHORT_SIZE, LONG_SIZE = (1080, 1920), (1920, 1080)\n\n# MoviePy 1.0.3\'s resize uses Image.ANTIALIAS, which Pillow 10 removed (LANCZOS is the same filter)\nif not hasattr(Image, "ANTIALIAS"):\n    Image.ANTIALIAS = Image.LANCZOS\n\n# Bold fonts tried in order: Windows, macOS, then the DejaVu font present on GitHub\'s Ubuntu runners\nFONT_CANDIDATES = [\n    "arialbd.ttf",\n    "Arial Bold.ttf",\n    "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",\n    "DejaVuSans-Bold.ttf",\n]\nWATERMARK_MARGIN = 24\n\n\ndef load_font(size):\n    for candidate in FONT_CANDIDATES:\n        try:\n            return ImageFont.truetype(candidate, size)\n        except OSError:\n            continue\n    return ImageFont.load_default(size=size)\n\n\ndef ffmpeg(*args):\n    """Run FFmpeg (the system copy, or the one bundled with MoviePy) and raise if it fails."""\n    exe = shutil.which("ffmpeg") or imageio_ffmpeg.get_ffmpeg_exe()\n    result = subprocess.run([exe, "-y", "-hide_banner", "-loglevel", "error", *map(str, args)],\n                            capture_output=True, text=True)\n    if result.returncode != 0:\n        raise RuntimeError(f"FFmpeg failed: {result.stderr.strip()[-500:]}")\n\n\ndef watermark_image(text, fontsize, color, opacity=1.0):\n    """The watermark as a transparent PIL image (white text with a dark outline)."""\n    font = load_font(fontsize)\n    stroke = max(1, fontsize // 12)\n    left, top, right, bottom = ImageDraw.Draw(Image.new("RGBA", (1, 1))).textbbox(\n        (0, 0), text, font=font, stroke_width=stroke\n    )\n    image = Image.new("RGBA", (right - left + 4, bottom - top + 4), (0, 0, 0, 0))\n    ImageDraw.Draw(image).text(\n        (2 - left, 2 - top), text, font=font, fill=ImageColor.getrgb(color),\n        stroke_width=stroke, stroke_fill=(0, 0, 0)\n    )\n    if opacity < 1:\n        image.putalpha(image.getchannel("A").point(lambda a: int(a * opacity)))\n    return image\n\n\ndef render_watermark(text, fontsize, color):\n    # Drawn with Pillow instead of MoviePy\'s TextClip, so ImageMagick is not needed\n    font = load_font(fontsize)\n    stroke = max(1, fontsize // 12)\n    left, top, right, bottom = ImageDraw.Draw(Image.new("RGBA", (1, 1))).textbbox(\n        (0, 0), text, font=font, stroke_width=stroke\n    )\n    image = Image.new("RGBA", (right - left + 4, bottom - top + 4), (0, 0, 0, 0))\n    ImageDraw.Draw(image).text(\n        (2 - left, 2 - top), text, font=font, fill=ImageColor.getrgb(color),\n        stroke_width=stroke, stroke_fill=(0, 0, 0)\n    )\n    return ImageClip(np.array(image))\n\n\ndef draw_button(draw, width, scale, center_y, text, fill, text_color, font):\n    left, top, right, bottom = draw.textbbox((0, 0), text, font=font)\n    pad_x, pad_y = int(scale * 0.08), int(scale * 0.035)\n    box_w, box_h = (right - left) + 2 * pad_x, (bottom - top) + 2 * pad_y\n    x0, y0 = (width - box_w) // 2, center_y - box_h // 2\n    draw.rounded_rectangle((x0, y0, x0 + box_w, y0 + box_h), radius=box_h // 2, fill=fill)\n    draw.text((x0 + pad_x - left, y0 + pad_y - top), text, font=font, fill=text_color)\n\n\ndef render_end_card(background, logo_path, channel_name, like_text, subscribe_text, show_subscribe):\n    """One end-card frame: blurred last frame, round logo, channel name, then the LIKE / SUBSCRIBE buttons."""\n    w, h = background.size\n    s = min(w, h)  # sizes follow the shorter side, so the card fits both vertical Shorts and landscape videos\n    card = background.convert("RGB").filter(ImageFilter.GaussianBlur(radius=max(8, s // 40)))\n    card = ImageEnhance.Brightness(card).enhance(0.4).convert("RGBA")\n    draw = ImageDraw.Draw(card)\n\n    diameter, center_y = int(s * 0.34), int(h * 0.30)\n    if logo_path:\n        logo = ImageOps.fit(Image.open(logo_path).convert("RGBA"), (diameter, diameter))\n        mask = Image.new("L", (diameter, diameter), 0)\n        ImageDraw.Draw(mask).ellipse((0, 0, diameter, diameter), fill=255)\n        ring = int(s * 0.012)\n        draw.ellipse((w // 2 - diameter // 2 - ring, center_y - diameter // 2 - ring,\n                      w // 2 + diameter // 2 + ring, center_y + diameter // 2 + ring), fill=(255, 255, 255))\n        card.paste(logo, (w // 2 - diameter // 2, center_y - diameter // 2), mask)\n\n    wide = w > h\n    if logo_path:\n        name_font = load_font(int(s * 0.065))\n        y = center_y + diameter // 2 + int(s * 0.06)\n        wrap_width = 30 if wide else 18\n    else:\n        # No logo: the channel name becomes the centrepiece, larger and where the logo would be\n        name_font = load_font(int(s * 0.105))\n        y = int(h * (0.22 if wide else 0.30))\n        wrap_width = 24 if wide else 14\n    for line in textwrap.wrap(channel_name, width=wrap_width):\n        left, top, right, bottom = draw.textbbox((0, 0), line, font=name_font)\n        draw.text(((w - (right - left)) // 2 - left, y - top), line, font=name_font, fill=(255, 255, 255))\n        y += (bottom - top) + int(s * 0.02)\n\n    button_font = load_font(int(s * 0.07))\n    like_y, subscribe_y = (int(h * 0.58), int(h * 0.78)) if wide else (int(h * 0.62), int(h * 0.75))\n    if show_subscribe:\n        # LIKE stays on screen as "pressed", and SUBSCRIBE appears last\n        draw_button(draw, w, s, like_y, like_text, (6, 95, 212), (255, 255, 255), button_font)\n        draw_button(draw, w, s, subscribe_y, subscribe_text, (204, 0, 0), (255, 255, 255), button_font)\n    else:\n        draw_button(draw, w, s, like_y, like_text, (255, 255, 255), (20, 20, 20), button_font)\n    return np.array(card.convert("RGB"))\n\n\nclass VideoEditorAgent:\n    def __init__(self, config):\n        self.config = config\n        self.active_key = config["active_profile"]\n        self.profile = config["profiles"][self.active_key]\n        self.rules = config["editing_rules"]\n        self.paths = config["storage_paths"]\n\n    def end_card_frames(self, background):\n        """The two end-card frames (LIKE, then LIKE + SUBSCRIBE) and their durations, or None when disabled."""\n        settings = self.rules.get("end_card") or {}\n        if not settings.get("enabled", True):\n            return None\n        seconds = float(settings.get("seconds", 3))\n        branding_dir = self.paths.get("branding_dir", os.path.join(self.paths["base_dir"], "00_branding"))\n        logo = channel_logo(self.profile, self.active_key, branding_dir) if settings.get("show_logo", False) else None\n        frames = [\n            render_end_card(background, logo, self.profile["channel_name"],\n                            settings.get("like_text", "LIKE"), settings.get("subscribe_text", "SUBSCRIBE"), show)\n            for show in (False, True)\n        ]\n        # LIKE alone first, then SUBSCRIBE joins it for the rest of the card\n        return list(zip(frames, (seconds * 0.45, seconds * 0.55)))\n\n    def end_card_clip(self, video):\n        """The closing card as a MoviePy clip (used when re-using a trending video)."""\n        card = self.end_card_frames(Image.fromarray(video.get_frame(max(0, video.duration - 0.1))))\n        if card is None:\n            return None\n        return concatenate_videoclips([ImageClip(frame).set_duration(seconds) for frame, seconds in card])\n\n    def render_stock(self, item, output_video):\n        """Build a stock-footage video entirely with FFmpeg: much faster than MoviePy for long videos.\n\n        Each clip is cut to its scene\'s narration time, scaled and cropped to the frame, joined, then the\n        watermark, narration and end card are added in a single final encode.\n        """\n        width, height = LONG_SIZE if item.get("format") == "long" else SHORT_SIZE\n        voice = AudioFileClip(item["voiceover_path"])\n        duration = voice.duration\n        voice.close()\n        clips = item["footage_paths"]\n        scenes = item.get("scenes") or []\n        if len(scenes) == len(clips):\n            # Each clip plays exactly while its scene is narrated; the last one runs to the end of the narration\n            lengths = [max(0.5, s["end"] - s["start"]) for s in scenes]\n            lengths[-1] = max(0.5, duration - scenes[-1]["start"])\n        else:\n            lengths = [duration / len(clips)] * len(clips)\n        fit = (f"scale={width}:{height}:force_original_aspect_ratio=increase,crop={width}:{height},"\n               f"setsar=1,fps=30,format=yuv420p")\n\n        work = tempfile.mkdtemp(prefix="render_", dir=self.paths["processed_videos"])\n        try:\n            parts = []\n            for index, clip in enumerate(clips):\n                part = os.path.join(work, f"part{index:03d}.mp4")\n                # -stream_loop repeats clips shorter than their share\n                ffmpeg("-stream_loop", "-1", "-i", clip, "-t", f"{lengths[index]:.3f}", "-an", "-vf", fit,\n                       "-c:v", "libx264", "-preset", "veryfast", "-crf", "23", part)\n                parts.append(part)\n            with open(os.path.join(work, "parts.txt"), "w", encoding="utf-8") as f:\n                f.writelines(f"file \'{os.path.basename(p)}\'\\n" for p in parts)\n            montage = os.path.join(work, "montage.mp4")\n            ffmpeg("-f", "concat", "-safe", "0", "-i", os.path.join(work, "parts.txt"), "-c", "copy", montage)\n\n            mark = os.path.join(work, "watermark.png")\n            watermark_image(self.profile["watermark_text"], self.rules["watermark_fontsize"],\n                            self.rules["watermark_color"], self.rules["watermark_opacity"]).save(mark)\n\n            last_frame = os.path.join(work, "last.png")\n            ffmpeg("-sseof", "-0.2", "-i", montage, "-frames:v", "1", last_frame)\n            card = self.end_card_frames(Image.open(last_frame).convert("RGB"))\n\n            inputs = ["-i", montage, "-i", item["voiceover_path"], "-i", mark]\n            graph = (f"[0:v][2:v]overlay=W-w-{WATERMARK_MARGIN}:H-h-{WATERMARK_MARGIN},format=yuv420p,setsar=1[main];"\n                     "[1:a]aresample=44100,aformat=channel_layouts=stereo[voice];")\n            if card:\n                for index, (frame, seconds) in enumerate(card):\n                    path = os.path.join(work, f"card{index}.png")\n                    Image.fromarray(frame).save(path)\n                    inputs += ["-loop", "1", "-t", f"{seconds:.3f}", "-i", path,\n                               "-f", "lavfi", "-t", f"{seconds:.3f}", "-i", "anullsrc=r=44100:cl=stereo"]\n                graph += ("[3:v]fps=30,format=yuv420p,setsar=1[c0];[5:v]fps=30,format=yuv420p,setsar=1[c1];"\n                          "[main][voice][c0][4:a][c1][6:a]concat=n=3:v=1:a=1[v][a]")\n            else:\n                graph += "[main]null[v];[voice]anull[a]"\n            ffmpeg(*inputs, "-filter_complex", graph, "-map", "[v]", "-map", "[a]",\n                   "-c:v", "libx264", "-preset", "veryfast", "-crf", "23", "-c:a", "aac", "-b:a", "160k",\n                   "-movflags", "+faststart", output_video)\n        finally:\n            shutil.rmtree(work, ignore_errors=True)\n\n    def run(self):\n        manifest_path = self.paths["manifest_file"]\n        with open(manifest_path, "r", encoding="utf-8") as f:\n            trends = json.load(f)\n\n        for item in trends:\n            # Stock videos are ready once their scene clips are in; re-used trending videos once narrated\n            ready = item["status"] == "ready_to_edit" or (item["status"] == "voiced" and not item.get("scenes"))\n            if ready and item_matches(item, self.active_key, self.profile):\n                vid_id = item["video_id"]\n                raw_video = item["raw_video_path"]\n                vo_audio = item["voiceover_path"]\n                output_video = os.path.join(\n                    self.paths["processed_videos"], f"final_{self.active_key}_{vid_id}.mp4"\n                )\n\n                print(f"\\n[Agent 4: Editor] Editing & Watermarking {vid_id}...")\n                if item.get("footage_paths"):\n                    try:\n                        self.render_stock(item, output_video)\n                        item["edited_video_path"] = output_video\n                        item["status"] = "edited"\n                        print(f"[Agent 4: Editor] Saved final video to {output_video}")\n                    except Exception as e:\n                        print(f"[Agent 4: Editor] Error editing {vid_id}: {e}")\n                    continue\n                try:\n                    # Re-used trending video (footage.source "youtube"): edited with MoviePy\n                    voice_clip = AudioFileClip(vo_audio)\n                    video_clip = VideoFileClip(raw_video)\n                    sources = [video_clip]\n                    # Loop or trim the picture only; looping a clip\'s audio in MoviePy 1.0.3 reads past its end\n                    original_audio = video_clip.audio\n                    picture = video_clip.without_audio()\n                    if picture.duration < voice_clip.duration:\n                        picture = picture.loop(duration=voice_clip.duration)\n                    else:\n                        picture = picture.subclip(0, voice_clip.duration)\n\n                    # Zoom in, then crop back to the original frame size around the centre\n                    width, height = picture.size\n                    transformed_video = picture.resize(self.rules["zoom_factor"]).crop(\n                        x_center=width * self.rules["zoom_factor"] / 2,\n                        y_center=height * self.rules["zoom_factor"] / 2,\n                        width=width - width % 2,\n                        height=height - height % 2,\n                    )\n\n                    # original_audio_volume 0 means the source\'s sound is dropped and only the AI voice is heard\n                    if original_audio is not None and self.rules.get("original_audio_volume", 0) > 0:\n                        bg_end = max(0, min(original_audio.duration - 0.1, voice_clip.duration))\n                        bg_audio = original_audio.subclip(0, bg_end).volumex(self.rules["original_audio_volume"])\n                        mixed_audio = CompositeAudioClip([bg_audio, voice_clip])\n                    else:\n                        mixed_audio = voice_clip\n\n                    transformed_video = transformed_video.set_audio(mixed_audio)\n\n                    watermark = render_watermark(\n                        self.profile["watermark_text"],\n                        self.rules["watermark_fontsize"],\n                        self.rules["watermark_color"],\n                    )\n                    watermark = (\n                        watermark\n                        .set_opacity(self.rules["watermark_opacity"])\n                        .set_position((\n                            transformed_video.w - watermark.w - WATERMARK_MARGIN,\n                            transformed_video.h - watermark.h - WATERMARK_MARGIN,\n                        ))\n                        .set_duration(transformed_video.duration)\n                    )\n\n                    final_clip = CompositeVideoClip([transformed_video, watermark])\n                    end_card = self.end_card_clip(transformed_video)\n                    if end_card is not None:\n                        final_clip = concatenate_videoclips([final_clip, end_card])\n                    final_clip.write_videofile(\n                        output_video,\n                        codec="libx264",\n                        audio_codec="aac",\n                        fps=30,\n                        # Long videos use a faster encoder setting so a 6-minute render stays quick\n                        preset="veryfast" if item.get("format") == "long" else "medium",\n                        threads=os.cpu_count() or 2,\n                        logger=None\n                    )\n\n                    for source in sources:\n                        source.close()\n                    voice_clip.close()\n                    final_clip.close()\n\n                    item["edited_video_path"] = output_video\n                    item["status"] = "edited"\n                    print(f"[Agent 4: Editor] Saved final video to {output_video}")\n                except Exception as e:\n                    print(f"[Agent 4: Editor] Error editing {vid_id}: {e}")\n\n        with open(manifest_path, "w", encoding="utf-8") as f:\n            json.dump(trends, f, indent=4, ensure_ascii=False)\n',
    'agents/agent_5_publisher.py': 'import os\r\nimport re\r\nimport json\r\nfrom datetime import datetime, timedelta, timezone\r\nfrom google import genai\r\nfrom google_auth_oauthlib.flow import InstalledAppFlow\r\nfrom google.auth.transport.requests import Request\r\nfrom google.oauth2.credentials import Credentials\r\nfrom googleapiclient.discovery import build\r\nfrom googleapiclient.errors import HttpError\r\nfrom googleapiclient.http import MediaFileUpload\r\nimport time\r\n\r\nfrom agents.ai import generate_text\r\nfrom brain import YOUTUBE_SCOPES as SCOPES, channel_matches, item_matches\r\n\r\nUPLOAD_CHUNK_BYTES = 8 * 1024 * 1024\r\nUPLOAD_RETRIES = 5\r\nPASSED_SLOT_GAP = timedelta(minutes=30)\r\nMAX_HASHTAGS = 8\r\n\r\nclass PublisherAgent:\r\n    def __init__(self, config, instructions):\r\n        self.config = config\r\n        self.instructions = instructions\r\n        self.active_key = config["active_profile"]\r\n        self.profile = config["profiles"][self.active_key]\r\n        self.upload_rules = config["upload_rules"]\r\n        self.paths = config["storage_paths"]\r\n        self.ai_client = genai.Client(api_key=os.getenv("GEMINI_API_KEY"))\r\n\r\n    def get_authenticated_service(self):\r\n        tokens_dir = self.paths.get("tokens_dir", ".")\r\n        token_file = os.path.join(tokens_dir, f"token_{self.active_key}.json")\r\n        creds = None\r\n\r\n        if os.path.exists(token_file):\r\n            creds = Credentials.from_authorized_user_file(token_file, SCOPES)\r\n\r\n        if not creds or not creds.valid:\r\n            if creds and creds.expired and creds.refresh_token:\r\n                creds.refresh(Request())\r\n            else:\r\n                if os.getenv("GITHUB_ACTIONS") == "true":\r\n                    raise RuntimeError(\r\n                        f"YouTube login for \'{self.active_key}\' is missing or expired. Run "\r\n                        f"\'python execution/execution.py --authorize {self.active_key}\' on your laptop "\r\n                        "and upload the token file to Google Drive: YouTube_Automation/00_tokens/"\r\n                    )\r\n                print(f"\\n[!] Please select the \'{self.profile[\'channel_name\']}\' Brand Channel in the browser popup!")\r\n                flow = InstalledAppFlow.from_client_secrets_file("client_secret.json", SCOPES)\r\n                creds = flow.run_local_server(port=0)\r\n            os.makedirs(tokens_dir, exist_ok=True)\r\n            with open(token_file, "w") as token:\r\n                token.write(creds.to_json())\r\n\r\n        youtube = build("youtube", "v3", credentials=creds)\r\n        self.verify_channel(youtube)\r\n        return youtube\r\n\r\n    def verify_channel(self, youtube):\r\n        # Stop before uploading if this login belongs to a different channel than channels.yaml says\r\n        items = youtube.channels().list(part="snippet", mine=True).execute().get("items", [])\r\n        if not items:\r\n            raise RuntimeError(f"The YouTube login for \'{self.active_key}\' has no channel.")\r\n        channel_id, snippet = items[0]["id"], items[0]["snippet"]\r\n        if not channel_matches(self.profile["channel_url"], channel_id, snippet.get("customUrl")):\r\n            raise RuntimeError(\r\n                f"The YouTube login for \'{self.active_key}\' is for \'{snippet[\'title\']}\' ({channel_id}), "\r\n                f"not {self.profile[\'channel_url\']}. Run --authorize {self.active_key} again and pick the right channel."\r\n            )\r\n        print(f"[Agent 5: Publisher] Confirmed channel: {snippet[\'title\']}")\r\n\r\n    @staticmethod\r\n    def fallback_seo_package(item, max_title):\r\n        """Used when Gemini is unavailable: the source video\'s own title, and the opening of our narration."""\r\n        title = re.sub(r"#\\w+", "", item.get("original_title") or "").replace(\'"\', "")\r\n        title = " ".join(title.split()).strip(" |-:") or "New video"\r\n        if len(title) > max_title:\r\n            title = title[:max_title - 3].rsplit(" ", 1)[0] + "..."\r\n        script = " ".join((item.get("generated_script") or "").split())\r\n        sentences = [s.strip() for s in re.split(r"(?<=[.!?])\\s+", script) if s.strip()]\r\n        return title, " ".join(sentences[:2])[:400]\r\n\r\n    def generate_seo_package(self, item):\r\n        clean_creator_name = item["original_creator"].replace("@", "").strip()\r\n        max_title = 75 if item.get("format") == "long" else 65\r\n        if item.get("seo_title"):\r\n            # Written together with the script, so no extra Gemini request is needed\r\n            new_title = item["seo_title"].replace(\'"\', \'\').strip()[:max_title]\r\n            return new_title, self.finish_description(item, item.get("seo_description") or "",\r\n                                                      item.get("seo_hashtags") or "", clean_creator_name)\r\n\r\n        prompt = (\r\n            f"Follow these system instructions: {self.instructions}\\n"\r\n            f"Profile: {self.active_key}\\n"\r\n            f"Original Title: {item[\'original_title\']}\\n"\r\n            f"Our Voiceover Script: {item[\'generated_script\']}\\n"\r\n            f"Language for title, description and hashtags: {self.profile.get(\'language\', \'English\')}\\n\\n"\r\n            + ("Generate a click-worthy YouTube video title (maximum 70 characters, no quotes) on Line 1.\\n"\r\n               "On the following lines, write a 3-sentence SEO description followed by 5 relevant hashtags "\r\n               "(do not use #shorts)."\r\n               if item.get("format") == "long" else\r\n               "Generate a viral YouTube Short Title (maximum 60 characters, no quotes) on Line 1.\\n"\r\n               "On the following lines, write a 2-sentence SEO description followed by 5 relevant hashtags.")\r\n        )\r\n        try:\r\n            resp = generate_text(self.ai_client, prompt, self.config.get("ai_models")).split("\\n")\r\n            new_title = resp[0].replace(\'"\', \'\').strip()[:max_title]\r\n            seo_body = "\\n".join(resp[1:]).strip()\r\n        except Exception as e:\r\n            # Gemini quota ran out or it is down: the video is already rendered, so publish it under the\r\n            # source video\'s title instead of losing the slot\r\n            print(f"[Agent 5: Publisher] Gemini could not write the title for {item[\'video_id\']}, "\r\n                  f"using the source video\'s title: {str(e)[:160]}")\r\n            new_title, seo_body = self.fallback_seo_package(item, max_title)\r\n\r\n        # Gemini\'s hashtags may sit inside the text; gather them so they are merged with the trending ones\r\n        gemini_tags = " ".join(re.findall(r"#\\w+", seo_body))\r\n        seo_body = "\\n".join(line for line in seo_body.splitlines() if not re.fullmatch(r"(\\s*#\\w+)+\\s*", line))\r\n        return new_title, self.finish_description(item, seo_body.strip(), gemini_tags, clean_creator_name)\r\n\r\n    def hashtags(self, item, gemini_tags):\r\n        """Topic hashtags from Gemini plus the ones the trending source video uses, without the source\'s own brand.\r\n\r\n        Shorts start with #shorts. YouTube shows the first three above the title and ignores all of them past 60,\r\n        so at most MAX_HASHTAGS are kept.\r\n        """\r\n        source_text = f"{item.get(\'original_title\') or \'\'} {item.get(\'original_description\') or \'\'}"\r\n        creator = re.sub(r"\\W", "", (item.get("original_creator") or "").lower())\r\n        trending = [t for t in re.findall(r"#\\w+", source_text)\r\n                    if not (creator and (creator in t.lower() or t.lower().lstrip("#") in creator))]\r\n        tags = (["#shorts"] if item.get("format") != "long" else []) + re.findall(r"#\\w+", gemini_tags) + trending\r\n        if len(tags) <= 1:\r\n            # Nothing from Gemini or the source: fall back to the channel\'s niche words\r\n            tags += ["#" + w.lower() for w in re.findall(r"[A-Za-z]{4,}", self.profile.get("niche", ""))][:4]\r\n        unique = {}\r\n        for tag in tags:\r\n            if item.get("format") == "long" and tag.lower() == "#shorts":\r\n                continue\r\n            unique.setdefault(tag.lower(), tag)\r\n        return list(unique.values())[:MAX_HASHTAGS]\r\n\r\n    def search_tags(self, item):\r\n        """YouTube\'s hidden search tags: the hashtags as words, the footage topic terms and the channel name."""\r\n        tags = [t.lstrip("#") for t in item.get("upload_hashtags") or []] + list(item.get("topic_terms") or []) + \\\r\n            [self.profile["channel_name"].replace(" ", "")]\r\n        kept, length = [], 0\r\n        for tag in dict.fromkeys(t.strip() for t in tags if t.strip()):\r\n            # YouTube rejects the upload if the tags add up to more than 500 characters\r\n            if length + len(tag) + 3 > 450:\r\n                break\r\n            kept.append(tag)\r\n            length += len(tag) + 3\r\n        return kept\r\n\r\n    def finish_description(self, item, text, gemini_tags, clean_creator_name):\r\n        tags = self.hashtags(item, gemini_tags)\r\n        item["upload_hashtags"] = tags\r\n        return "\\n\\n".join(p for p in (text, " ".join(tags)) if p) + self.credit_block(item, clean_creator_name)\r\n\r\n    def credit_block(self, item, clean_creator_name):\r\n        if item.get("footage_paths"):\r\n            # Pixabay and Pexels ask that you show where the footage came from\r\n            site = {"pexels": ("Pexels", "https://www.pexels.com")}.get(item.get("footage_provider"),\r\n                                                                         ("Pixabay", "https://pixabay.com"))\r\n            return (\r\n                f"\\n\\n---\\n"\r\n                f"Stock footage: {site[0]} ({site[1]}), videos by {\', \'.join(item.get(\'footage_credits\') or [site[0]])}\\n"\r\n                f"Commentary produced by {self.profile[\'channel_name\']}."\r\n            )\r\n        return (\r\n            f"\\n\\n---\\n"\r\n            f"Visual Reference & Credit: {clean_creator_name}\\n"\r\n            f"Commentary and analysis produced by {self.profile[\'channel_name\']} under Fair Use guidelines."\r\n        )\r\n\r\n    @staticmethod\r\n    def upload(youtube, path, body):\r\n        """Upload in 8 MB chunks, resuming after dropped connections, so long videos survive a shaky network."""\r\n        media = MediaFileUpload(path, chunksize=UPLOAD_CHUNK_BYTES, resumable=True)\r\n        request = youtube.videos().insert(part="snippet,status", body=body, media_body=media)\r\n        response, failures = None, 0\r\n        while response is None:\r\n            try:\r\n                status, response = request.next_chunk()\r\n                failures = 0\r\n                if status:\r\n                    print(f"[Agent 5: Publisher] Uploaded {int(status.progress() * 100)}%")\r\n            except (HttpError, OSError) as e:\r\n                retryable = not isinstance(e, HttpError) or e.resp.status in (500, 502, 503, 504)\r\n                failures += 1\r\n                if not retryable or failures > UPLOAD_RETRIES:\r\n                    raise\r\n                print(f"[Agent 5: Publisher] Upload interrupted ({e}); resuming in {10 * failures}s...")\r\n                time.sleep(10 * failures)\r\n        return response\r\n\r\n    def scheduled_publish_time(self, index, now=None):\r\n        """Go-live time for the index-th video of this run, or None to publish immediately.\r\n\r\n        execution.py sets publish_plan to either\r\n          {"first_utc": ISO time, "interval_minutes": gap}: slots repeat every interval from first_utc, and if\r\n          preparing the videos took past some slots, the next future slot is used (Shorts); or\r\n          {"times_utc": [ISO times]}: this run\'s go-live slots, one per video. A slot that passed while the\r\n          videos were being made (GitHub often starts scheduled runs hours late) goes live soon instead, keeping\r\n          at least PASSED_SLOT_GAP between videos.\r\n        """\r\n        plan = self.profile.get("publish_plan")\r\n        if not plan:\r\n            return None\r\n        if "times_utc" in plan:\r\n            earliest = (now or datetime.now(timezone.utc)) + timedelta(minutes=10)\r\n            slots, previous = [], None\r\n            for t in sorted(datetime.fromisoformat(t) for t in plan["times_utc"]):\r\n                if t < earliest:\r\n                    t = earliest if previous is None else max(earliest, previous + PASSED_SLOT_GAP)\r\n                elif previous is not None and t < previous + PASSED_SLOT_GAP:\r\n                    t = previous + PASSED_SLOT_GAP\r\n                slots.append(t)\r\n                previous = t\r\n            return slots[index] if index < len(slots) else None\r\n        first = datetime.fromisoformat(plan["first_utc"])\r\n        interval = timedelta(minutes=plan.get("interval_minutes") or 0)\r\n        earliest = (now or datetime.now(timezone.utc)) + timedelta(minutes=10)\r\n\r\n        if first < earliest:\r\n            if not interval:\r\n                return None\r\n            missed_slots = -((first - earliest) // interval)\r\n            first += interval * missed_slots\r\n        return first + interval * index\r\n\r\n    def run(self):\r\n        manifest_path = self.paths["manifest_file"]\r\n        with open(manifest_path, "r", encoding="utf-8") as f:\r\n            trends = json.load(f)\r\n\r\n        items_to_publish = [\r\n            i for i in trends if i["status"] == "edited" and item_matches(i, self.active_key, self.profile)\r\n        ]\r\n        # A finished video whose file was deleted (e.g. an old day folder) can\'t be uploaded any more\r\n        for item in [i for i in items_to_publish if not os.path.exists(i.get("edited_video_path") or "")]:\r\n            print(f"[Agent 5: Publisher] Skipping {item[\'video_id\']}: its edited video file no longer exists.")\r\n            item["status"] = "expired"\r\n            items_to_publish.remove(item)\r\n        plan = self.profile.get("publish_plan") or {}\r\n        if "times_utc" in plan and len(items_to_publish) > len(plan["times_utc"]):\r\n            # This run has a fixed number of go-live slots; the oldest finished videos fill them first and\r\n            # the rest wait for the next run\r\n            waiting = len(items_to_publish) - len(plan["times_utc"])\r\n            items_to_publish = items_to_publish[:len(plan["times_utc"])]\r\n            print(f"[Agent 5: Publisher] {waiting} more finished video(s) will be uploaded in a later run.")\r\n        if not items_to_publish:\r\n            print("[Agent 5: Publisher] No edited videos pending upload.")\r\n            return\r\n\r\n        youtube = self.get_authenticated_service()\r\n\r\n        for index, item in enumerate(items_to_publish):\r\n            vid_id = item["video_id"]\r\n            try:\r\n                title, description = self.generate_seo_package(item)\r\n            except Exception as e:\r\n                # The video stays "edited" and is uploaded on the next run\r\n                print(f"[Agent 5: Publisher] Could not write the title for {vid_id}, will retry next run: {e}")\r\n                continue\r\n\r\n            body = {\r\n                "snippet": {\r\n                    "title": title,\r\n                    "description": description,\r\n                    "categoryId": self.profile["category_id"],\r\n                    "tags": self.search_tags(item)\r\n                },\r\n                "status": {\r\n                    "privacyStatus": self.profile.get("privacy_status", self.upload_rules["privacy_status"]),\r\n                    "selfDeclaredMadeForKids": self.profile["made_for_kids"],\r\n                    "containsSyntheticMedia": self.upload_rules["synthetic_media_disclosure"]\r\n                }\r\n            }\r\n\r\n            publish_at = self.scheduled_publish_time(index)\r\n            if publish_at:\r\n                # YouTube only accepts publishAt on private videos; it flips them public at that time\r\n                body["status"]["privacyStatus"] = "private"\r\n                body["status"]["publishAt"] = publish_at.strftime("%Y-%m-%dT%H:%M:%SZ")\r\n                print(f"[Agent 5: Publisher] Scheduled to go public at {body[\'status\'][\'publishAt\']}")\r\n\r\n            print(f"\\n[Agent 5: Publisher] Uploading \'{title}\' to {self.profile[\'channel_name\']}...")\r\n            try:\r\n                response = self.upload(youtube, item["edited_video_path"], body)\r\n                item["uploaded_youtube_id"] = response["id"]\r\n                item["uploaded_title"] = title\r\n                item["uploaded_tags"] = body["snippet"]["tags"]\r\n                item["publish_at"] = body["status"].get("publishAt")\r\n                item["uploaded_at"] = datetime.now(timezone.utc).isoformat()\r\n                item["status"] = "published"\r\n                print(f"[Agent 5: Publisher] SUCCESS! Uploaded Video ID: {response[\'id\']}")\r\n            except Exception as e:\r\n                print(f"[Agent 5: Publisher] Upload failed for {vid_id}: {e}")\r\n\r\n        with open(manifest_path, "w", encoding="utf-8") as f:\r\n            json.dump(trends, f, indent=4, ensure_ascii=False)\r\n',
    'agents/agent_6_cleanup.py': 'import os\nimport re\nimport json\nimport shutil\nfrom datetime import datetime, timedelta, timezone\n\n# Videos still waiting for a later step; if their files are gone they can never finish\nUNFINISHED = ("downloaded", "voiced", "ready_to_edit", "edited")\nFILE_FOR_STATUS = {"downloaded": "raw_video_path", "voiced": "voiceover_path",\n                   "ready_to_edit": "raw_video_path", "edited": "edited_video_path"}\n\n\ndef required_files(item):\n    """The files a video still needs for its next step."""\n    status = item.get("status")\n    if status == "ready_to_edit":\n        return [item.get("voiceover_path")] + list(item.get("footage_paths") or [])\n    if status in FILE_FOR_STATUS:\n        return [item.get(FILE_FOR_STATUS[status])]\n    return []\n\n\ndef expire_missing_files(items):\n    """Mark unfinished videos whose files are gone as "expired", so they stop counting toward the day\'s videos.\n\n    GitHub runs start on a fresh machine and only finished ("edited") videos are carried over through Google Drive,\n    so a video left half-done by an interrupted run can never be completed.\n    """\n    expired = 0\n    for item in items:\n        if item.get("status") in UNFINISHED and not all(f and os.path.exists(f) for f in required_files(item)):\n            item["status"] = "expired"\n            expired += 1\n    return expired\n\nclass CleanupAgent:\n    def __init__(self, config):\n        self.config = config\n        self.paths = config["storage_paths"]\n        self.cleanup_rules = config.get("cleanup_rules", {\n            "delete_raw_after_publish": True,\n            "delete_voiceover_after_publish": True,\n            "delete_edited_from_previous_dates": True\n        })\n\n    def _safe_remove(self, file_path):\n        if file_path and os.path.exists(file_path):\n            try:\n                os.remove(file_path)\n                print(f"[Agent 6: Cleanup] Deleted file: {file_path}")\n                return True\n            except Exception as e:\n                print(f"[Agent 6: Cleanup] Failed to delete {file_path}: {e}")\n        return False\n\n    def remove_old_date_folders(self):\n        """Local runs: delete whole YouTube_Auto/<YYYY-MM-DD> folders older than local_media.keep_days."""\n        media = self.config.get("local_media") or {}\n        root = self.config.get("media_root")\n        keep_days = int(media.get("keep_days", 2))\n        if not root or not os.path.isdir(root):\n            return 0\n        oldest_kept = (datetime.now() - timedelta(days=keep_days - 1)).strftime("%Y-%m-%d")\n        removed = 0\n        for name in sorted(os.listdir(root)):\n            if re.fullmatch(r"\\d{4}-\\d{2}-\\d{2}", name) and name < oldest_kept:\n                try:\n                    shutil.rmtree(os.path.join(root, name))\n                    print(f"[Agent 6: Cleanup] Deleted folder older than {keep_days} days: {os.path.join(root, name)}")\n                    removed += 1\n                except Exception as e:\n                    print(f"[Agent 6: Cleanup] Failed to delete {name}: {e}")\n        return removed\n\n    def run(self):\n        manifest_path = self.paths["manifest_file"]\n        if not os.path.exists(manifest_path):\n            return\n\n        local = self.config.get("storage_mode") == "local"\n        print("\\n[Agent 6: Cleanup] " + ("Removing date folders past the keep period..." if local\n                                         else "Scanning manifest for published & previous-date videos..."))\n        removed_folders = self.remove_old_date_folders() if local else 0\n\n        with open(manifest_path, "r", encoding="utf-8") as f:\n            trends = json.load(f)\n\n        today_str = datetime.now(timezone.utc).strftime("%Y-%m-%d")\n        cleaned_count = expired = 0\n\n        for item in trends:\n            status = item.get("status")\n            if local:\n                # Files are kept in the date folders until those are deleted as a whole\n                for field in ("raw_video_path", "voiceover_path", "edited_video_path"):\n                    if item.get(field) and not os.path.exists(item[field]):\n                        item[field] = None\n                if status in UNFINISHED and not item.get(FILE_FOR_STATUS[status]):\n                    item["status"] = "expired"\n                    expired += 1\n                continue\n\n            if status == "published":\n                discovered_date = item.get("discovered_at", "")[:10]\n                is_previous_date = (discovered_date != "" and discovered_date < today_str)\n\n                if self.cleanup_rules.get("delete_raw_after_publish", True):\n                    for clip in item.get("footage_paths") or []:\n                        self._safe_remove(clip)\n                    if self._safe_remove(item.get("raw_video_path")) or item.get("footage_paths"):\n                        item["raw_video_path"] = None\n                        item["footage_paths"] = []\n                        cleaned_count += 1\n\n                if self.cleanup_rules.get("delete_voiceover_after_publish", True):\n                    if self._safe_remove(item.get("voiceover_path")):\n                        item["voiceover_path"] = None\n\n                # Published videos live on YouTube; deleting the file keeps it from being synced to Drive every run\n                delete_edited = (self.cleanup_rules.get("delete_edited_after_publish", True)\n                                 or (self.cleanup_rules.get("delete_edited_from_previous_dates", True)\n                                     and is_previous_date))\n                if delete_edited and self._safe_remove(item.get("edited_video_path")):\n                    item["edited_video_path"] = None\n\n            elif status == "download_failed":\n                discovered_date = item.get("discovered_at", "")[:10]\n                if discovered_date and discovered_date < today_str:\n                    self._safe_remove(item.get("raw_video_path"))\n                    item["raw_video_path"] = None\n\n        with open(manifest_path, "w", encoding="utf-8") as f:\n            json.dump(trends, f, indent=4, ensure_ascii=False)\n\n        if local:\n            print(f"[Agent 6: Cleanup] Cleanup complete. Removed {removed_folders} old date folder(s); "\n                  f"{expired} unfinished video(s) expired with them.")\n        else:\n            print(f"[Agent 6: Cleanup] Cleanup complete. Purged {cleaned_count} published raw video sets.")\n',
    'agents/agent_7_notifier.py': 'import os\nimport html\nimport json\nimport requests\nfrom datetime import datetime\nfrom zoneinfo import ZoneInfo\n\n\ndef send_telegram(html_text):\n    """Post a message (Telegram HTML) to the channel in TELEGRAM_CHANNEL_ID; never stops the run on failure."""\n    bot_token, channel_id = os.getenv("TELEGRAM_BOT_TOKEN"), os.getenv("TELEGRAM_CHANNEL_ID")\n    if not bot_token or not channel_id:\n        print("[Agent 7: Telegram] Skipping alert: Missing TELEGRAM_BOT_TOKEN or TELEGRAM_CHANNEL_ID.")\n        return\n    payload = {"chat_id": channel_id, "text": html_text, "parse_mode": "HTML", "disable_web_page_preview": True}\n    try:\n        resp = requests.post(f"https://api.telegram.org/bot{bot_token}/sendMessage", json=payload, timeout=15)\n        if resp.status_code == 200:\n            print("[Agent 7: Telegram] Alert posted to Telegram channel!")\n        else:\n            print(f"[Agent 7: Telegram] API Error: {resp.text}")\n    except Exception as e:\n        # The exception text can contain the request URL, which includes the bot token\n        print(f"[Agent 7: Telegram] Failed to send Telegram alert: {str(e).replace(bot_token, \'***\')}")\n\n\nclass TelegramNotifierAgent:\n    def __init__(self, config):\n        self.config = config\n        self.active_key = config["active_profile"]\n        self.profile = config["profiles"][self.active_key]\n        self.paths = config["storage_paths"]\n\n    def go_live_text(self, item):\n        if not item.get("publish_at"):\n            return "live now"\n        tz = ZoneInfo(self.profile["schedule"]["timezone"])\n        when = datetime.fromisoformat(item["publish_at"].replace("Z", "+00:00")).astimezone(tz)\n        day = "today" if when.date() == datetime.now(tz).date() else f"{when:%d %b}"\n        return f"goes live {day} {when:%H:%M} {when:%Z}"\n\n    def run(self, uploaded, planned=None):\n        """One message for this channel: the videos this run uploaded and when each one goes live."""\n        uploaded = sorted(uploaded, key=lambda i: i.get("publish_at") or "")\n        planned = planned if planned is not None else len(uploaded)\n        icon = "✅" if uploaded and len(uploaded) >= planned else "⚠️"\n        lines = [f"{icon} <b>{html.escape(self.profile[\'channel_name\'])}</b>: "\n                 f"{len(uploaded)} of {planned} video(s) uploaded and scheduled"]\n        for idx, item in enumerate(uploaded, 1):\n            long = item.get("format") == "long"\n            yt_id = item.get("uploaded_youtube_id")\n            url = f"https://youtube.com/{\'watch?v=\' if long else \'shorts/\'}{yt_id}"\n            title = item.get("uploaded_title") or item.get("original_title") or yt_id\n            tags = " ".join(item.get("upload_hashtags") or [])\n            lines.append(f"\\n{idx}. {\'🎬 Long video\' if long else \'📱 Short\'}, {self.go_live_text(item)}\\n"\n                         f"<b>{html.escape(title)}</b>\\n🔗 {url}" + (f"\\n🏷 {html.escape(tags)}" if tags else ""))\n        if len(uploaded) < planned:\n            lines.append(f"\\n{planned - len(uploaded)} video(s) were not uploaded. Check the GitHub run log, "\n                         "step 8, for the [Agent ...] lines explaining why.")\n        send_telegram("\\n".join(lines))\n\n        if not uploaded:\n            return\n        manifest_path = self.paths["manifest_file"]\n        with open(manifest_path, "r", encoding="utf-8") as f:\n            trends = json.load(f)\n        ids = {item["video_id"] for item in uploaded}\n        for item in trends:\n            if item.get("video_id") in ids and item.get("profile") == self.active_key:\n                item["notified_telegram"] = True\n        with open(manifest_path, "w", encoding="utf-8") as f:\n            json.dump(trends, f, indent=4, ensure_ascii=False)\n',
    'execution/execution.py': '"""The single entry point for the YouTube automation pipeline. Read execution/execution.md first.\r\n\r\nAnswers to every question live in execution/questions.yaml; this file reads them each time it runs.\r\n\r\n    python execution/execution.py                        # run every channel with run: true in questions.yaml\r\n    python execution/execution.py --channel kids_edu     # run one channel (or --channel all)\r\n    python execution/execution.py --check                # validate both pages, show the plan, update GitHub schedule\r\n    python execution/execution.py --list                 # show channels and their posting plans\r\n    python execution/execution.py --authorize kids_edu   # sign in to YouTube for a channel (once)\r\n    python execution/execution.py --ask                  # answer the questions interactively for a one-off run\r\n\r\nOne-off overrides for a run: --genre "..." --videos 6 --frequency "30 mins" --first-post "09:00" --dry-run\r\nGitHub uses: --scheduled --cron "<cron>"  and  --due --cron "<cron>"\r\n"""\r\nimport argparse\r\nimport copy\r\nimport html\r\nimport os\r\nimport re\r\nimport sys\r\nfrom datetime import datetime, timedelta, timezone\r\nfrom zoneinfo import ZoneInfo\r\n\r\nEXECUTION_DIR = os.path.dirname(os.path.abspath(__file__))\r\nPROJECT_DIR = os.path.dirname(EXECUTION_DIR)\r\nREPO_DIR = os.path.dirname(PROJECT_DIR)\r\nWORKFLOW_FILE = os.path.join(REPO_DIR, ".github", "workflows", "daily_youtube_agents.yml")\r\n\r\nsys.path.insert(0, PROJECT_DIR)\r\n# The agents use paths relative to the project folder, wherever this file is started from\r\nos.chdir(PROJECT_DIR)\r\n\r\nfrom brain import (  # noqa: E402\r\n    DEFAULT_VOICES, FREQUENCIES, LANGUAGES, MAX_VIDEOS_PER_DAY, SPEEDS, YOUTUBE_SCOPES,\r\n    channel_matches, cron_lines, due_profiles, fetch_time_for_cron, load_brain, parse_time,\r\n)\r\n\r\nSCHEDULE_BEGIN = "# BEGIN CHANNEL SCHEDULE"\r\nSCHEDULE_END = "# END CHANNEL SCHEDULE"\r\nRUNNING_ON_GITHUB = os.getenv("GITHUB_ACTIONS") == "true"\r\nDAILY_UPLOAD_LIMIT = 100\r\nDAILY_SEARCH_LIMIT = 100\r\n# Rough GitHub Actions build times, used only for the --check estimate (measured on October 2026 runs)\r\nGITHUB_SETUP_MINUTES = 2\r\nMINUTES_PER_SHORT = 3\r\nMINUTES_PER_LONG = 12\r\nGITHUB_FREE_MINUTES = 2000\r\n\r\nVOICE_CHOICES = {\r\n    "English": ["en-US-AndrewNeural", "en-US-ChristopherNeural", "en-US-GuyNeural", "en-US-AriaNeural",\r\n                "en-US-EmmaNeural", "en-US-AnaNeural", "en-US-JennyNeural", "en-IN-PrabhatNeural", "en-IN-NeerjaNeural"],\r\n    "Hindi": ["hi-IN-MadhurNeural", "hi-IN-SwaraNeural"],\r\n    "Telugu": ["te-IN-MohanNeural", "te-IN-ShrutiNeural"],\r\n}\r\n\r\n\r\n# ---------- prompt helpers (used by --ask and sign-in) ----------\r\n\r\ndef ask(question, default=None, validate=None):\r\n    while True:\r\n        suffix = f" [{default}]" if default not in (None, "") else ""\r\n        answer = input(f"{question}{suffix}: ").strip()\r\n        if not answer and default is not None:\r\n            answer = str(default)\r\n        if not answer:\r\n            print("   Please enter a value.")\r\n            continue\r\n        if validate:\r\n            error = validate(answer)\r\n            if error:\r\n                print(f"   {error}")\r\n                continue\r\n        return answer\r\n\r\n\r\ndef ask_yes_no(question, default=True):\r\n    hint = "Y/n" if default else "y/N"\r\n    while True:\r\n        answer = input(f"{question} ({hint}): ").strip().lower()\r\n        if not answer:\r\n            return default\r\n        if answer in ("y", "yes"):\r\n            return True\r\n        if answer in ("n", "no"):\r\n            return False\r\n        print("   Please answer y or n.")\r\n\r\n\r\ndef ask_choice(question, options, default_value=None):\r\n    print(question)\r\n    default_index = 1\r\n    for index, (value, label) in enumerate(options, 1):\r\n        marker = ""\r\n        if value == default_value:\r\n            default_index, marker = index, "  <- current"\r\n        print(f"   {index:>2}. {label}{marker}")\r\n\r\n    def validate(answer):\r\n        if not answer.isdigit() or not 1 <= int(answer) <= len(options):\r\n            return f"Enter a number from 1 to {len(options)}."\r\n        return None\r\n\r\n    return options[int(ask("   Choose a number", default_index, validate)) - 1][0]\r\n\r\n\r\ndef ask_int(question, default, low, high):\r\n    def validate(answer):\r\n        if not answer.isdigit() or not low <= int(answer) <= high:\r\n            return f"Enter a whole number from {low} to {high}."\r\n        return None\r\n    return int(ask(question, default, validate))\r\n\r\n\r\ndef validate_hhmm(answer):\r\n    if not re.fullmatch(r"\\d{1,2}:\\d{2}", answer):\r\n        return "Use 24-hour HH:MM, e.g. 07:00."\r\n    try:\r\n        parse_time(answer)\r\n    except ValueError:\r\n        return "That is not a real time of day."\r\n    return None\r\n\r\n\r\ndef split_list(text):\r\n    return [part.strip() for part in text.split(",") if part.strip()]\r\n\r\n\r\ndef heading(title):\r\n    print("\\n" + "=" * 60)\r\n    print(f" {title}")\r\n    print("=" * 60)\r\n\r\n\r\n# ---------- posting plan ----------\r\n\r\ndef apply_overrides(profile, overrides):\r\n    """Apply one-off command-line or --ask answers on top of questions.yaml (the file itself is not changed)."""\r\n    if overrides.get("genre"):\r\n        profile["niche"] = overrides["genre"]\r\n        profile["search_queries"] = overrides.get("queries") or [f"{overrides[\'genre\']} #shorts"]\r\n    elif overrides.get("queries"):\r\n        profile["search_queries"] = overrides["queries"]\r\n    for key, field in (("videos", "max_videos_per_run"), ("language", "language"), ("voice", "voice"),\r\n                       ("voice_rate", "voice_rate"), ("privacy", "privacy_status")):\r\n        if overrides.get(key):\r\n            profile[field] = overrides[key]\r\n    if overrides.get("frequency"):\r\n        profile["posting"]["frequency_minutes"] = FREQUENCIES[overrides["frequency"]]\r\n    if overrides.get("first_post") or overrides.get("frequency"):\r\n        # A one-off first time or gap replaces the fixed short_post_times\r\n        profile["posting"]["post_times"] = []\r\n    if overrides.get("first_post"):\r\n        profile["posting"]["first_post_time"] = overrides["first_post"]\r\n    if overrides.get("videos") and profile["long"]["count"]:\r\n        # --videos N means at most N of each format\r\n        profile["long"]["count"] = min(profile["long"]["count"], overrides["videos"])\r\n    if overrides.get("post_now"):\r\n        profile["posting"]["first_post_time"] = None\r\n        profile["posting"]["post_times"] = []\r\n        profile["long"]["post_times"] = []\r\n\r\n\r\ndef next_occurrences(times, tz, now, count):\r\n    """The next `count` go-live times (UTC) from a list of daily "HH:MM", at least 30 minutes from now."""\r\n    earliest = now.astimezone(tz) + timedelta(minutes=30)\r\n    upcoming = []\r\n    for days in range(0, count // max(len(times), 1) + 2):\r\n        for t in times:\r\n            local = datetime.combine(earliest.date() + timedelta(days=days), parse_time(t), tzinfo=tz)\r\n            if local >= earliest:\r\n                upcoming.append(local)\r\n    return [t.astimezone(timezone.utc) for t in sorted(upcoming)[:count]]\r\n\r\n\r\ndef publish_plan(profile, now=None):\r\n    """Turn first_post_time and post_frequency into the plan Agent 5 uses to schedule go-live times."""\r\n    tz = ZoneInfo(profile["schedule"]["timezone"])\r\n    if profile["posting"].get("post_times"):\r\n        upcoming = next_occurrences(profile["posting"]["post_times"], tz, now or datetime.now(tz),\r\n                                    profile["max_videos_per_run"])\r\n        return {"times_utc": [t.isoformat() for t in upcoming]}\r\n    first_post = profile["posting"]["first_post_time"]\r\n    if not first_post:\r\n        return None\r\n    today = (now or datetime.now(tz)).astimezone(tz).date()\r\n    first_local = datetime.combine(today, parse_time(first_post), tzinfo=tz)\r\n\r\n    fetch_times = profile["schedule"]["post_times"]\r\n    if fetch_times and parse_time(first_post) <= parse_time(fetch_times[0]):\r\n        # e.g. fetch at 23:00 and first post at 07:00 means 07:00 the next morning\r\n        first_local += timedelta(days=1)\r\n\r\n    return {\r\n        "first_utc": first_local.astimezone(timezone.utc).isoformat(),\r\n        "interval_minutes": profile["posting"]["frequency_minutes"],\r\n    }\r\n\r\n\r\ndef long_publish_plan(profile, now=None):\r\n    """One fixed go-live time per long video (long_post_times); times already past move to the next day."""\r\n    long = profile["long"]\r\n    if not long["count"] or not long["post_times"]:\r\n        return None\r\n    tz = ZoneInfo(profile["schedule"]["timezone"])\r\n    now_local = (now or datetime.now(tz)).astimezone(tz)\r\n    times = []\r\n    for post_time in long["post_times"][:long["count"]]:\r\n        local = datetime.combine(now_local.date(), parse_time(post_time), tzinfo=tz)\r\n        if local <= now_local:\r\n            local += timedelta(days=1)\r\n        times.append(local.astimezone(timezone.utc))\r\n    return {"times_utc": [t.isoformat() for t in sorted(times)]}\r\n\r\n\r\ndef day_slots(profile, day):\r\n    """Go-live times (local) of one posting day that starts on `day`: (Shorts, long videos).\r\n\r\n    A time at or before the day\'s first fetch time belongs to the next morning (e.g. fetch 23:00, post 07:00).\r\n    """\r\n    tz = ZoneInfo(profile["schedule"]["timezone"])\r\n    fetches = sorted(parse_time(t) for t in profile["schedule"]["post_times"])\r\n\r\n    def at(value):\r\n        local = datetime.combine(day, parse_time(value), tzinfo=tz)\r\n        return local + timedelta(days=1) if fetches and parse_time(value) <= fetches[0] else local\r\n\r\n    shorts = []\r\n    if profile["posting"].get("post_times"):\r\n        shorts = [at(t) for t in profile["posting"]["post_times"]]\r\n    elif profile["posting"]["first_post_time"]:\r\n        first, gap = at(profile["posting"]["first_post_time"]), timedelta(minutes=profile["posting"]["frequency_minutes"])\r\n        shorts = [first + gap * k for k in range(profile["max_videos_per_run"])]\r\n    longs = [at(t) for t in profile["long"]["post_times"][:profile["long"]["count"]]]\r\n    return shorts, longs\r\n\r\n\r\ndef run_window(profile, now=None, fetch=None):\r\n    """(start, end) local times of this run: from its fetch time up to the channel\'s next fetch time.\r\n\r\n    fetch is the fetch time behind a scheduled run, which GitHub may start hours early or late\r\n    (github_schedule_lead_minutes), so its nearest occurrence is used; manual runs use the window that contains\r\n    the current time.\r\n    """\r\n    tz = ZoneInfo(profile["schedule"]["timezone"])\r\n    now_local = (now or datetime.now(tz)).astimezone(tz)\r\n    times = sorted(parse_time(t) for t in profile["schedule"]["post_times"])\r\n    if not times:\r\n        return None\r\n\r\n    def latest(t):\r\n        local = datetime.combine(now_local.date(), t, tzinfo=tz)\r\n        return local - timedelta(days=1) if local > now_local else local\r\n\r\n    if fetch in times:\r\n        start = min((datetime.combine(now_local.date() + timedelta(days=d), fetch, tzinfo=tz) for d in (-1, 0, 1)),\r\n                    key=lambda local: abs(local - now_local))\r\n    else:\r\n        start = max(latest(t) for t in times)\r\n\r\n    def following(t):\r\n        local = datetime.combine(start.date(), t, tzinfo=tz)\r\n        return local + timedelta(days=1) if local <= start else local\r\n\r\n    return start, min(following(t) for t in times)\r\n\r\n\r\ndef run_slots(profile, now=None, fetch=None):\r\n    """This run\'s go-live times in UTC, (Shorts, long videos): the day\'s slots that fall inside its window."""\r\n    window = run_window(profile, now, fetch)\r\n    if not window:\r\n        return None\r\n    start, end = window\r\n    shorts, longs = set(), set()\r\n    for offset in (-1, 0, 1):\r\n        day_shorts, day_longs = day_slots(profile, start.date() + timedelta(days=offset))\r\n        shorts.update(t for t in day_shorts if start <= t < end)\r\n        longs.update(t for t in day_longs if start <= t < end)\r\n    return ([t.astimezone(timezone.utc) for t in sorted(shorts)],\r\n            [t.astimezone(timezone.utc) for t in sorted(longs)])\r\n\r\n\r\ndef plan_run(profile, fetch=None, shared=True, now=None):\r\n    """Set this run\'s video counts and go-live plans on the profile.\r\n\r\n    shared: the day\'s videos are shared between the channel\'s runs (one per fetch time), each run making the\r\n    videos whose go-live times fall before the next run. Off for one-off runs that set their own counts or times.\r\n    """\r\n    profile["publish_plan"] = publish_plan(profile, now)\r\n    profile["long_publish_plan"] = long_publish_plan(profile, now)\r\n    slots = run_slots(profile, now, fetch) if shared else None\r\n    if not slots:\r\n        return\r\n    shorts, longs = slots\r\n    if profile["posting"].get("post_times") or profile["posting"]["first_post_time"]:\r\n        profile["max_videos_per_run"] = len(shorts)\r\n        profile["publish_plan"] = {"times_utc": [t.isoformat() for t in shorts]}\r\n    if profile["long"]["post_times"]:\r\n        profile["long"]["count"] = len(longs)\r\n        profile["long_publish_plan"] = {"times_utc": [t.isoformat() for t in longs]} if longs else None\r\n\r\n\r\ndef plan_times(plan, tz):\r\n    if not plan or "times_utc" not in plan:\r\n        return []\r\n    return [datetime.fromisoformat(t).astimezone(ZoneInfo(tz)).strftime("%H:%M") for t in plan["times_utc"]]\r\n\r\n\r\ndef describe_run(profile, formats=("long", "short")):\r\n    """e.g. \'1 long (12:00) + 2 Shorts (08:00, 11:00)\' for the plan set by plan_run."""\r\n    tz = profile["schedule"]["timezone"]\r\n    parts = []\r\n    if "long" in formats and profile["long"]["count"]:\r\n        times = plan_times(profile.get("long_publish_plan"), tz)\r\n        parts.append(f"{profile[\'long\'][\'count\']} long" + (f" ({\', \'.join(times)})" if times else ""))\r\n    if "short" in formats and profile["max_videos_per_run"]:\r\n        times = plan_times(profile.get("publish_plan"), tz)\r\n        count = profile["max_videos_per_run"]\r\n        parts.append(f"{count} Short{\'s\' if count > 1 else \'\'}"\r\n                     + (f" ({\', \'.join(times)})" if times else " (live on upload)"))\r\n    return " + ".join(parts) or "no videos"\r\n\r\n\r\ndef describe_runs(profile):\r\n    """Each daily run and the videos it makes, e.g. \'06:00 -> 1 long (12:00) + 2 Shorts (08:00, 11:00)\'."""\r\n    tz = ZoneInfo(profile["schedule"]["timezone"])\r\n    lines = []\r\n    for fetch in sorted(parse_time(t) for t in profile["schedule"]["post_times"]):\r\n        preview = copy.deepcopy(profile)\r\n        at_fetch = datetime.combine(datetime.now(tz).date(), fetch, tzinfo=tz)\r\n        plan_run(preview, fetch=fetch, now=at_fetch)\r\n        lines.append(f"{fetch:%H:%M} -> {describe_run(preview)}")\r\n    return lines\r\n\r\n\r\ndef run_label(fetch):\r\n    if fetch is None:\r\n        return "Manual run"\r\n    return "Morning run" if fetch.hour < 12 else "Afternoon run" if fetch.hour < 17 else "Evening run"\r\n\r\n\r\ndef describe_long(profile):\r\n    long = profile["long"]\r\n    if not long["count"]:\r\n        return "no long videos"\r\n    minutes = str(long["minutes"]).replace("-", " to ")\r\n    return (f"{long[\'count\']} long landscape video(s) of {minutes} min, live at "\r\n            f"{\', \'.join(f\'{parse_time(t):%H:%M}\' for t in long[\'post_times\'][:long[\'count\']])}")\r\n\r\n\r\ndef describe_plan(profile):\r\n    posting = profile["posting"]\r\n    count = profile["max_videos_per_run"]\r\n    fetch = ", ".join(f"{parse_time(t):%H:%M}" for t in profile["schedule"]["post_times"]) or "manual runs only"\r\n    if posting.get("post_times"):\r\n        return f"fetch {fetch} | {count} video(s) live at " + ", ".join(\r\n            f"{parse_time(t):%H:%M}" for t in posting["post_times"])\r\n    if not posting["first_post_time"]:\r\n        return f"fetch {fetch} | {count} video(s), live immediately after upload"\r\n    freq = next((name for name, minutes in FREQUENCIES.items() if minutes == posting["frequency_minutes"]),\r\n                f"{posting[\'frequency_minutes\']} mins")\r\n    first = datetime.combine(datetime(2000, 1, 1), parse_time(posting["first_post_time"]))\r\n    last = first + timedelta(minutes=posting["frequency_minutes"] * (count - 1))\r\n    return (f"fetch {fetch} | {count} video(s): first live {first:%H:%M}, every {freq}, "\r\n            f"last {last:%H:%M}{\' (next day)\' if last.date() > first.date() else \'\'}")\r\n\r\n\r\n# ---------- running ----------\r\n\r\ndef token_path(config, key):\r\n    return os.path.normpath(os.path.join(PROJECT_DIR, config["storage_paths"]["tokens_dir"], f"token_{key}.json"))\r\n\r\n\r\ndef preflight(config, keys, dry_runs):\r\n    """Return the channels that are ready to run, explaining why any are skipped."""\r\n    problems = []\r\n    if not os.path.exists(os.path.join(PROJECT_DIR, ".env")) and not RUNNING_ON_GITHUB:\r\n        problems.append("No .env file. Copy .env.example to .env and fill in your API keys.")\r\n    for name in ("YOUTUBE_API_KEY", "GEMINI_API_KEY"):\r\n        if not os.getenv(name):\r\n            problems.append(f"{name} is not set (add it to .env, or as a GitHub secret).")\r\n    footage = config.get("footage") or {}\r\n    if footage.get("source", "stock") == "stock":\r\n        from agents.stock_footage import choose_provider\r\n        if not choose_provider(footage.get("provider", "auto"))[0]:\r\n            problems.append("No stock footage key is set. Add PIXABAY_API_KEY (free at https://pixabay.com/api/docs/) "\r\n                            "to .env, or as a GitHub secret.")\r\n    if problems:\r\n        print("\\nCannot start:\\n  - " + "\\n  - ".join(problems))\r\n        return []\r\n\r\n    ready = []\r\n    for key in keys:\r\n        if dry_runs[key] or os.path.exists(token_path(config, key)):\r\n            ready.append(key)\r\n        elif RUNNING_ON_GITHUB or not sys.stdin.isatty():\r\n            print(f"\\n[Skip] {key}: no YouTube login file. Run \'python execution/execution.py --authorize {key}\' "\r\n                  "on your laptop and upload the token file to Google Drive: YouTube_Automation/00_tokens/")\r\n        else:\r\n            print(f"\\n{key} has no YouTube login yet ({token_path(config, key)}).")\r\n            if ask_yes_no("Sign in to YouTube for this channel now?", True) and authorize(config, key):\r\n                ready.append(key)\r\n    return ready\r\n\r\n\r\ndef notify_start(config, keys, fetches, formats):\r\n    """Telegram message at the start of a run: which videos each channel is preparing and when they go live."""\r\n    from agents.agent_7_notifier import send_telegram\r\n    first = config["profiles"][keys[0]]\r\n    tz = ZoneInfo(first["schedule"]["timezone"])\r\n    now = datetime.now(tz)\r\n    fetch = fetches.get(keys[0])\r\n    started = f"started {now:%H:%M} {now:%Z}"\r\n    if fetch:\r\n        planned_at = min((datetime.combine(now.date() + timedelta(days=d), fetch, tzinfo=tz) for d in (-1, 0, 1)),\r\n                         key=lambda local: abs(local - now))\r\n        late = int((now - planned_at).total_seconds() // 60)\r\n        off = f"{abs(late) // 60}h {abs(late) % 60:02d}m {\'late\' if late > 0 else \'early\'}"\r\n        started = f"planned {fetch:%H:%M}, {started}" + (f" ({off})" if abs(late) >= 15 else "")\r\n    lines = [f"🎬 <b>{run_label(fetch)} started</b> ({started})", "Video preparation in progress:"]\r\n    for key in keys:\r\n        p = config["profiles"][key]\r\n        lines.append(f"• <b>{html.escape(p[\'channel_name\'])}</b>: {describe_run(p, formats)}")\r\n    lines.append("A message per channel follows once its videos are uploaded and scheduled.")\r\n    send_telegram("\\n".join(lines))\r\n\r\n\r\ndef run_channels(config, instructions, keys, overrides=None, force_dry_run=False, formats=("long", "short"),\r\n                 cron=None):\r\n    from dotenv import load_dotenv\r\n    load_dotenv(os.path.join(PROJECT_DIR, ".env"))\r\n\r\n    config = copy.deepcopy(config)\r\n    for key in keys:\r\n        apply_overrides(config["profiles"][key], overrides or {})\r\n    dry_runs = {key: force_dry_run or config["profiles"][key]["test_run"] for key in keys}\r\n\r\n    ready = preflight(config, keys, dry_runs)\r\n    if not ready:\r\n        return 1\r\n\r\n    from orchestrator import OrchestratorAgent\r\n    orchestrator = OrchestratorAgent(config, instructions)\r\n    failed, results = [], {}\r\n    # One-off counts or times replace the shared daily plan for this run\r\n    shared = not any((overrides or {}).get(k) for k in ("videos", "first_post", "frequency", "post_now"))\r\n    fetches, planned = {}, {}\r\n    for key in ready:\r\n        profile = config["profiles"][key]\r\n        fetches[key] = fetch_time_for_cron(profile, cron) if cron else None\r\n        plan_run(profile, fetch=fetches[key], shared=shared)\r\n        planned[key] = (profile["max_videos_per_run"] if "short" in formats else 0) + \\\r\n                       (profile["long"]["count"] if "long" in formats else 0)\r\n    if not all(dry_runs[key] for key in ready):\r\n        notify_start(config, ready, fetches, formats)\r\n\r\n    for key in ready:\r\n        profile = config["profiles"][key]\r\n        print(f"\\n>>> {key}: {describe_run(profile, formats)}")\r\n        if not planned[key]:\r\n            print(f"[Orchestrator] {key}: no go-live times fall in this run; nothing to make.")\r\n            continue\r\n        try:\r\n            results[key] = orchestrator.execute_pipeline(key, dry_run=dry_runs[key], formats=formats,\r\n                                                         planned=planned[key])\r\n            if not dry_runs[key] and results[key] == 0:\r\n                failed.append(key)\r\n        except Exception as e:\r\n            print(f"\\n[Error] {key} failed: {e}")\r\n            failed.append(key)\r\n            if not dry_runs[key]:\r\n                from agents.agent_7_notifier import send_telegram\r\n                send_telegram(f"❌ <b>{html.escape(profile[\'channel_name\'])}</b>: the run stopped with an error "\r\n                              f"before uploading.\\n<code>{html.escape(str(e)[:300])}</code>")\r\n\r\n    heading("RESULT")\r\n    for key in keys:\r\n        if key not in ready:\r\n            print(f" {key}: skipped (no YouTube login)")\r\n        elif dry_runs[key]:\r\n            print(f" {key}: test run, videos made but not uploaded")\r\n        else:\r\n            print(f" {key}: {results.get(key, 0)} of {planned[key]} video(s) uploaded")\r\n            if RUNNING_ON_GITHUB and 0 < results.get(key, 0) < planned[key]:\r\n                # Some but not all: the run stays green, with a yellow warning on its summary page\r\n                print(f"::warning title={key}: {results[key]} of {planned[key]} uploaded::"\r\n                      f"{planned[key] - results[key]} video(s) were not made or uploaded. Search step 8 for "\r\n                      "\'[Agent\' lines to see why; they are retried in later runs.")\r\n    if failed or len(ready) < len(keys):\r\n        print("\\nSome channels uploaded nothing. Scroll up for the [Agent ...] lines explaining why.")\r\n        return 1\r\n    return 0\r\n\r\n\r\n# ---------- schedule, check, login and list ----------\r\n\r\ndef read_workflow_schedule():\r\n    if not os.path.exists(WORKFLOW_FILE):\r\n        return None, None\r\n    with open(WORKFLOW_FILE, "r", encoding="utf-8") as f:\r\n        lines = f.read().split("\\n")\r\n    begin = next((i for i, line in enumerate(lines) if SCHEDULE_BEGIN in line), None)\r\n    end = next((i for i, line in enumerate(lines) if SCHEDULE_END in line), None)\r\n    if begin is None or end is None or end < begin:\r\n        return lines, None\r\n    return lines, (begin, end)\r\n\r\n\r\ndef schedule_in_sync(config):\r\n    lines, markers = read_workflow_schedule()\r\n    if not markers:\r\n        return True\r\n    current = [re.sub(r".*cron:\\s*\'([^\']*)\'.*", r"\\1", line) for line in lines[markers[0] + 1:markers[1]]]\r\n    return current == cron_lines(config)\r\n\r\n\r\ndef sync_schedule(config):\r\n    crons = cron_lines(config)\r\n    lines, markers = read_workflow_schedule()\r\n    if lines is None or markers is None:\r\n        print("Could not find the schedule section in the GitHub workflow. Add these lines under \'schedule:\':")\r\n        print("\\n".join(f"    - cron: \'{c}\'" for c in crons))\r\n        return False\r\n    if not crons:\r\n        print("No channel has a fetch_time, so the GitHub schedule was left unchanged.")\r\n        return False\r\n\r\n    begin, end = markers\r\n    indent = lines[begin][:len(lines[begin]) - len(lines[begin].lstrip())]\r\n    lines[begin + 1:end] = [f"{indent}- cron: \'{c}\'" for c in crons]\r\n    with open(WORKFLOW_FILE, "w", encoding="utf-8", newline="") as f:\r\n        f.write("\\n".join(lines))\r\n\r\n    print("GitHub schedule updated (times shown in UTC):")\r\n    for c in crons:\r\n        print(f"   {c}")\r\n    print("Push to GitHub so the new schedule takes effect.")\r\n    return True\r\n\r\n\r\ndef list_channels(config):\r\n    heading("CHANNELS AND POSTING PLANS")\r\n    for key, p in config["profiles"].items():\r\n        if not p["has_answers"]:\r\n            state = "NOT ANSWERED in questions.yaml (will not run)"\r\n        else:\r\n            state = "will run" if p["enabled"] else "run: false (paused)"\r\n        login = "yes" if os.path.exists(token_path(config, key)) else "NO"\r\n        days = p["schedule"]["days"] if isinstance(p["schedule"]["days"], str) else ",".join(p["schedule"]["days"])\r\n        print(f" {key}  -  {p[\'channel_name\']}")\r\n        print(f"    {state} | YouTube login: {login} | {\'TEST RUN\' if p[\'test_run\'] else \'uploads\'}")\r\n        if p["has_answers"]:\r\n            print(f"    Shorts: {describe_plan(p)} ({days}, {p[\'schedule\'][\'timezone\']})")\r\n            print(f"    Long:   {describe_long(p)}")\r\n            if len(p["schedule"]["post_times"]) > 1:\r\n                for line in describe_runs(p):\r\n                    print(f"    Run {line}")\r\n            print(f"    genre: {p[\'niche\']} | {p[\'language\']} | voice: {p[\'voice\']} {p[\'voice_rate\']}")\r\n\r\n\r\ndef usage_report(config):\r\n    """Estimate the YouTube API calls the answers use per day, against YouTube\'s daily limits."""\r\n    # Channels due at the same time share one GitHub run, so setup time is counted once per scheduled time.\r\n    # videos_per_day and long_videos_per_day are day totals, shared between a channel\'s runs\r\n    uploads = searches = 0\r\n    github_minutes = len(cron_lines(config)) * GITHUB_SETUP_MINUTES\r\n    for p in config["profiles"].values():\r\n        if not p["enabled"]:\r\n            continue\r\n        runs_per_day = len(p["schedule"]["post_times"]) or 1\r\n        long_count = p["long"]["count"]\r\n        github_minutes += p["max_videos_per_run"] * MINUTES_PER_SHORT + long_count * MINUTES_PER_LONG\r\n        if p["test_run"]:\r\n            continue\r\n        uploads += p["max_videos_per_run"] + long_count\r\n        searches += len(p["search_queries"]) * runs_per_day * (2 if long_count else 1)\r\n    print(f"\\nDaily YouTube usage (all channels): {uploads} of {DAILY_UPLOAD_LIMIT} uploads, "\r\n          f"up to {searches} of {DAILY_SEARCH_LIMIT} searches.")\r\n    if uploads > DAILY_UPLOAD_LIMIT or searches > DAILY_SEARCH_LIMIT:\r\n        print("WARNING: over YouTube\'s daily limit. Lower videos_per_day or search_phrases, "\r\n              "or request more quota in Google Cloud Console.")\r\n    monthly = github_minutes * 30\r\n    if config.get("github_repo_public"):\r\n        print(f"Estimated GitHub Actions time: about {github_minutes} min a day (public repository: unlimited).")\r\n        return\r\n    print(f"Estimated GitHub Actions time: about {github_minutes} min a day, {monthly} min a month "\r\n          f"(private repos get {GITHUB_FREE_MINUTES} free minutes a month; public repos are unlimited).")\r\n    if monthly > GITHUB_FREE_MINUTES:\r\n        print("WARNING: likely over GitHub\'s free minutes for a private repo. Make the repo public, lower the "\r\n              "video counts, or GitHub will stop the runs (or bill you, if a payment method is set) for the rest "\r\n              "of the month.")\r\n\r\n\r\ndef plan_warnings(config):\r\n    warnings = []\r\n    for key, p in config["profiles"].items():\r\n        if not p["enabled"]:\r\n            continue\r\n        fetch, first = p["schedule"]["post_times"], p["posting"]["first_post_time"]\r\n        if fetch and first:\r\n            gap = (datetime.combine(datetime(2000, 1, 1), parse_time(first))\r\n                   - datetime.combine(datetime(2000, 1, 1), parse_time(fetch[0]))).total_seconds() / 60 % 1440\r\n            if gap < 30:\r\n                warnings.append(f"{key}: first_post_time is only {int(gap)} min after fetch_time; allow 30+ min "\r\n                                "to prepare videos (later slots are used automatically if it runs late).")\r\n        span = p["posting"]["frequency_minutes"] * (p["max_videos_per_run"] - 1)\r\n        if first and not p["posting"].get("post_times") and span >= 1440:\r\n            warnings.append(f"{key}: {p[\'max_videos_per_run\']} videos every {p[\'posting\'][\'frequency_minutes\']} min "\r\n                            "runs past 24 hours and overlaps the next day\'s videos.")\r\n        # Each run needs time to prepare its videos before the first one goes live\r\n        tz = ZoneInfo(p["schedule"]["timezone"])\r\n        for run_time in sorted(parse_time(t) for t in fetch):\r\n            preview = copy.deepcopy(p)\r\n            at_fetch = datetime.combine(datetime.now(tz).date(), run_time, tzinfo=tz)\r\n            plan_run(preview, fetch=run_time, now=at_fetch)\r\n            times = [datetime.fromisoformat(t) for plan in (preview.get("publish_plan"), preview.get("long_publish_plan"))\r\n                     for t in (plan or {}).get("times_utc", [])]\r\n            if times and (min(times) - at_fetch).total_seconds() < 45 * 60:\r\n                warnings.append(f"{key}: the {run_time:%H:%M} run\'s first video goes live under 45 min after the run "\r\n                                "starts; it will go live a little later than planned.")\r\n    return warnings\r\n\r\n\r\ndef check(config):\r\n    list_channels(config)\r\n    print("\\nBoth pages are valid.")\r\n    for warning in plan_warnings(config):\r\n        print(f"Note: {warning}")\r\n    usage_report(config)\r\n    if schedule_in_sync(config):\r\n        print("GitHub schedule already matches questions.yaml.")\r\n    else:\r\n        sync_schedule(config)\r\n\r\n\r\ndef authorize(config, key):\r\n    client_secret = os.path.join(PROJECT_DIR, "client_secret.json")\r\n    if key not in config["profiles"]:\r\n        print(f"\'{key}\' is not on the channel page.")\r\n        return False\r\n    if not os.path.exists(client_secret):\r\n        print(f"client_secret.json not found at {client_secret}. See execution.md, \'One-Time Setup\'.")\r\n        return False\r\n    from google_auth_oauthlib.flow import InstalledAppFlow\r\n    from googleapiclient.discovery import build\r\n\r\n    profile = config["profiles"][key]\r\n    target = token_path(config, key)\r\n    os.makedirs(os.path.dirname(target), exist_ok=True)\r\n    print(f"\\nA browser window will open. Sign in with the Google account that owns \'{profile[\'channel_name\']}\'")\r\n    print(f"and choose that channel ({profile[\'channel_url\']}).")\r\n    creds = InstalledAppFlow.from_client_secrets_file(client_secret, YOUTUBE_SCOPES).run_local_server(port=0)\r\n\r\n    items = build("youtube", "v3", credentials=creds).channels().list(part="snippet", mine=True).execute().get("items", [])\r\n    if not items:\r\n        print("That Google account has no YouTube channel. Nothing was saved; try again.")\r\n        return False\r\n    channel_id, snippet = items[0]["id"], items[0]["snippet"]\r\n    if not channel_matches(profile["channel_url"], channel_id, snippet.get("customUrl")):\r\n        print(f"You signed in to \'{snippet[\'title\']}\' ({snippet.get(\'customUrl\') or channel_id}), "\r\n              f"but \'{key}\' is {profile[\'channel_url\']}. Nothing was saved; try again and pick the right channel.")\r\n        return False\r\n    print(f"Confirmed channel: {snippet[\'title\']}")\r\n\r\n    with open(target, "w", encoding="utf-8") as f:\r\n        f.write(creds.to_json())\r\n    print(f"Saved YouTube login to: {target}")\r\n    print("For GitHub runs, upload this file to Google Drive: YouTube_Automation/00_tokens/")\r\n    return True\r\n\r\n\r\n# ---------- --ask: answer the questions interactively for one run ----------\r\n\r\ndef ask_mode(config, instructions):\r\n    answered = {k: p for k, p in config["profiles"].items() if p["has_answers"]}\r\n    if not answered:\r\n        print("No channel is answered in questions.yaml yet.")\r\n        return 1\r\n\r\n    heading("ONE-OFF RUN  (questions.yaml is not changed)")\r\n    print("Each answer starts at the value in questions.yaml. Press Enter to keep it. Ctrl+C cancels.\\n")\r\n    key = ask_choice("Q1. Which channel should the videos be posted to?",\r\n                     [(k, f"{p[\'channel_name\']} ({k})") for k, p in answered.items()])\r\n    p = answered[key]\r\n    o = {}\r\n\r\n    genre = ask("\\nQ3. Genre to source trending videos for", p["niche"])\r\n    if genre != p["niche"]:\r\n        o["genre"] = genre\r\n    default_queries = f"{genre} #shorts" if "genre" in o else ", ".join(p["search_queries"])\r\n    queries = split_list(ask("Q4. YouTube search phrases, comma-separated", default_queries))\r\n    if queries != p["search_queries"]:\r\n        o["queries"] = queries\r\n\r\n    o["language"] = ask_choice("\\nQ5. Narration language:", [(lang, lang) for lang in LANGUAGES], p["language"])\r\n    voices = VOICE_CHOICES[o["language"]]\r\n    current_voice = p["voice"] if p["voice"] in voices else DEFAULT_VOICES[(o["language"], p["made_for_kids"])]\r\n    o["voice"] = ask_choice("\\nQ6. Narrator voice:", [(v, v) for v in voices], current_voice)\r\n    o["voice_rate"] = ask_choice("\\nQ7. Speaking speed:", [\r\n        ("-15%", "-15%  slow and very clear"), ("-5%", "-5%   clear (recommended)"),\r\n        ("+0%", "+0%   natural"), ("+10%", "+10%  brisk")], p["voice_rate"] if p["voice_rate"] in SPEEDS else "-5%")\r\n\r\n    o["videos"] = ask_int("\\nQ15. How many videos?", p["max_videos_per_run"], 1, MAX_VIDEOS_PER_DAY)\r\n    when = ask_choice("\\nWhen should they go live?", [\r\n        ("schedule", "Spaced out: first video at a set time, then one every 15 mins / 30 mins / 1 hour / 3 hours"),\r\n        ("now", "All immediately after upload")], "schedule" if p["posting"]["first_post_time"] else "now")\r\n    if when == "schedule":\r\n        o["first_post"] = ask(f"Q13. First video goes live at (HH:MM, {p[\'schedule\'][\'timezone\']})",\r\n                              p["posting"]["first_post_time"] or "", validate_hhmm)\r\n        current_freq = next((n for n, m in FREQUENCIES.items() if m == p["posting"]["frequency_minutes"]), "1 hour")\r\n        o["frequency"] = ask_choice("\\nQ14. Gap between videos:", [(f, f) for f in FREQUENCIES], current_freq)\r\n    else:\r\n        o["post_now"] = True\r\n    o["privacy"] = ask_choice("\\nQ18. Visibility:", [(v, v) for v in ("public", "unlisted", "private")],\r\n                              p["privacy_status"])\r\n    dry_run = ask_yes_no("\\nQ19. Test run? (make the videos but do NOT upload)", p["test_run"])\r\n\r\n    heading("SUMMARY")\r\n    preview = copy.deepcopy(p)\r\n    apply_overrides(preview, o)\r\n    print(f" Channel:  {key} ({p[\'channel_name\']})")\r\n    print(f" Genre:    {preview[\'niche\']}")\r\n    print(f" Search:   {\', \'.join(preview[\'search_queries\'])}")\r\n    print(f" Voice:    {preview[\'voice\']} {preview[\'voice_rate\']} ({preview[\'language\']})")\r\n    print(f" Plan:     {describe_plan(preview).split(\'| \', 1)[-1]}")\r\n    print(f" Mode:     {\'TEST RUN (no upload)\' if dry_run else \'Upload to YouTube, \' + preview[\'privacy_status\']}")\r\n    if not ask_yes_no("\\nStart now?", True):\r\n        print("Cancelled.")\r\n        return 0\r\n    return run_channels(config, instructions, [key], o, force_dry_run=dry_run, formats=("short",))\r\n\r\n\r\n# ---------- command line ----------\r\n\r\ndef main():\r\n    parser = argparse.ArgumentParser(\r\n        description="Run the YouTube automation using the answers in execution/questions.yaml.",\r\n    )\r\n    parser.add_argument("--channel", help="Run one channel key, or \'all\' (default: every channel with run: true)")\r\n    parser.add_argument("--genre", help="One-off genre to source trending videos for")\r\n    parser.add_argument("--videos", help="One-off number of videos")\r\n    parser.add_argument("--frequency", help="One-off gap between videos: \'15 mins\', \'30 mins\', \'1 hour\' or \'3 hours\'")\r\n    parser.add_argument("--first-post", help="One-off time the first video goes live (HH:MM)")\r\n    parser.add_argument("--post-now", action="store_true", help="One-off: make every video live immediately")\r\n    parser.add_argument("--visibility", choices=["public", "unlisted", "private"], help="One-off visibility")\r\n    parser.add_argument("--dry-run", action="store_true", help="Make the videos but do not upload")\r\n    parser.add_argument("--format", choices=["both", "short", "long"], default="both",\r\n                        help="Which videos to make: Shorts, long videos, or both (default)")\r\n    parser.add_argument("--ask", action="store_true", help="Answer the questions interactively for a one-off run")\r\n    parser.add_argument("--scheduled", action="store_true", help="Run channels due for --cron (used by GitHub)")\r\n    parser.add_argument("--due", action="store_true", help="Only print channels due for --cron (used by GitHub)")\r\n    parser.add_argument("--cron", help="The cron expression that triggered a scheduled GitHub run")\r\n    parser.add_argument("--authorize", metavar="CHANNEL", help="Sign in to YouTube for a channel")\r\n    parser.add_argument("--check", action="store_true", help="Validate pages, show plan and usage, update schedule")\r\n    parser.add_argument("--list", action="store_true", help="Show channels and their posting plans")\r\n    args = parser.parse_args()\r\n\r\n    try:\r\n        config, instructions = load_brain()\r\n    except (ValueError, FileNotFoundError) as e:\r\n        print(e)\r\n        return 2\r\n\r\n    if args.due or args.scheduled:\r\n        if not args.cron:\r\n            print("--cron is required with --due and --scheduled.")\r\n            return 2\r\n        keys = due_profiles(config, args.cron)\r\n        if args.due:\r\n            print(" ".join(keys))\r\n            return 0\r\n        if not keys:\r\n            print("No channels are due for this schedule.")\r\n            return 0\r\n        return run_channels(config, instructions, keys, force_dry_run=args.dry_run, cron=args.cron)\r\n\r\n    if args.check:\r\n        check(config)\r\n        return 0\r\n    if args.list:\r\n        list_channels(config)\r\n        return 0\r\n    if args.authorize:\r\n        return 0 if authorize(config, args.authorize) else 1\r\n    if args.ask:\r\n        return ask_mode(config, instructions)\r\n\r\n    # GitHub passes empty strings for form fields left blank, so treat "" as not given\r\n    overrides = {\r\n        "genre": args.genre or None,\r\n        "videos": int(args.videos) if args.videos else None,\r\n        "frequency": args.frequency or None,\r\n        "first_post": args.first_post or None,\r\n        "post_now": args.post_now,\r\n        "privacy": args.visibility,\r\n    }\r\n    if overrides["frequency"] and overrides["frequency"] not in FREQUENCIES:\r\n        print(f"--frequency must be one of: {\', \'.join(FREQUENCIES)}")\r\n        return 2\r\n    if overrides["first_post"] and validate_hhmm(overrides["first_post"]):\r\n        print(f"--first-post: {validate_hhmm(overrides[\'first_post\'])}")\r\n        return 2\r\n    if overrides["videos"] is not None and not 1 <= overrides["videos"] <= MAX_VIDEOS_PER_DAY:\r\n        print(f"--videos must be from 1 to {MAX_VIDEOS_PER_DAY}")\r\n        return 2\r\n\r\n    if args.channel and args.channel != "all":\r\n        if args.channel not in config["profiles"]:\r\n            print(f"\'{args.channel}\' is not on the channel page. Channels: {\', \'.join(config[\'profiles\'])}")\r\n            return 2\r\n        if not config["profiles"][args.channel]["has_answers"]:\r\n            print(f"\'{args.channel}\' has no answers in questions.yaml yet.")\r\n            return 2\r\n        keys = [args.channel]\r\n    else:\r\n        keys = [k for k, p in config["profiles"].items() if p["enabled"]]\r\n        if not keys:\r\n            print("No channel has run: true in questions.yaml.")\r\n            return 1\r\n    # Long videos first, so they are ready well before their go-live times\r\n    formats = ("long", "short") if args.format == "both" else (args.format,)\r\n    return run_channels(config, instructions, keys, overrides, force_dry_run=args.dry_run, formats=formats)\r\n\r\n\r\nif __name__ == "__main__":\r\n    try:\r\n        sys.exit(main())\r\n    except (KeyboardInterrupt, EOFError):\r\n        print("\\nCancelled.")\r\n        sys.exit(1)\r\n',
    'execution/execution.md': '# Execution Guide\r\n\r\nEverything you need to run the YouTube automation lives in this folder:\r\n\r\n| File | Purpose |\r\n|---|---|\r\n| `execution.py` | **The only file you run.** Works from GitHub, any IDE, a terminal, or Copilot. |\r\n| `execution.md` | This guide: setup, rules and how to run. |\r\n| `questions.yaml` | **The answers.** What and when each channel posts: genre, language, voice, how many videos, how often. Options are written beside each question. |\r\n| `channels.yaml` | **The channel page.** Who each channel is: name, made for kids, watermark, category. |\r\n\r\n`BRAIN.md` (one folder up) holds the global rules every channel shares: editing style, storage folders and AI writing instructions. You rarely need to touch it.\r\n\r\n---\r\n\r\n## Golden Rules\r\n\r\n1. **Create each YouTube channel yourself**, then list it in `channels.yaml` and answer its questions in `questions.yaml` under the **same key**.\r\n2. **`execution.py` always reads `questions.yaml`.** To change what a channel does, change the answers there, not the code.\r\n3. **Copy options exactly** from the comments: quotes, spaces and capital letters matter (`"1 hour"`, `"Telugu"`, `"-5%"`).\r\n4. **After any change to either file, run** `python execution/execution.py --check`, **then push to GitHub.** The check validates both files, shows each channel\'s posting plan and daily YouTube usage, and updates the GitHub schedule.\r\n5. **Every channel needs a YouTube login** (`token_<key>.json`) before it can upload. See *Adding a Channel*, step 4. Sign in with **the Google account that owns the channel**. This can be a different account from the one that owns the Google Cloud project; if the OAuth consent screen is still in Testing mode, add that account under **Test users**.\r\n6. **Test first:** set `test_run: true` for a new channel. It makes the videos without uploading them.\r\n7. **Stay within YouTube\'s daily limits:** 100 uploads and 100 searches per day, shared by all channels. `--check` shows your total.\r\n8. **Never commit secrets.** `.env`, `client_secret.json` and `token_*.json` are git-ignored.\r\n\r\n---\r\n\r\n## What Happens When the Job Runs\r\n\r\n```mermaid\r\nflowchart TD\r\n    A[GitHub schedule fires at a channel\'s fetch_time] --> B[Set up: Python, FFmpeg, rclone, keys]\r\n    B --> C[Pull YouTube logins and manifest from Google Drive]\r\n    C --> D[execution.py reads channels.yaml + questions.yaml + BRAIN.md]\r\n    D --> E[Mark lost half-finished videos expired]\r\n    E --> F{Long videos first, then Shorts}\r\n    F --> G[Scout, agent 1: trending topic on YouTube]\r\n    G --> H[Script and voice, agent 3: Gemini script, narration, sentence timings, length check, scenes]\r\n    H --> I[Footage, agent 2: one matching stock clip per scene]\r\n    I --> J[Editor, agent 4: FFmpeg montage, watermark, narration, end card]\r\n    J --> K[Publisher, agent 5: channel check, title, chunked upload with go-live time]\r\n    K --> F\r\n    F -->|both formats done| L[Cleanup, agent 6]\r\n    L --> M[Telegram alert with links, agent 7]\r\n    M --> N[Sync manifest and unpublished videos back to Google Drive]\r\n```\r\n\r\n### The GitHub job ([daily_youtube_agents.yml](../../.github/workflows/daily_youtube_agents.yml))\r\n\r\n| Step | What it does |\r\n|---|---|\r\n| 1. Checkout | Gets the latest code from `main` |\r\n| 2. Python 3.11 | Sets up Python |\r\n| 3. Decide which channels are due | Scheduled run: the channel(s) whose `fetch_time` matches. Manual run: the channel you typed. Nothing due means the job stops here at almost no cost. |\r\n| 4. Install FFmpeg & rclone | Video tools and the Google Drive connection |\r\n| 5. Install dependencies | Everything in `requirements.txt` |\r\n| 6. Restore API keys | Writes the GitHub secrets into `.env` and `client_secret.json` |\r\n| 7. Pull from Google Drive | YouTube logins (`00_tokens`), the manifest (`01_manifests`) and any finished-but-unpublished videos |\r\n| 8. Run the pipeline | `python execution/execution.py --scheduled --cron "<time>"` (or your manual options). See below. |\r\n| 9. Sync back to Google Drive | Saves the updated manifest, logins and any unpublished videos for the next run. Runs even if step 8 failed. |\r\n\r\n### The pipeline (step 8), for each due channel\r\n\r\n1. **Clear lost work:** unfinished videos whose files are gone are marked `expired`, because GitHub starts every run on a fresh machine.\r\n2. **Long videos, then Shorts.** Long videos go first so they are uploaded hours before their go-live times. For each format:\r\n\r\n| Agent | Does | Uses |\r\n|---|---|---|\r\n| **1. Scout** ([agent_1_scout.py](../agents/agent_1_scout.py)) | Finds trending YouTube videos on your `search_phrases` (Shorts for Shorts, 4 to 20 minute videos for long ones), in your `language`, rotating phrases and avoiding recent or excluded source channels. Only the topic is used, never the video itself. | YouTube Data API |\r\n| **3. Script & Voice** ([agent_3_voiceover.py](../agents/agent_3_voiceover.py)) | Gemini writes an original script, and in the same request the upload title, description, hashtags and 5 footage terms for the whole topic (one request instead of three). Hook first; long videos get 3 to 5 parts, a recap and a comment question. Narrated with your `voice` and `voice_speed`, recording when each sentence is spoken. If the narration is longer than allowed, it\'s shortened and narrated again. Then it\'s split into scenes: 3 per Short, ~15 seconds each in long videos. | Gemini, edge-tts |\r\n| **2. Footage** ([agent_2_downloader.py](../agents/agent_2_downloader.py)) | Gemini reads each scene and picks a specific search term (news channels may name public figures) plus a generic backup. One clip per scene comes from Pixabay, cartoon or real per `footage_style`. The log prints a **sync report**: each scene\'s time range, the footage shown and the words spoken. | Gemini, Pixabay |\r\n| **4. Editor** ([agent_4_editor.py](../agents/agent_4_editor.py)) | FFmpeg cuts every clip to its scene\'s narration time and fits it to 1080×1920 (Short) or 1920×1080 (long). It joins them, overlays the watermark, adds only the narration, and appends the LIKE → SUBSCRIBE end card. | FFmpeg |\r\n| **5. Publisher** ([agent_5_publisher.py](../agents/agent_5_publisher.py)) | Confirms the YouTube login is the channel in `channels.yaml`. Uses the title, description and hashtags written with the script, plus the stock-footage credit. If they\'re missing it asks Gemini, and if Gemini is unavailable (quota used up) it uses the source video\'s title so the finished video still goes out. Uploads in 8 MB resumable chunks, scheduled to go live at its slot. | YouTube Data API |\r\n\r\n3. **6. Cleanup** ([agent_6_cleanup.py](../agents/agent_6_cleanup.py)): on GitHub, deletes clips, narration and published videos. On a laptop, deletes `YouTube_Auto` day folders older than `keep_days`.\r\n4. **7. Telegram** ([agent_7_notifier.py](../agents/agent_7_notifier.py)): when a run starts, one message says it\'s preparing videos (and how late GitHub started it). After each channel finishes, one message per channel lists every uploaded video with its title, link and go-live time, and says if any were not uploaded.\r\n5. **RESULT:** the log ends with how many videos each channel uploaded. If a channel uploaded nothing, the job is marked failed so you notice.\r\n\r\n**Gemini usage:** 1 request per Short (script, title, hashtags and each scene\'s footage terms together) and 2 per long video (script, then per-scene footage terms for its ~20 scenes): about 20 a day for both channels. The free tier allows 20 requests a day **per model**, reset at 12:30 IST, so the 4 models in `ai_models` share the load. Requests are spaced 4 seconds apart. If every model is rate-limited, the run waits one minute and tries again; if they\'re still limited, the daily quota is used up, so the rest of the run skips Gemini (footage falls back to the topic terms, titles to the source video\'s title).\r\n\r\n### A typical day\r\n\r\nBoth channels run together three times a day. Morning and afternoon runs make 1 long video and 2 Shorts per channel; the evening run makes 2 Shorts per channel. Each run sends a Telegram "run started" message, then one message per channel when its videos are uploaded.\r\n\r\n| Run (IST) | Frontline Ledger | WonderSprout |\r\n|---|---|---|\r\n| 06:00 morning | long 12:00, Shorts 08:00 and 10:00 | long 11:30, Shorts 08:30 and 10:30 |\r\n| 13:00 afternoon | long 16:30, Shorts 14:00 and 16:00 | long 15:30, Shorts 14:30 and 16:00 |\r\n| 17:00 evening | Shorts 18:00 and 19:00 | Shorts 18:00 and 19:00 |\r\n\r\nYouTube publishes each video at its time even though the GitHub job finished hours earlier.\r\n\r\n**Start times:** GitHub starts scheduled runs late (4 to 5 hours in October 2026), so `github_schedule_lead_minutes` in `BRAIN.md` (265) makes the GitHub schedule fire that much earlier: 01:35, 08:35 and 12:35 IST, so runs start near 06:00, 13:00 and 17:00. If GitHub is ever on time, the run simply starts early; the videos still go live at their times. The start message shows how early or late each run was; if it drifts, change the lead and run `--check`. A go-live time that has already passed by upload time goes live 10 minutes after upload instead, 30 minutes apart.\r\n\r\n**Hashtags:** each video gets up to 8 hashtags in its description (YouTube shows the first three above the title): `#shorts` for Shorts, 5 from Gemini (2 broad, popular ones for the niche and 3 specific to the story), and the hashtags the trending source video uses, minus the source channel\'s own brand tag. The same words, plus the footage topic terms, go into the video\'s search tags. The Telegram message lists them.\r\n\r\n---\r\n\r\n## How Posting Works\r\n\r\nFor each channel, every day it is scheduled (`days`):\r\n\r\n1. **At `fetch_time`**, GitHub starts the pipeline:\r\n   - It finds trending topics for your `genre` and `search_phrases` on YouTube.\r\n   - It downloads matching **free stock clips from Pixabay** (or Pexels). YouTube blocks downloading its videos from cloud servers like GitHub\'s, and stock footage also avoids copyright claims.\r\n   - It writes a script in your `language`, narrates it with your `voice` at your `voice_speed`, and edits the clips into a montage.\r\n2. **It uploads all `videos_per_day` videos at once**, each with its own go-live time: the first at `first_post_time`, then one every `post_frequency`.\r\n3. **YouTube publishes each video exactly at its time**, even though GitHub has already finished.\r\n\r\nExample: `fetch_time "06:00"`, `first_post_time "07:00"`, `post_frequency "1 hour"`, `videos_per_day 12` → videos go live at 07:00, 08:00, 09:00 … 18:00.\r\n\r\n**Several runs a day:** give `fetch_time` a list, e.g. `["06:00", "13:00"]`. `videos_per_day` and `long_videos_per_day` stay day totals; each run makes the videos whose go-live time falls between its fetch time and the next one. `--check` prints each run\'s share, e.g. `Run 06:00 -> 1 long (12:00) + 2 Shorts (08:00, 11:00)`. A one-off run with `--videos`, `--first-post`, `--frequency` or `--post-now` ignores the split and uses the numbers you typed.\r\n\r\n| `post_frequency` | 12 videos starting 07:00 go live |\r\n|---|---|\r\n| `"15 mins"` | 07:00, 07:15 … 09:45 |\r\n| `"30 mins"` | 07:00, 07:30 … 12:30 |\r\n| `"1 hour"` | 07:00, 08:00 … 18:00 |\r\n| `"3 hours"` | 07:00, 10:00 … 16:00 the next day (too long, so `--check` warns you) |\r\n\r\n**Long videos (Q22 to Q24)** are made in the same run, **before** the Shorts, so they\'re ready well ahead of their go-live times. Their length never exceeds the upper number of `long_video_minutes`: if the narration runs long, the script is shortened and narrated again.\r\n\r\n| | Shorts | Long videos |\r\n|---|---|---|\r\n| Shape | Vertical 1080×1920 | Landscape 1920×1080 |\r\n| Length | `video_length_seconds` (15 to 60 s) | `long_video_minutes` (5 to 7 min) |\r\n| Topics from | Trending Shorts | Trending 4 to 20 minute videos on the same search phrases |\r\n| Script | Hook plus one idea | Hook, 3 to 5 parts, recap and a question for comments |\r\n| Footage | 3 scenes, one matching clip each | One matching clip per ~15-second scene (about 20 to 28) |\r\n| Goes live | `first_post_time`, then every `post_frequency` | At each `long_post_times` entry |\r\n\r\nA long video takes roughly 12 minutes to build on GitHub (videos are assembled with FFmpeg for speed). `--check` estimates the monthly GitHub time for all your answers.\r\n\r\n**Every video looks and sounds the same way:**\r\n- **Audio:** only the AI narration; the source video\'s own sound is removed.\r\n- **Watermark:** in the bottom-right corner.\r\n- **End card:** a 3-second closing card with the channel name in large text, a **LIKE** button first, then **SUBSCRIBE**.\r\n  - Change the card\'s length or wording, or turn it off, under `end_card` in `BRAIN.md`.\r\n  - To also show a logo, set `show_logo: true` there. The logo is the channel\'s YouTube profile picture, saved in `GDrive_Mount/YouTube_Automation/00_branding/`, or the image set as `logo_file` in `channels.yaml`.\r\n\r\nIf preparing the videos takes longer than planned, a passed go-live time is replaced by one shortly after upload. Allow at least 30 minutes between `fetch_time` and `first_post_time` (about 3 minutes per Short, 12 per long video).\r\n\r\n---\r\n\r\n## The Questions (`questions.yaml`)\r\n\r\n| # | Question | Field | Options |\r\n|---|---|---|---|\r\n| Q1 | Channel to post to | the key (e.g. `kids_edu`) | Any key from `channels.yaml` |\r\n| Q2 | Include this channel? | `run` | `true` \\| `false` |\r\n| Q3 | Genre to source trending videos for | `genre` | Any text |\r\n| Q4 | YouTube searches that find trending Shorts | `search_phrases` | 1 to 5 lines; add `#shorts` to each |\r\n| Q5 | Narration language | `language` | `"English"` \\| `"Hindi"` \\| `"Telugu"` |\r\n| Q6 | Narrator voice | `voice` | See voices below; must match the language |\r\n| Q7 | Speaking speed | `voice_speed` | `"-15%"` slow and very clear \\| `"-5%"` clear (recommended) \\| `"+0%"` natural \\| `"+10%"` brisk |\r\n| Q8 | Narration style | `tone` | Any text |\r\n| Q9 | Length of each video | `video_length_seconds` | `15` \\| `30` \\| `45` \\| `60` |\r\n| Q10 | Words the script must never use | `avoid_words` | `[]` or `["word1", "word2"]` |\r\n| Q11 | Use trending videos from the last N days | `lookback_days` | `1` to `30` |\r\n| Q12 | When to fetch and prepare videos | `fetch_time` | `"HH:MM"` (24-hour), or a list like `["06:00", "13:00"]` for several runs a day |\r\n| Q13 | When each Short goes live | `short_post_times` | A list like `["08:00", "10:00"]`, one per Short. Or leave it out and use Q13 to Q15 below |\r\n| Q13 | When the first Short goes live | `first_post_time` | `"HH:MM"` |\r\n| Q14 | Gap between Shorts | `post_frequency` | `"15 mins"` \\| `"30 mins"` \\| `"1 hour"` \\| `"3 hours"` |\r\n| Q15 | Shorts to post each day (all runs together) | `videos_per_day` | `1` to `50` |\r\n| Q16 | Which days | `days` | `"daily"` \\| `"weekdays"` \\| `"weekends"` \\| `[mon, wed, fri]` |\r\n| Q17 | Timezone for all times | `timezone` | `"Asia/Kolkata"`, `"America/New_York"`, `"Europe/London"`, … |\r\n| Q18 | Who can see the videos | `visibility` | `"public"` \\| `"unlisted"` \\| `"private"` |\r\n| Q19 | Make videos without uploading | `test_run` | `true` \\| `false` |\r\n| Q20 | YouTube channels never to take videos from | `exclude_sources` | `[]` or `["Channel Name 1", "Channel Name 2"]` |\r\n| Q22 | Long landscape videos per day | `long_videos_per_day` | `0` (none) to `4` |\r\n| Q23 | Length of each long video | `long_video_minutes` | `4` \\| `5` \\| `6` \\| `7` \\| `"4-5"` \\| `"4-6"` \\| `"5-6"` \\| `"5-7"` \\| `"6-7"` (a range gives each video a different length, never above the upper number) |\r\n| Q24 | When each long video goes live | `long_post_times` | one `"HH:MM"` per long video, e.g. `["14:00", "20:00"]` |\r\n| Q21 | Kind of stock clips used | `footage_style` | `"any"` \\| `"animation"` (cartoon) \\| `"film"` (real footage) \\| `"mixed"` (cartoon and real alternate). Pixabay only; Pexels has no cartoon filter. |\r\n\r\n**How source videos are picked:** each run starts from the next search phrase in turn and takes the most-viewed recent Short from each phrase in rotation. Searches favour videos in the channel\'s language. It takes **at most one video per source channel per run**, avoids channels used for any of that channel\'s last 5 videos, and never uses channels in `exclude_sources`. This keeps one big channel from supplying everything.\r\n\r\nDelete a line to use its default. Defaults: English, a natural voice for the language, `-5%` speed (`-15%` for kids), 30-second videos, last 5 days, 1 video, `"1 hour"`, daily, `Asia/Kolkata`, public, uploads on. If `first_post_time` is left out, videos go live as soon as they are uploaded.\r\n\r\n**Voices:**\r\n\r\n| Language | Voice | Style |\r\n|---|---|---|\r\n| English | `en-US-AndrewNeural` | Male, warm, all-rounder |\r\n| English | `en-US-ChristopherNeural` | Male, authoritative, news |\r\n| English | `en-US-GuyNeural` | Male, energetic, sports |\r\n| English | `en-US-AriaNeural` | Female, confident, news |\r\n| English | `en-US-EmmaNeural` | Female, cheerful, kids and education |\r\n| English | `en-US-AnaNeural` | **Child voice** (young girl); best for kids channels |\r\n| English | `en-US-JennyNeural` | Female, friendly, calm |\r\n| English | `en-IN-PrabhatNeural` / `en-IN-NeerjaNeural` | Indian English, male / female |\r\n| Hindi | `hi-IN-MadhurNeural` / `hi-IN-SwaraNeural` | Male / female |\r\n| Telugu | `te-IN-MohanNeural` / `te-IN-ShrutiNeural` | Male / female |\r\n\r\nFor Hindi and Telugu, scripts, titles and descriptions are written in the native script. Write `search_phrases` in whichever language finds the best trending videos for your genre.\r\n\r\n---\r\n\r\n## The Channel Page (`channels.yaml`)\r\n\r\n| Field | Required | Options |\r\n|---|---|---|\r\n| *key* | yes | Lowercase letters, numbers, underscores; starts with a letter; unique |\r\n| `channel_name` | yes | Exactly as on YouTube |\r\n| `channel_url` | yes | The channel link: `https://www.youtube.com/@handle` or `https://www.youtube.com/channel/UC...`. Sign-in and every upload check that the YouTube login is this exact channel, so videos never go to the wrong one. |\r\n| `made_for_kids` | yes | `true` \\| `false` (`true` only for children under 13: legal COPPA setting, limits ads) |\r\n| `watermark_text` | no | Default `@` + channel name |\r\n| `logo_file` | no | Image for the end card, e.g. `"execution/logos/my_logo.png"`. Default: the channel\'s YouTube profile picture |\r\n| `category_id` | no | `"24"` Entertainment (default), `"25"` News & Politics, `"27"` Education (default for kids), `"17"` Sports, `"28"` Science & Technology. The full list is in the file. |\r\n\r\n---\r\n\r\n## One-Time Setup\r\n\r\n| # | Step | How |\r\n|---|---|---|\r\n| 1 | Python environment | `python -m venv C:\\Users\\<you>\\venvs\\yt`, then `C:\\Users\\<you>\\venvs\\yt\\Scripts\\python.exe -m pip install -r requirements.txt`. A short path avoids Windows\' long-path error, and no admin rights are needed. |\r\n| 2 | API keys | Copy `.env.example` to `.env` and fill in `YOUTUBE_API_KEY`, `GEMINI_API_KEY`, and optionally the Telegram values. |\r\n| 3 | Upload permission | Save your Google Cloud **OAuth Desktop client** file as `client_secret.json` in `youtube-automation-agents`. On the OAuth consent screen click **Publish app**; otherwise logins expire every 7 days. |\r\n| 4 | Google Drive | Create the folder `YouTube_Automation/00_tokens/`. |\r\n| 5 | rclone | `rclone config` and create a remote named exactly **`gdrive`** (type: drive). |\r\n| 6 | Stock footage key | Create a free account at [pixabay.com](https://pixabay.com/accounts/register/), open [pixabay.com/api/docs](https://pixabay.com/api/docs/) while logged in, copy the key shown under **Parameters → key**, and add it to `.env` as `PIXABAY_API_KEY`. (A Pexels key in `PEXELS_API_KEY` also works.) |\r\n| 7 | GitHub secrets | Repo → Settings → Secrets and variables → Actions. Add the 7 secrets below. |\r\n\r\n| Secret | Contents |\r\n|---|---|\r\n| `YOUTUBE_API_KEY` | YouTube Data API v3 key |\r\n| `GEMINI_API_KEY` | Gemini API key |\r\n| `PIXABAY_API_KEY` | Pixabay API key (free stock footage). To use Pexels instead, add a `PEXELS_API_KEY` secret and pass it in step 6 of the workflow the same way. |\r\n| `TELEGRAM_BOT_TOKEN` | Telegram bot token |\r\n| `TELEGRAM_CHANNEL_ID` | Telegram channel ID (starts with `-100`) |\r\n| `CLIENT_SECRET_JSON` | Full contents of `client_secret.json` |\r\n| `RCLONE_CONFIG_GDRIVE` | Full contents of the file shown by `rclone config file` |\r\n\r\n---\r\n\r\n## Adding a Channel\r\n\r\n1. **Create the channel on YouTube:** [youtube.com/channel_switcher](https://www.youtube.com/channel_switcher) → **Create a channel**.\r\n2. **`channels.yaml`:** copy the TEMPLATE, paste it under `channels:`, remove the `# `, and fill in the 5 lines.\r\n3. **`questions.yaml`:** copy the TEMPLATE, paste it under `channels:` with the **same key**, remove the `# `, and answer each question by copying an option from its comment.\r\n4. **Sign in to YouTube:** `python execution/execution.py --authorize <key>`. Upload the token file it prints to Google Drive `YouTube_Automation/00_tokens/`.\r\n5. **Check:** `python execution/execution.py --check`\r\n6. **Test:** `python execution/execution.py --channel <key> --dry-run`\r\n7. **Push to GitHub** so the schedule goes live: `git add -A`, `git commit -m "Add <key>"`, `git push`.\r\n\r\nTo pause a channel, set `run: false`. To remove one, delete it from both files. Then run `--check` and push.\r\n\r\n---\r\n\r\n## Ways to Run\r\n\r\n### GitHub (automatic)\r\n\r\nNothing to do. Each channel runs at its `fetch_time` on its `days`.\r\n\r\n### GitHub (manual)\r\n\r\nGitHub → **Actions** → **Daily YouTube Multi-Agent Pipeline** → **Run workflow**. Leave any field blank to use `questions.yaml`.\r\n\r\n| Field | Meaning |\r\n|---|---|\r\n| `channel` | `all` (every channel with `run: true`) or one channel key |\r\n| `genre` | One-off genre |\r\n| `videos` | One-off number of videos |\r\n| `first_post_time` | One-off first go-live time (`HH:MM`) |\r\n| `frequency` | One-off gap: 15 mins, 30 mins, 1 hour or 3 hours |\r\n| `format` | `both` (default), `short` (Shorts only) or `long` (long videos only) |\r\n| `dry_run` | Tick to make videos without uploading |\r\n\r\n### IDE, terminal or Copilot\r\n\r\nOpen `execution.py` and press **Run**, or run this from the `youtube-automation-agents` folder:\r\n\r\n```bash\r\nC:\\Users\\<you>\\venvs\\yt\\Scripts\\python.exe execution/execution.py\r\n```\r\n\r\nIt runs **every channel with `run: true`** using its answers in `questions.yaml`. To have Copilot (or any assistant) run it, say:\r\n\r\n> Run `python execution/execution.py` from the `youtube-automation-agents` folder using `C:\\Users\\<you>\\venvs\\yt\\Scripts\\python.exe`.\r\n\r\n### Interactive one-off (`--ask`)\r\n\r\n`python execution/execution.py --ask` asks the questions on screen, starting from your `questions.yaml` answers, and runs once. `questions.yaml` itself is not changed.\r\n\r\n---\r\n\r\n## Command Reference\r\n\r\n| Command | What it does |\r\n|---|---|\r\n| `python execution/execution.py` | Run every channel with `run: true`, using `questions.yaml` |\r\n| `... --channel KEY` | Run one channel |\r\n| `... --channel all` | Same as no arguments |\r\n| `... --genre "cricket highlights"` | One-off genre (search becomes `"<genre> #shorts"`) |\r\n| `... --videos 6` | One-off number of videos |\r\n| `... --first-post "09:00"` | One-off first go-live time |\r\n| `... --frequency "30 mins"` | One-off gap: `"15 mins"`, `"30 mins"`, `"1 hour"` or `"3 hours"` |\r\n| `... --post-now` | One-off: every video goes live as soon as it is uploaded |\r\n| `... --visibility unlisted` | One-off visibility: `public`, `unlisted` or `private` |\r\n| `... --dry-run` | Make videos, don\'t upload |\r\n| `... --format short` / `--format long` | Make only Shorts, or only long videos (default: both) |\r\n| `python execution/execution.py --ask` | Answer the questions on screen for a one-off run |\r\n| `python execution/execution.py --check` | Validate both files, show plans and YouTube usage, update the GitHub schedule |\r\n| `python execution/execution.py --list` | Show channels, plans and YouTube login status |\r\n| `python execution/execution.py --authorize KEY` | Sign in to YouTube for a channel |\r\n\r\n---\r\n\r\n## Where the Footage Comes From\r\n\r\nSet under `footage` in `BRAIN.md`:\r\n\r\n| `source` | What it does | Works on GitHub? |\r\n|---|---|---|\r\n| `"stock"` (default) | The script is written and narrated first, and the narration is split into scenes using the voice\'s sentence timings (3 scenes in a Short, about one every 15 seconds in a long video). Gemini picks a search term from **each scene\'s own words**, one matching clip per scene is downloaded from Pixabay or Pexels (`provider`), and each clip plays exactly while its scene is narrated. Descriptions credit the site and the contributors, as both sites ask. | Yes |\r\n| `"youtube"` | Re-uses the trending video itself. | **No.** YouTube blocks downloads from cloud servers ("Sign in to confirm you\'re not a bot"). Works only when run from your laptop. |\r\n\r\n`clips_per_video` sets how many clips each video uses (default 3). The free limits (Pixabay: 100 requests a minute; Pexels: 200 an hour) are far more than 14 videos a day needs.\r\n\r\n## Where Video Files Are Kept\r\n\r\n| Run from | Downloaded videos | Narration and final (uploaded) videos | Deleted |\r\n|---|---|---|---|\r\n| Your laptop / IDE / Copilot | `H:\\My Drive\\YouTube_Auto\\<YYYY-MM-DD>\\download\\` (Google Drive) | `H:\\My Drive\\YouTube_Auto\\<YYYY-MM-DD>\\upload\\` | Whole day folders older than 2 days, automatically at the end of each run |\r\n| GitHub | Temporary folders on GitHub\'s machine | Temporary folders on GitHub\'s machine | Right after upload; the machine is wiped after every run |\r\n\r\nChange the folder or the number of days under `local_media` in `BRAIN.md` (`root`, `keep_days`). If Google Drive for Desktop isn\'t running (no `H:` drive), that run uses `C:\\Users\\<you>\\YouTube_Auto` instead. Files in the Google Drive folder count toward your Drive storage, so the 2-day limit also keeps Drive from filling up. To clear space by hand, delete any day folder you no longer need; videos from that day that weren\'t uploaded yet are skipped automatically.\r\n\r\nThe manifest, YouTube logins and logos always stay in `GDrive_Mount/YouTube_Automation/`, because GitHub runs share them through Google Drive.\r\n\r\n## Good to Know\r\n\r\n- **GitHub may start a scheduled run hours after its scheduled time** (4 to 5 hours in October 2026). `github_schedule_lead_minutes` in `BRAIN.md` compensates (see "A typical day"). Future go-live times are always exact, because YouTube publishes them.\r\n- **Public repository:** Actions minutes are unlimited and secrets stay hidden (GitHub never shows them, masks them in logs, and doesn\'t give them to pull requests from forks). Run logs are public, so they must never print key values; the code masks them.\r\n- **The workflow file stores times in UTC**, so 06:00 IST appears as `30 0 * * *`. `--check` handles this.\r\n- **Daylight saving:** India has none. For timezones that do, run `--check` and push after each clock change.\r\n- **GitHub free minutes:** private repos get 2,000 a month. A Short takes about 3 minutes to build and a long video about 12. Run `--check` to see the estimate for your answers. If it\'s near or over 2,000, lower the counts or make the repository public; public repos have unlimited free minutes, and your keys stay safe in GitHub secrets either way.\r\n- **Test-run videos are kept** at "edited" and are uploaded by that channel\'s next real run.\r\n\r\n## Troubleshooting\r\n\r\n| Problem | Fix |\r\n|---|---|\r\n| "Please fix these problems" | Each line names the file, channel and field. Copy the correct option from the comment beside it. |\r\n| "No YouTube login file" | `--authorize <key>`, then upload the token to Drive `YouTube_Automation/00_tokens/`. |\r\n| "You signed in to \'...\' but \'<key>\' is ..." | You picked a different channel in the browser. Run `--authorize <key>` again and choose the channel matching `channel_url`. |\r\n| "Access blocked" / "app has not completed verification" when signing in | The account that owns the channel isn\'t a test user. Google Cloud Console → OAuth consent screen → add it under **Test users**, or click **Publish app**. |\r\n| "login is missing or expired" on GitHub | Same as above. If it happens weekly, publish the OAuth consent screen (One-Time Setup, step 3). |\r\n| "Cannot start: No .env file" | Copy `.env.example` to `.env` and fill in the keys. |\r\n| `--check` warns about YouTube usage | Lower `videos_per_day` or the number of `search_phrases`, or request more quota in Google Cloud Console. |\r\n| `pip` says "filename too long" | Use a short-path venv (One-Time Setup, step 1). |\r\n| "429 RESOURCE_EXHAUSTED" from Gemini | The Gemini quota is used up (free tier: 20 requests a day per model, reset at 12:30 IST). The run waits one minute and tries again once; if it\'s still limited, the rest of the run skips Gemini (footage uses topic terms, titles use the source video\'s title), so finished videos still upload. If it happens every day, use a paid Gemini key or fewer videos. |\r\n| "The user has exceeded the number of videos they may upload" | YouTube\'s daily upload limit for that channel (low for new, unverified channels). Verify the channel by phone at youtube.com/verify. The video stays queued and uploads on a later run. |\r\n| Runs start far from 06:00 / 13:00 / 17:00 | GitHub\'s delay changed. The Telegram start message shows how early or late; change `github_schedule_lead_minutes` in `BRAIN.md`, run `--check` and push. |\r\n| Narration fails | The free voice service occasionally changes. Run `pip install -U edge-tts`. Videos stay queued and retry on the next run. |\r\n',
    'execution/channels.yaml': '# =====================================================================\n#  CHANNEL PAGE  -  who each channel is\n#  Create the channel on YouTube yourself first, then list it here.\n#  What and when each channel posts is answered in: execution/questions.yaml\n#  Full rules: execution/execution.md\n# =====================================================================\n#\n#  RULES\n#    - The channel key (e.g. geopolitics_war) must be lowercase letters,\n#      numbers and underscores, start with a letter, and be unique.\n#      Use the SAME key in questions.yaml.\n#    - Indent with spaces, never tabs.\n#    - After any change run:  python execution/execution.py --check\n# =====================================================================\n\nchannels:\n\n  geopolitics_war:\n    channel_name: "Frontline Ledger TT83"                            # REQUIRED: exactly as on YouTube\n    channel_url: "https://www.youtube.com/@frontline-ledger-tt83"    # REQUIRED: channel link; uploads only go ahead if the YouTube login matches it\n    made_for_kids: false                                             # REQUIRED: true | false  (true only for children under 13, legal COPPA setting)\n    watermark_text: "@frontline-ledger-tt83"                         # optional: default is @ + channel name\n    category_id: "25"                                                # optional: see category list below (default "24", or "27" for kids)\n\n  kids_edu:\n    channel_name: "WonderSprout Kids TT83"\n    channel_url: "https://www.youtube.com/channel/UCf9u1ZaejKPPA-oOD8oXVfg"\n    made_for_kids: true\n    watermark_text: "WonderSprout Kids"\n    category_id: "27"\n\n# =====================================================================\n#  TEMPLATE  (copy, paste under "channels:", remove the "# ")\n# =====================================================================\n#\n#  my_channel_key:\n#    channel_name: "Exact Channel Name On YouTube"\n#    channel_url: "https://www.youtube.com/@myhandle"     # or https://www.youtube.com/channel/UC...\n#    made_for_kids: false\n#    watermark_text: "@MyHandle"\n#    category_id: "24"\n#    logo_file: "execution/logos/my_logo.png"   # optional: end-card logo; default is the channel\'s YouTube profile picture\n#\n#  CATEGORY OPTIONS (category_id):\n#    "1" Film & Animation   "2" Autos & Vehicles   "10" Music        "15" Pets & Animals\n#    "17" Sports            "19" Travel & Events   "20" Gaming       "22" People & Blogs\n#    "23" Comedy            "24" Entertainment     "25" News & Politics\n#    "26" Howto & Style     "27" Education         "28" Science & Technology\n',
    'execution/questions.yaml': '# =====================================================================\r\n#  EXECUTION QUESTIONS  -  what and when each channel posts\r\n#\r\n#  execution.py reads this file every time it runs: from GitHub, from an\r\n#  IDE, from a terminal, or when you ask Copilot to "run execution.py".\r\n#  Answer the questions once per channel. The options for each question\r\n#  are in the comment beside it: copy one option and paste it as the value.\r\n#\r\n#  HOW POSTING WORKS\r\n#    At fetch_time the pipeline finds trending videos, writes and narrates\r\n#    a script for each, edits them, and uploads them all to YouTube with a\r\n#    go-live time: the first at first_post_time, then one every\r\n#    post_frequency, until videos_per_day are scheduled.\r\n#    Example: fetch_time "06:00", first_post_time "07:00", post_frequency\r\n#    "1 hour", videos_per_day 12  ->  videos go live 07:00, 08:00 ... 18:00.\r\n#\r\n#    SEVERAL RUNS A DAY: give fetch_time a list, e.g. ["06:00", "13:00"].\r\n#    The day\'s videos (Shorts and long) are shared between the runs: each\r\n#    run makes the videos whose go-live time falls before the next run.\r\n#    Example: fetch ["06:00", "13:00", "17:00"],\r\n#    short_post_times ["08:00", "10:00", "14:00", "16:00", "18:00", "19:00"],\r\n#    long_post_times ["12:00", "16:30"]\r\n#      ->  06:00 run: Shorts 08:00 and 10:00, long 12:00\r\n#          13:00 run: Shorts 14:00 and 16:00, long 16:30\r\n#          17:00 run: Shorts 18:00 and 19:00 (no long video in its window)\r\n#    fetch_time is when you want a run to START. GitHub starts scheduled\r\n#    runs hours late, so the GitHub schedule fires earlier by\r\n#    github_schedule_lead_minutes (BRAIN.md). A go-live time that has\r\n#    already passed by upload time goes live soon after upload instead.\r\n#    Every run sends a Telegram message when it starts, then one message\r\n#    per channel listing the uploaded videos and their go-live times.\r\n#\r\n#  RULES\r\n#    - Channel keys must match execution/channels.yaml exactly.\r\n#    - Put text and times in quotes. Times are 24-hour "HH:MM".\r\n#    - Leave a question out (delete the line) to use its default.\r\n#    - After any change run:  python execution/execution.py --check\r\n#      then push to GitHub so the schedule updates.\r\n#    - YouTube allows 100 uploads and 100 searches per day in total across\r\n#      ALL channels. --check shows how much of that your answers use.\r\n#\r\n#  VOICE OPTIONS (copy the voice name that matches the language)\r\n#    English: "en-US-AndrewNeural"      male, warm, all-rounder\r\n#             "en-US-ChristopherNeural" male, authoritative, news\r\n#             "en-US-GuyNeural"         male, energetic, sports\r\n#             "en-US-AriaNeural"        female, confident, news\r\n#             "en-US-EmmaNeural"        female, cheerful, kids and education\r\n#             "en-US-AnaNeural"         CHILD voice (young girl), best for kids channels\r\n#             "en-US-JennyNeural"       female, friendly, calm\r\n#             "en-IN-PrabhatNeural"     male, Indian English\r\n#             "en-IN-NeerjaNeural"      female, Indian English\r\n#    Hindi:   "hi-IN-MadhurNeural"      male\r\n#             "hi-IN-SwaraNeural"       female\r\n#    Telugu:  "te-IN-MohanNeural"       male\r\n#             "te-IN-ShrutiNeural"      female\r\n# =====================================================================\r\n\r\nchannels:\r\n\r\n  geopolitics_war:                         # Q1. Channel to post to (key from channels.yaml)\r\n    run: true                              # Q2. Include this channel?            Options: true | false\r\n    genre: "Geopolitics of India, Europe, Russia and America, and current and ongoing wars"\r\n                                           # Q3. Genre to source trending videos for (any text)\r\n    search_phrases:                        # Q4. YouTube searches that find trending Shorts (1 to 5 lines; each run starts from the next phrase)\r\n      - "India foreign policy geopolitics news #shorts"\r\n      - "Russia Ukraine war update #shorts"\r\n      - "Europe NATO news #shorts"\r\n      - "America US foreign policy news #shorts"\r\n      - "Middle East war update #shorts"\r\n    language: "English"                    # Q5. Narration language                Options: "English" | "Hindi" | "Telugu"\r\n    voice: "en-US-ChristopherNeural"       # Q6. Narrator voice                    Options: see VOICE OPTIONS above (must match the language)\r\n    voice_speed: "-5%"                     # Q7. Speaking speed                    Options: "-15%" slow & very clear | "-5%" clear (recommended) | "+0%" natural | "+10%" brisk\r\n    tone: "Serious, objective, analytical intelligence briefing."\r\n                                           # Q8. Narration style (any text)\r\n    video_length_seconds: 30               # Q9. Length of each video              Options: 15 | 30 | 45 | 60\r\n    avoid_words: ["dead", "killed", "blood", "massacre"]\r\n                                           # Q10. Words the script must never use  Options: [] for none, or ["word1", "word2"]\r\n    lookback_days: 5                       # Q11. Use trending videos from the last N days   Options: 1 to 30\r\n    fetch_time: ["06:00", "13:00", "17:00"]  # Q12. When each run starts           Options: "HH:MM" for one run a day, or ["HH:MM", ...] for several (videos are shared between them)\r\n    short_post_times: ["08:00", "10:00", "14:00", "16:00", "18:00", "19:00"]\r\n                                           # Q13. When each Short goes live (one per Short; replaces Q13 to Q15 below)   Options: list of "HH:MM"\r\n    # first_post_time: "08:00"             # Q13. Instead of short_post_times: first Short\'s go-live time\r\n    # post_frequency: "3 hours"            # Q14. ...then one every            Options: "15 mins" | "30 mins" | "1 hour" | "3 hours"\r\n    # videos_per_day: 4                    # Q15. ...this many Shorts a day    Options: 1 to 50\r\n    days: "daily"                          # Q16. Which days to post               Options: "daily" | "weekdays" | "weekends" | [mon, wed, fri]\r\n    timezone: "Asia/Kolkata"               # Q17. Timezone for all times above     Options: "Asia/Kolkata" | "America/New_York" | "Europe/London" | ...\r\n    visibility: "public"                   # Q18. Who can see the videos           Options: "public" | "unlisted" | "private"\r\n    test_run: false                        # Q19. Make videos without uploading    Options: true | false\r\n    exclude_sources: []                    # Q20. YouTube channels never to take videos from   Options: [] | ["Channel Name 1", "Channel Name 2"]\r\n    footage_style: "film"                  # Q21. Kind of stock clips used          Options: "any" | "animation" (cartoon) | "film" (real footage) | "mixed" (alternate)\r\n    long_videos_per_day: 2                 # Q22. Long landscape videos per day (all runs together)   Options: 0 (none) to 4\r\n    long_video_minutes: "5-7"              # Q23. Length of each long video         Options: 4 | 5 | 6 | 7 | "4-5" | "4-6" | "5-6" | "5-7" | "6-7" (a range varies each video; never longer than its upper number)\r\n    long_post_times: ["12:00", "16:30"]    # Q24. When each long video goes live    Options: one "HH:MM" per long video, e.g. ["12:00", "20:00"]\r\n\r\n  kids_edu:                                # Q1\r\n    run: true                              # Q2.  Options: true | false\r\n    genre: "Kids entertainment and education: funny cartoon stories, silly animal adventures, and amazing facts"\r\n    search_phrases:\r\n      - "funny cartoon story for kids #shorts"\r\n      - "amazing animal facts for kids #shorts"\r\n      - "animated kids story #shorts"\r\n      - "fun science facts kids #shorts"\r\n      - "silly animals cartoon for kids #shorts"\r\n    language: "English"                    # Q5.  Options: "English" | "Hindi" | "Telugu"\r\n    voice: "en-US-AnaNeural"               # Q6.  Options: see VOICE OPTIONS above\r\n    voice_speed: "-5%"                     # Q7.  Options: "-15%" | "-5%" | "+0%" | "+10%"\r\n    tone: "A cheerful, excited kid talking to other kids: playful and funny, tells silly short stories or amazing facts, short punchy sentences, lots of \'Whoa!\' and \'Guess what?\'"\r\n    video_length_seconds: 30               # Q9.  Options: 15 | 30 | 45 | 60\r\n    avoid_words: []                        # Q10. Options: [] | ["word1", "word2"]\r\n    lookback_days: 5                       # Q11. Options: 1 to 30\r\n    fetch_time: ["06:00", "13:00", "17:00"]  # Q12. Options: "HH:MM" | ["HH:MM", ...]\r\n    short_post_times: ["08:30", "10:30", "14:30", "16:00", "18:00", "19:00"]\r\n                                           # Q13. Options: list of "HH:MM", one per Short\r\n    days: "daily"                          # Q16. Options: "daily" | "weekdays" | "weekends" | [mon, wed, fri]\r\n    timezone: "Asia/Kolkata"               # Q17\r\n    visibility: "public"                   # Q18. Options: "public" | "unlisted" | "private"\r\n    test_run: false                        # Q19. Options: true | false\r\n    exclude_sources: []                    # Q20. Options: [] | ["Channel Name 1", "Channel Name 2"]\r\n    footage_style: "mixed"                 # Q21. Options: "any" | "animation" | "film" | "mixed" (cartoon and real clips alternate)\r\n    long_videos_per_day: 2                 # Q22. Options: 0 (none) to 4\r\n    long_video_minutes: "4-6"              # Q23. Options: 4 | 5 | 6 | 7 | "4-5" | "4-6" | "5-6" | "5-7" | "6-7"\r\n    long_post_times: ["11:30", "15:30"]    # Q24. Options: one "HH:MM" per long video\r\n\r\n# =====================================================================\r\n#  TEMPLATE  (copy, paste under "channels:", remove the "# ", answer each)\r\n# =====================================================================\r\n#\r\n#  my_channel_key:                         # Q1. same key as in channels.yaml\r\n#    run: true                             # Q2. true | false\r\n#    genre: "cricket highlights"           # Q3. any text\r\n#    search_phrases:                       # Q4. 1 to 5 lines\r\n#      - "cricket highlights #shorts"\r\n#      - "ipl best moments #shorts"\r\n#    language: "Telugu"                    # Q5. "English" | "Hindi" | "Telugu"\r\n#    voice: "te-IN-MohanNeural"            # Q6. see VOICE OPTIONS (must match language)\r\n#    voice_speed: "-5%"                    # Q7. "-15%" | "-5%" | "+0%" | "+10%"\r\n#    tone: "Energetic sports commentary."  # Q8. any text\r\n#    video_length_seconds: 30              # Q9. 15 | 30 | 45 | 60\r\n#    avoid_words: []                       # Q10. [] | ["word1", "word2"]\r\n#    lookback_days: 3                      # Q11. 1 to 30\r\n#    fetch_time: "06:00"                   # Q12. "HH:MM" | ["HH:MM", "HH:MM"]\r\n#    short_post_times: []                  # Q13. list of "HH:MM" (one per Short), or leave out and use the next 3 lines\r\n#    first_post_time: "07:00"              # Q13. "HH:MM"\r\n#    post_frequency: "1 hour"              # Q14. "15 mins" | "30 mins" | "1 hour" | "3 hours"\r\n#    videos_per_day: 8                     # Q15. 1 to 50\r\n#    days: "daily"                         # Q16. "daily" | "weekdays" | "weekends" | [mon, wed, fri]\r\n#    timezone: "Asia/Kolkata"              # Q17. timezone name\r\n#    visibility: "public"                  # Q18. "public" | "unlisted" | "private"\r\n#    test_run: false                       # Q19. true | false\r\n#    exclude_sources: []                   # Q20. [] | ["Channel Name 1", "Channel Name 2"]\r\n#    footage_style: "any"                  # Q21. "any" | "animation" | "film" | "mixed"\r\n#    long_videos_per_day: 0                # Q22. 0 to 4\r\n#    long_video_minutes: 6                 # Q23. 4 | 5 | 6 | 7 | "4-5" | "4-6" | "5-6" | "5-7" | "6-7"\r\n#    long_post_times: []                   # Q24. one "HH:MM" per long video, e.g. ["14:00", "20:00"]\r\n',
    '../.github/workflows/daily_youtube_agents.yml': 'name: Daily YouTube Multi-Agent Pipeline\n\non:\n  schedule:\n    # BEGIN CHANNEL SCHEDULE (fetch times from execution/questions.yaml, updated by: python execution/execution.py --check)\n    - cron: \'5 3 * * *\'\n    - cron: \'5 7 * * *\'\n    - cron: \'5 20 * * *\'\n    # END CHANNEL SCHEDULE\n  workflow_dispatch:\n    inputs:\n      channel:\n        description: \'Channel key, or "all" for every channel with run: true. Blank fields below use execution/questions.yaml\'\n        required: true\n        default: \'all\'\n        type: string\n      genre:\n        description: \'One-off genre to source trending videos for\'\n        required: false\n        type: string\n      videos:\n        description: \'One-off number of videos (1 to 50)\'\n        required: false\n        type: string\n      first_post_time:\n        description: \'One-off time the first video goes live, HH:MM in the channel timezone\'\n        required: false\n        type: string\n      frequency:\n        description: \'One-off gap between videos\'\n        required: false\n        default: \'from questions.yaml\'\n        type: choice\n        options:\n          - \'from questions.yaml\'\n          - \'15 mins\'\n          - \'30 mins\'\n          - \'1 hour\'\n          - \'3 hours\'\n      format:\n        description: \'Which videos to make\'\n        required: false\n        default: \'both\'\n        type: choice\n        options:\n          - \'both\'\n          - \'short\'\n          - \'long\'\n      dry_run:\n        description: \'Test run: make the videos but do not upload\'\n        required: false\n        default: false\n        type: boolean\n\nconcurrency:\n  group: youtube-pipeline\n  cancel-in-progress: false\n\njobs:\n  run-youtube-agents:\n    runs-on: ubuntu-latest\n    timeout-minutes: 240\n    defaults:\n      run:\n        working-directory: youtube-automation-agents\n\n    steps:\n      - name: 1. Checkout Repository Code\n        uses: actions/checkout@v7\n\n      - name: 2. Set Up Python 3.11\n        uses: actions/setup-python@v7\n        with:\n          python-version: \'3.11\'\n          cache: \'pip\'\n          cache-dependency-path: youtube-automation-agents/requirements.txt\n\n      - name: 3. Decide Which Channels Are Due\n        id: plan\n        env:\n          REQUESTED_CHANNEL: ${{ github.event.inputs.channel }}\n          TRIGGER_CRON: ${{ github.event.schedule }}\n        run: |\n          pip install pyyaml\n          if [ -n "$REQUESTED_CHANNEL" ]; then\n            CHANNELS="$REQUESTED_CHANNEL"\n          else\n            CHANNELS="$(python execution/execution.py --due --cron "$TRIGGER_CRON")"\n          fi\n          echo "Channels to run: ${CHANNELS:-none}"\n          echo "channels=$CHANNELS" >> "$GITHUB_OUTPUT"\n\n      - name: 4. Install FFmpeg & Rclone\n        if: steps.plan.outputs.channels != \'\'\n        run: |\n          sudo apt-get update\n          sudo apt-get install -y ffmpeg rclone\n\n      - name: 5. Install Python Dependencies\n        if: steps.plan.outputs.channels != \'\'\n        run: pip install -r requirements.txt\n\n      - name: 6. Restore API Keys\n        if: steps.plan.outputs.channels != \'\'\n        env:\n          YOUTUBE_API_KEY: ${{ secrets.YOUTUBE_API_KEY }}\n          GEMINI_API_KEY: ${{ secrets.GEMINI_API_KEY }}\n          # Stock footage. To use Pexels instead, add a PEXELS_API_KEY secret and pass it here the same way\n          PIXABAY_API_KEY: ${{ secrets.PIXABAY_API_KEY }}\n          TELEGRAM_BOT_TOKEN: ${{ secrets.TELEGRAM_BOT_TOKEN }}\n          TELEGRAM_CHANNEL_ID: ${{ secrets.TELEGRAM_CHANNEL_ID }}\n          CLIENT_SECRET_JSON: ${{ secrets.CLIENT_SECRET_JSON }}\n        run: |\n          echo "YOUTUBE_API_KEY=${YOUTUBE_API_KEY}" >> .env\n          echo "GEMINI_API_KEY=${GEMINI_API_KEY}" >> .env\n          echo "PIXABAY_API_KEY=${PIXABAY_API_KEY}" >> .env\n          echo "TELEGRAM_BOT_TOKEN=${TELEGRAM_BOT_TOKEN}" >> .env\n          echo "TELEGRAM_CHANNEL_ID=${TELEGRAM_CHANNEL_ID}" >> .env\n          echo "${CLIENT_SECRET_JSON}" > client_secret.json\n\n      - name: 7. Pull Channel Logins, Manifest & Prior Edited Videos from Google Drive\n        if: steps.plan.outputs.channels != \'\'\n        env:\n          # Not named RCLONE_CONFIG: rclone reads that variable as the config file\'s path, not its contents\n          GDRIVE_RCLONE_CONF: ${{ secrets.RCLONE_CONFIG_GDRIVE }}\n        run: |\n          mkdir -p ~/.config/rclone\n          printf \'%s\\n\' "${GDRIVE_RCLONE_CONF}" > ~/.config/rclone/rclone.conf\n          chmod 600 ~/.config/rclone/rclone.conf\n          mkdir -p ./GDrive_Mount/YouTube_Automation/00_tokens\n          mkdir -p ./GDrive_Mount/YouTube_Automation/01_manifests\n          mkdir -p ./GDrive_Mount/YouTube_Automation/03_edited_videos\n          rclone copy gdrive:YouTube_Automation/00_tokens ./GDrive_Mount/YouTube_Automation/00_tokens\n          rclone copy gdrive:YouTube_Automation/01_manifests ./GDrive_Mount/YouTube_Automation/01_manifests || true\n          rclone copy gdrive:YouTube_Automation/03_edited_videos ./GDrive_Mount/YouTube_Automation/03_edited_videos || true\n\n      - name: 8. Run the Pipeline (execution/execution.py)\n        if: steps.plan.outputs.channels != \'\'\n        env:\n          EVENT_NAME: ${{ github.event_name }}\n          TRIGGER_CRON: ${{ github.event.schedule }}\n          CHANNEL: ${{ github.event.inputs.channel }}\n          GENRE: ${{ github.event.inputs.genre }}\n          VIDEOS: ${{ github.event.inputs.videos }}\n          FIRST_POST: ${{ github.event.inputs.first_post_time }}\n          FREQUENCY: ${{ github.event.inputs.frequency }}\n          FORMAT: ${{ github.event.inputs.format }}\n          DRY_RUN: ${{ github.event.inputs.dry_run }}\n        run: |\n          if [ "$EVENT_NAME" = "workflow_dispatch" ]; then\n            EXTRA=""\n            if [ "$DRY_RUN" = "true" ]; then EXTRA="--dry-run"; fi\n            if [ "$FREQUENCY" = "from questions.yaml" ]; then FREQUENCY=""; fi\n            python execution/execution.py --channel "$CHANNEL" --genre "$GENRE" --videos "$VIDEOS" \\\n              --first-post "$FIRST_POST" --frequency "$FREQUENCY" --format "${FORMAT:-both}" $EXTRA\n          else\n            python execution/execution.py --scheduled --cron "$TRIGGER_CRON"\n          fi\n\n      - name: 9. Sync Cleaned Folders, Logins & Updated Manifest Back to Google Drive\n        if: always() && steps.plan.outputs.channels != \'\'\n        run: |\n          rclone copy ./GDrive_Mount/YouTube_Automation/00_tokens gdrive:YouTube_Automation/00_tokens\n          rclone copy ./GDrive_Mount/YouTube_Automation/01_manifests gdrive:YouTube_Automation/01_manifests\n          rclone sync ./GDrive_Mount/YouTube_Automation/03_edited_videos gdrive:YouTube_Automation/03_edited_videos\n          rclone delete gdrive:YouTube_Automation/02_raw_videos || true\n          rclone delete gdrive:YouTube_Automation/02_audio_voiceovers || true\n',
}


def build_project():
    for filepath, content in FILES.items():
        dir_name = os.path.dirname(filepath)
        if dir_name:
            os.makedirs(dir_name, exist_ok=True)
        with open(filepath, "w", encoding="utf-8", newline="") as f:
            f.write(content)
        print(f"[+] Created: {filepath}")

    os.makedirs("./GDrive_Mount/YouTube_Automation/00_tokens", exist_ok=True)
    print()
    print("[SUCCESS] Entire Multi-Agent Project & GitHub Action Workflow generated!")


if __name__ == "__main__":
    build_project()
